  ('cpiuris2025::47f9e480479bae026fbe495cc72106ff', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Consumação do Furto', '## Consumação do Furto

O furto pode não se consumir se o crime for interrompido a qualquer momento, e a súmula do STJ estabelece que o furto pode ocorrer mesmo com sistemas de vigilância perfeitos.

### Conceitos
- **Consumação do Furto**: Ocorre quando o delito é completamente realizado.
- **Iter Criminis**: A sequência de fatos que compõe o crime.
- **Pena do Furto**: Aumenta de um terço se praticado durante o repouso noturno.
- **Repouso Noturno**: O intervalo entre o recolhimento para o descanso e o despertar, variável com os costumes locais.
- **Furto**: O crime de roubo ou despojo.
- **Súmula do STJ**: Estabelece que o furto pode ocorrer mesmo com sistemas de vigilância perfeitos.
- **Dosimetria**: A fase da sentença em que se determina a pena.
- **Causa de Aumento de Pena**: Fato que aumenta a pena do crime.

### Referências legais
- Art. 157, § 2º, do Código Penal
- Súmula 434/STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre consumação e interrupção do furto.
- Conheça as causas de aumento de pena, incluindo o repouso noturno.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.89 (2)", "page_number": 89, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 2º, do Código Penal", "Súmula 434/STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T08:21:37.270276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=89", "doc_key": "47f9e480479bae026fbe495cc72106ff"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '1008b08083e26c44283e9075c8f316ca4a321c3cc692ddc9e9606e1b854f9be6'),
  ('cpiuris2025::fa871c334c2feb916dc0a04542672e58', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Causa de aumento do furto', '## Causa de aumento do furto

A causa de aumento do furto ocorre quando o agente cometeu o crime durante a noite, independentemente da presença ou ausência da vítima. A majorante pode ser aplicada ao furto simples ou qualificado, mas não é aplicável ao privilégio do furto privilegiado.

### Conceitos
- **Furto**: crime contra o patrimônio
- **Causa de aumento**: aumento da pena para o agente que cometeu o crime durante a noite
- **Furto privilegiado**: formas especiais do furto, como o furto simples e qualificado

### Referências legais
- Art. 155, § 1º do Código Penal

### Jurisprudência
- {''term'': ''Tema nº 1.087'', ''definition'': ''Entendimento histórico de que a causa de aumento não incide no crime de furto qualificado''}
- {''term'': ''3ª Seção do STJ'', ''definition'': ''Julgamento de recursos especiais repetitivos em 25 de maio de 2022''}

### Dicas de prova
- Diferenciar entre a causa de aumento e o privilégio do furto privilegiado
- Entender que a majorante pode ser aplicada ao furto simples ou qualificado, mas não é aplicável ao privilégio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 155, § 1º do Código Penal"], "jurisprudence": ["{''term'': ''Tema nº 1.087'', ''definition'': ''Entendimento histórico de que a causa de aumento não incide no crime de furto qualificado''}", "{''term'': ''3ª Seção do STJ'', ''definition'': ''Julgamento de recursos especiais repetitivos em 25 de maio de 2022''}"], "confidence": 0.8, "extracted_at": "2026-05-27T08:22:13.958055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=90", "doc_key": "fa871c334c2feb916dc0a04542672e58"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '76a98b5352eecf880bfac875ec42a46eebb44ebeb307cea18fd61e981ef4671d'),
  ('cpiuris2025::a131472031c56ce2a8c21180af28661e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Furto Privilegiado-Qualificado Híbrido', '## Furto Privilegiado-Qualificado Híbrido

O privilégio no furto privilegiado-qualificado híbrido é reconhecível se estiverem presentes a primariedade do agente, o pequeno valor da coisa e a qualificadora for de ordem objetiva.

### Conceitos
- **Furto Privilegiado-Qualificado Híbrido**: Reconhecimento do privilégio no furto privilegiado-qualificado híbrido
- **Primariedade do Agente**: O agente é primário se não tiver antecedentes criminais
- **Pequeno Valor**: O valor da coisa que não excede um salário mínimo vigente na data do fato
- **Qualificadora Objativa**: A qualificação objetiva do crime de furto

### Referências legais
- Art. 155, § 2º, CP

### Jurisprudência
- Súmula 511/STJ

### Dicas de prova
- Distinção entre privilégio e qualificadora objetiva
- Reconhecimento do privilégio no furto privilegiado-qualificado híbrido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 155, § 2º, CP"], "jurisprudence": ["Súmula 511/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T08:22:52.095244+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=90", "doc_key": "a131472031c56ce2a8c21180af28661e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cf90ee8661615f118195f39a7327293b07ffa43c1667caf8ab56917de5883951'),
  ('cpiuris2025::0e35a2ae7d109bbd28a5308b71a018aa', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Furto', '## Furto

O artigo discute as qualificadoras objetivas e subjetivas no crime de furto, destacando que todas as qualificadoras previstas no § 4º do art. 155 são de ordem objetiva, com exceção do abuso de confiança, que se equipara à traição.

### Conceitos
- **Qualificadoras objetivas**: Relacionadas ao modo de execução, tempo, lugar do crime e instrumentos utilizados.
- **Furto**: Crime que envolve a subtração de bens móveis ou imóveis
- **Abuso de confiança**: Traição no relacionamento entre empregado e empregador

### Referências legais
- Art. 155, § 4º, CP
- Súmula 56, STJ
- RE 123456
- Tema repetitivo: Atipicidade da conduta de furto de sinal de TV a cabo

### Jurisprudência
- STJ: Sinal de TV a cabo pode ser equiparado à energia elétrica em casos de captação clandestina
- STF: Atipicidade da conduta de furto de sinal de TV a cabo

### Dicas de prova
- Diferenciar entre qualificadoras objetivas e subjetivas no crime de furto
- Entender o conceito de abuso de confiança e sua relação com a traição
- Avaliar a atipicidade da conduta de furto de sinal de TV a cabo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 155, § 4º, CP", "Súmula 56, STJ", "RE 123456", "Tema repetitivo: Atipicidade da conduta de furto de sinal de TV a cabo"], "jurisprudence": ["STJ: Sinal de TV a cabo pode ser equiparado à energia elétrica em casos de captação clandestina", "STF: Atipicidade da conduta de furto de sinal de TV a cabo"], "confidence": 0.8, "extracted_at": "2026-05-27T08:23:30.717662+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=91", "doc_key": "0e35a2ae7d109bbd28a5308b71a018aa"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '16fab5e57c2a459eeeaf4d78a13ec9315cc5be6993bb88e29ad230a8a9bd9793'),
  ('cpiuris2025::2aa5a67f05f128f351f26bb8557d978a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Débito antes do recebimento da denúncia e punibilidade', '## Débito antes do recebimento da denúncia e punibilidade

O pagamento de débito antes do recebimento da denúncia não configura causa extintiva de punibilidade, mas causa de redução de pena relativa ao arrependimento posterior.

### Conceitos
- **Débito**: obrigação de pagar uma quantia
- **Punibilidade**: estado de pessoa condenada por crime
- **Arrependimento**: atuação da pena em doímo
- **Extintiva**: fim imediato da punibilidade
- **Redução de pena**: menor pena aplicada

### Referências legais
- Art. 16 do CP

### Jurisprudência
- Informativo 645
- Informativo 648

### Dicas de prova
- Diferenciar entre furto e estelionato
- Entender a natureza jurídica da remuneração pela prestação de serviço público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 16 do CP"], "jurisprudence": ["Informativo 645", "Informativo 648"], "confidence": 0.8, "extracted_at": "2026-05-27T08:23:55.077950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=91", "doc_key": "2aa5a67f05f128f351f26bb8557d978a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8214190c9dfc9892780600934f2927359ac60dd6a64dc3d010c7b44d39645869'),
  ('cpiuris2025::a350f744e3b3d74fbce5ae447156cc5a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Furto qualificado', '## Furto qualificado

O furto qualificado ocorre quando a destruição ou rompimento de obstáculo é feito sobre uma coisa exterior ao bem que se pretende subtrair, não aplicando-se a qualificadora em caso de violência contra o próprio objeto.

### Conceitos
- **Furto qualificado**: Ocorre quando a destruição ou rompimento de obstáculo é feito sobre uma coisa exterior ao bem que se pretende subtrair
- **Rompimento de obstáculo**: Destruição ou rompimento de obstáculo sobre uma coisa exterior ao bem que se pretende subtrair
- **Qualificadora**: Caracterização do crime como qualificado, dependendo da comprovação do rompimento de obstáculo por laudo pericial

### Referências legais
- Art. 155, § 4º, I, do CP

### Jurisprudência
- {''term'': ''STJ'', ''definition'': ''Pacificou o entendimento de que a subtração de objeto localizado no interior do veículo automotor mediante rompimento de obstáculo qualifica o furto''}
- {''term'': ''STF'', ''definition'': ''Entendimento prevalente no sentido da incompatibilidade com a aplicação do princípio da insignificância''}

### Dicas de prova
- Pergunta sobre a caracterização do furto qualificado e a importância do rompimento de obstáculo
- Distinção entre violência contra o próprio objeto e a coisa pretendida
- Conhecimento da jurisprudência do STJ e STF sobre o assunto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 155, § 4º, I, do CP"], "jurisprudence": ["{''term'': ''STJ'', ''definition'': ''Pacificou o entendimento de que a subtração de objeto localizado no interior do veículo automotor mediante rompimento de obstáculo qualifica o furto''}", "{''term'': ''STF'', ''definition'': ''Entendimento prevalente no sentido da incompatibilidade com a aplicação do princípio da insignificância''}"], "confidence": 0.8, "extracted_at": "2026-05-27T08:24:46.269317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=92", "doc_key": "a350f744e3b3d74fbce5ae447156cc5a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a74405c6b325ae50bcb6989e36f130965f7d5ebdfeabd414c8146a81b54ca4e2'),
  ('cpiuris2025::e83ddf8851f0c2fa0bbc7f2037aedb3c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Abuso de Confiança', '## Abuso de Confiança

O abuso de confiança é uma circunstância subjetiva que revela a periculosidade do agente que quebra uma relação preexistente de lealdade com a vítima. Exige-se um vínculo especial entre o autor do crime e o ofendido.

### Conceitos
- **Abuso de confiança**: Circunstância subjetiva que revela a periculosidade do agente que quebra uma relação preexistente de lealdade com a vítima.
- **Vínculo especial**: Relação entre o autor do crime e o ofendido que exige um grau de confiança ou lealdade
- **Expectativa da lealdade**: A expectativa de lealdade que se esperava em uma relação preexistente entre o agente e a vítima

### Referências legais
- Art. 149, § 2º, CP

### Dicas de prova
- Distinção entre empregado que furta dinheiro e funcionário de confiança
- Importância do vínculo especial e da expectativa da lealdade em relação ao abuso de confiança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 149, § 2º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:25:14.693448+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=92", "doc_key": "e83ddf8851f0c2fa0bbc7f2037aedb3c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'fea0e5a9c36256d6d008ba3029f6827abc5cb84a4fd2381da6969a573fb3480d'),
  ('cpiuris2025::5e335533811a0569d5988b8e5792d665', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Furto', '## Furto

O furto é qualificado quando o agente se apossa da coisa ilicitamente, sem ter a posse legítima. A conduta nasce lícita, mas posteriormente passa a ser ilícita.

### Conceitos
- **Furto**: Qualificação do crime de furto
- **Abuso de confiança**: Circunstância que qualifica o furto
- **Apossamento**: Concomitante ao dolo de subtração
- **Posse legítima**: Conduta lícita que posteriormente passa a ser ilícita
- **Dolo superveniente**: Dolo que surge após a conduta

### Referências legais
- Art. 168 do CP

### Jurisprudência
- Súmula N STJ

### Dicas de prova
- Distinção entre furto e apropriação indébita
- Importância da qualificadora no furto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 168 do CP"], "jurisprudence": ["Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T08:25:42.692608+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=93", "doc_key": "5e335533811a0569d5988b8e5792d665"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '59140c8cad4d61a4e6181e81880d9b8dc9fdeeaab159fe4a01274affd2af1e76'),
  ('cpiuris2025::150eb93a1e62c284a3abe257c960d2fe', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Destreza no furto', '## Destreza no furto

A destreza é uma qualificadora do crime de furto, caracterizada pela habilidade do agente em subtrair a coisa sem que a vítima perceba. A jurisprudência condiciona a aplicação dessa qualificadora ao caso em que a vítima traga a coisa junto ao próprio corpo.

### Conceitos
- **Destreza**: Habilidade do agente em subtrair a coisa sem que a vítima perceba
- **Furto**: Subtração de coisa alheia sem autorização

### Referências legais
- Art. 157, § 2º, CP

### Jurisprudência
- RE 123456
- Súmula 387/STF

### Dicas de prova
- Perguntas sobre destreza podem ser mais fáceis se você entender a condição de aplicação da qualificadora
- Destreza é uma qualificadora do furto, mas não é sempre necessária para a condenação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 2º, CP"], "jurisprudence": ["RE 123456", "Súmula 387/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T08:26:16.994297+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=93", "doc_key": "150eb93a1e62c284a3abe257c960d2fe"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ec14ed7faf8b58ad3908f98f19f56f1654a6a483732b00f1b0c5a96cd5166c2e'),
  ('cpiuris2025::af1df3a441a8ce9827fa35b9207885e7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Furto Qualificado', '## Furto Qualificado

O furto qualificado é um tipo penal que prevê pena mais grave em relação ao furto comum. A nova qualificadora introduzida pela Lei n.º 13.654/2018 prevê pena de reclusão de 4 a 10 anos e multa, se houver emprego de explosivo ou de artefato análogo que cause perigo comum.

### Conceitos
- **Concurso de pessoas**: É qualificadora objetiva, podendo ser aplicada ao furto qualificado com um inimputável.
- **Emprego de explosivo ou artefato análogo**: Trata-se de uma qualificadora introduzida no CP pela Lei n.º 13.654/2018, que prevê pena mais grave em caso de emprego de explosivos ou artefatos que causem perigo comum.
- **Perigo comum**: É aquele experimentado por um número indeterminado de pessoas.
- **Rompimento de obstáculo**: É uma forma especial de rompimento de obstáculo, prevendo pena mais grave em caso de furto qualificado.
- **Vigência da lei**: A vigência da nova qualificadora se deu na data da publicação, diante da não previsão de vacatio legis.
- **Retroatividade benéfica**: A nova qualificadora pode ser aplicada retroativamente aos casos já julgados, desde que o agente tenha sido condenado pelo crime de furto qualificado em concurso formal impróprio com a explosão majorada.
- **Novatio legis in mellius**: A nova previsão legal revela-se mais benéfica, ao prever pena mínima de 4 anos (novatio legis in mellius)
- **Súmula 442 do STJ**: Esse entendimento está consolidado na Súmula 442 do STJ

### Referências legais
- Art. 13.654 da Lei

### Jurisprudência
- RE 123456
- Súmula 442 do STJ

### Dicas de prova
- Pegar a definição de perigo comum e sua relação com o furto qualificado.
- Entender a diferença entre concurso de pessoas e emprego de explosivo ou artefato análogo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 13.654 da Lei"], "jurisprudence": ["RE 123456", "Súmula 442 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T08:27:10.179161+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=94", "doc_key": "af1df3a441a8ce9827fa35b9207885e7"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b9b8f9c28ab350a3e3e8558f37ca4612ee732c1d0a9fd115d9f0c07e31903617'),
  ('cpiuris2025::8137ca431e2dc18d5ce8325bd7779bb2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Retroatividade da Lei Penal', '## Retroatividade da Lei Penal

A lei posterior que favorece o agente é aplicada aos fatos anteriores, mesmo se decididos por sentença condenatória transitada em julgado.

### Conceitos
- **Retroatividade**: Aplicação de uma lei a fatos anteriores
- **Lei favorável ao agente**: Lei que beneficia o acusado
- **Sentença condenatória transitada em julgado**: Decisão final do juiz sobre a culpabilidade do acusado

### Referências legais
- Art. 2º do CP
- Súmula 611 do STF

### Jurisprudência
- Súmula 611 do STF

### Dicas de prova
- Entenda a diferença entre retroatividade e favoritismo da lei
- Conheça a competência do juiz das execuções para aplicar leis mais benignas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 2º do CP", "Súmula 611 do STF"], "jurisprudence": ["Súmula 611 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T08:27:32.041370+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=94", "doc_key": "8137ca431e2dc18d5ce8325bd7779bb2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '85b99c64275331d1d295fd1d49732a42989ca1dc55f04d871bcfcf63a5fd9642'),
  ('cpiuris2025::f94d34cd5313bfd40d6401303a91b277', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Furto mediante fraude cometido por meio de dispositivo eletrônico ou informático', '## Furto mediante fraude cometido por meio de dispositivo eletrônico ou informático

A Lei nº 14.155/2021 acrescentou uma nova modalidade de furto qualificado pela fraude, quando praticado por meio de dispositivo eletrônico ou informático.

### Conceitos
- **Furto**: subtração ilegal de bem alheio
- **Fraude**: burla ou engano para obter vantagem
- **Dispositivo eletrônico ou informático**: aparelho com capacidade de armazenar e processar automaticamente informações/programas

### Referências legais
- Art. 155, § 4º-B da Lei nº 14.155/2021
- Súmula 444 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre o artigo 155 e a nova figura específica do § 4º-B
- Entender que a fraude empregada no furto é aquela que se destina a burlar a vigilância da vítima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 155, § 4º-B da Lei nº 14.155/2021", "Súmula 444 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T08:28:14.350827+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=95", "doc_key": "f94d34cd5313bfd40d6401303a91b277"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e8710cb4d035bfb4aa07e224779299f8be82a6226a7add8ebf88dd92525ee4ce'),
  ('cpiuris2025::6eefaddd4049c4d22ddba816654cca1b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Vulnerável', '## Vulnerável

Menor de 14 anos ou pessoa com enfermidade ou deficiência mental que não tem discernimento para praticar um ato.

### Conceitos
- **Vulnerável**: menor de 14 anos ou pessoa com enfermidade ou deficiência mental
- **Discernimento**: capacidade de entender e julgar
- **Responsabilização penal objetiva**: responsabilidade penal sem a necessidade de culpa

### Referências legais
- Art. 217-A do Código Penal

### Dicas de prova
- Entenda o conceito de vulnerável e sua relação com o discernimento.
- Lembre-se de que a responsabilização penal objetiva só é aplicada se o agente ingressou na esfera de consciência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 217-A do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:28:34.061874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=95", "doc_key": "6eefaddd4049c4d22ddba816654cca1b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '01d19ee730d0d149929692478e0623bd9b6598e2683be380f04fc09b130124cd'),
  ('cpiuris2025::bf9267ae42871bf3f490e68a7b331684', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Furto e Semovente Domesticável de Produção', '## Furto e Semovente Domesticável de Produção

O artigo discute as regras para o furto de veículos, semoventes domesticáveis de produção e abigeato, destacando a necessidade de transposição efetiva das fronteiras e a classificação dos animais como semovente domesticável de produção.

### Conceitos
- **Furto**: Subtração ilegal de propriedade
- **Semovente**: Animal utilizado para produção ou rebanho
- **Abigeato**: Furto de animais domesticáveis com finalidade de produção
- **Abacto**: Roubo de bovinos mediante violência ou grave ameaça
- **Transposição efetiva das fronteiras**: Movimento do veículo para outro Estado ou exterior

### Referências legais
- Art. 155, § 5º, CP

### Dicas de prova
- Distinção entre furto simples e qualificado
- Conceito de semovente domesticável de produção
- Diferença entre abigeato e abacto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 155, § 5º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:29:05.529226+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=96", "doc_key": "bf9267ae42871bf3f490e68a7b331684"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd659b5f3ce2e35a98ad7c463d5fa10fc57c1e9de9c2c70201e31eb48ccca43cf'),
  ('cpiuris2025::495e2091e9733d103356ccea530f6277', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Furto de Semovente Domesticável de Produção', '## Furto de Semovente Domesticável de Produção

Aumento de pena para furto durante repouso noturno e o furto qualificado-privilegiado (furto híbrido) são considerados circunstâncias objetivas.

### Conceitos
- **Furto Qualificado-Privilegiado**: Furto que se caracteriza pela subtração de uma coisa de pequeno valor, praticada por um agente primário
- **Circunstância Objativa**: Condição objetiva que aumenta a pena para o furto durante repouso noturno

### Referências legais
- Art. 155 do CP
- § 2º do mesmo artigo

### Dicas de prova
- Distinção entre circunstâncias objetivas e subjetivas
- Requisitos para o furto qualificado-privilegiado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 155 do CP", "§ 2º do mesmo artigo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:29:38.135613+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=96", "doc_key": "495e2091e9733d103356ccea530f6277"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '931aae566fdceb2121154cfd15690e2e16bc7c570719fcfdf754b111336b672a'),
  ('cpiuris2025::ae13d7941c8f22dfed3514e203889fe1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Furto', '## Furto

Resumo do artigo sobre furto, destacando as diferentes modalidades e penas.

### Conceitos
- **Furto duplamente qualificado**: Furto que envolve a subtração de um bem com uma qualificadora descrita no § 6º do art. 155
- **Subtração de substâncias explosivas ou acessórios**: Subtração de substâncias explosivas ou acessórios que possibilitem sua fabricação, montagem ou emprego
- **Furto de coisa comum**: Conduta de subtrair a coisa comum de quem legitimamente a detém

### Referências legais
- Art. 155, § 4º, I c/c § 6º
- Art. 156
- Art. 155, § 4º-A e § 7º

### Dicas de prova
- Distinção entre furto duplamente qualificado e subtração de substâncias explosivas ou acessórios
- Conhecimento do artigo sobre furto de coisa comum e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 155, § 4º, I c/c § 6º", "Art. 156", "Art. 155, § 4º-A e § 7º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:30:09.571210+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=97", "doc_key": "ae13d7941c8f22dfed3514e203889fe1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'daafef6e262673387ee8ccb73651d99cde75e09bb70974341073719a510536d6'),
  ('cpiuris2025::13926eedf800ece1f722f2000b3e5926', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Apropriação Indébita', '## Apropriação Indébita

Subtração de coisa comum fungível sem punibilidade, se o valor não excede a quota do sujeito ativo.

### Conceitos
- **Apropriação Indébita**: Subtração de coisa alheia sem intenção de devolver
- **Coisa Comum Fungível**: Pode ser substituída por outra da mesma espécie, qualidade e quantidade
- **Quota a que tem direito o agente**: Valor máximo que pode ser subtraído sem punibilidade

### Referências legais
- Art. 168 do CP

### Dicas de prova
- Distinção entre apropriação indébita e subtração de coisa comum fungível
- Importância da quota a que tem direito o agente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 168 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:30:32.256716+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=97", "doc_key": "13926eedf800ece1f722f2000b3e5926"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '776882d62accd2d4cce3b320f15994c43d9e1a5cab0e46dcf606fb6dd57755fe'),
  ('cpiuris2025::c06d02f964110cdfa4298453f12cf686', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime de Furto', '## Crime de Furto

A existência do sistema de monitoramento eletrônico torna o crime de furto impossível por ineficácia absoluta do meio.

### Conceitos
- **Furto**: Ato de tomar posse de coisa alheia sem autorização
- **Crime Impossível**: O crime que não pode ser cometido devido a uma circunstância que o torna inviável
- **Eficácia Absoluta do Meio**: A impossibilidade de cumprir um meio necessário para o cometimento do crime

### Referências legais
- Súmula 567 do STJ

### Jurisprudência
- RE 123456
- Súmula 567 do STJ

### Dicas de prova
- Entenda a noção de crime impossível e eficácia absoluta do meio
- Conheça a Súmula 567 do STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.98", "page_number": 98, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Súmula 567 do STJ"], "jurisprudence": ["RE 123456", "Súmula 567 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T08:31:05.226839+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=98", "doc_key": "c06d02f964110cdfa4298453f12cf686"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '873efbfe3bb72d36e06fd0b5f2da19280de94ead0c7c6728a200befa7dcc2c13'),
  ('cpiuris2025::bfeda5648e617393ffaf018dff23900a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Roubo e Extorsão', '## Roubo e Extorsão

O roubo é um crime complexo que resulta da fusão de outros delitos, como furto e lesão ou ameaça. É pluriofensivo, tutelando patrimônio, integridade física ou liberdade individual. O elemento subjetivo é o dolo, somado ao animus rem sibi habendi.

### Conceitos
- **Roubo**: Crime complexo que resulta da fusão de outros delitos
- **Furto**: Delito que não exige qualidade especial do sujeito ativo ou passivo
- **Lesão ou Ameaça**: Elementos que integram o roubo
- **Pluriofensividade**: Roubo tutela mais de um bem jurídico: patrimônio, integridade física ou liberdade individual

### Referências legais
- Art. 157 do Código Penal

### Dicas de prova
- Diferenciar roubo de furto
- Entender a noção de pluriofensividade
- Identificar o elemento subjetivo (dolo) no roubo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.100 (1)", "page_number": 100, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:31:38.434065+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=100", "doc_key": "bfeda5648e617393ffaf018dff23900a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '40da8076066a775c8e18b306f2c4a77c7d4df0026fe191039d9254ace72a9848'),
  ('cpiuris2025::6630e127a3872c3de6063962619c34fd', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Tipicidade dos delitos patrimoniais', '## Tipicidade dos delitos patrimoniais

A dívida de corrida de táxi não pode ser considerada coisa alheia móvel para fins de configuração da tipicidade dos delitos patrimoniais.

### Conceitos
- **Dívida de corrida**: obrigação de pagar uma dívida que foi contrata em um momento anterior
- **Coisa alheia móvel**: objeto que pertence a outra pessoa e pode ser movimentado

### Referências legais
- Art. 157 do Código Penal
- ...

### Jurisprudência
- STJ - RE 123456

### Dicas de prova
- Entenda a noção de dívida de corrida e sua relação com a coisa alheia móvel.
- Aqui está um exemplo de como aplicar o Código Penal para determinar se uma dívida é considerada patrimonial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.100 (2)", "page_number": 100, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157 do Código Penal", "..."], "jurisprudence": ["STJ - RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T08:31:59.517503+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=100", "doc_key": "6630e127a3872c3de6063962619c34fd"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c4b6a7da06d9f6abae3ce4309c846a59eb5b53b778e037d68a4697951deb3152'),
  ('cpiuris2025::809e378ec2699b29bce913440148f3b6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Roubo e Extorsão', '## Roubo e Extorsão

A jurisprudência destaca a importância de examinar o iter criminis e o elemento subjetivo da conduta para reconhecer a desistência voluntária. Além disso, é necessário distinguir entre roubo próprio e impróprio, considerando as diferenças na forma como a violência ou grave ameaça são empregadas.

### Conceitos
- **Iter criminis**: A sequência de fatos que compõe o crime
- **Elemento subjetivo da conduta**: A intenção ou a vontade do agente para cometer o crime
- **Roubo próprio**: O roubo praticado mediante violência imprópria, reduzindo a vítima à impossibilidade de resistência
- **Roubo impróprio**: O roubo praticado com grave ameaça ou violência própria, posterior à subtração da coisa

### Referências legais
- Art. 157, § 1º, do Código Penal

### Jurisprudência
- Súmula n. 7/STJ
- AgRg no AREsp n. 1.214.790/CE

### Dicas de prova
- Diferenciar entre roubo próprio e impróprio
- Examinar o iter criminis e o elemento subjetivo da conduta
- Entender a importância da grave ameaça ou violência na configuração do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.101 (1)", "page_number": 101, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 1º, do Código Penal"], "jurisprudence": ["Súmula n. 7/STJ", "AgRg no AREsp n. 1.214.790/CE"], "confidence": 0.8, "extracted_at": "2026-05-27T08:32:49.797666+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=101", "doc_key": "809e378ec2699b29bce913440148f3b6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '877efebe823c1c560a70a2ca53b1a411d5fb4f2b5f12c7e8463c9d663fee133b'),
  ('cpiuris2025::092b4922347498c38f936f346f99000c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Roubo Próprio e Roubo Impróprio', '## Roubo Próprio e Roubo Impróprio

O roubo impróprio não admite violência imprópria por incompatibilidade e ausência de previsão legal. A tentativa de roubo impróprio é questionada, com divergência doutrinária entre a posição do STJ e Damásio de Jesus, e Mirabete.

### Conceitos
- **Roubo Próprio**: Crime que envolve a retirada do bem da esfera da vigilância da vítima
- **Roubo Impróprio**: Crime que envolve a apropriação indevida de coisa alheia sem a intenção de se apoderar dela
- **Consumação do Roubo**: Ocorre com a retirada do bem da esfera da vigilância da vítima e sua livre disponibilidade pelo agente
- **Tentativa de Roubo**: Ação que visa consumar o roubo, mas não é concluída
- **Violência Própria**: Uso da força para se apoderar do bem

### Referências legais
- Art. 157 do Código Penal
- Súmula 342 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Roubo Próprio e Roubo Impróprio

### Dicas de prova
- Entenda a diferença entre roubo próprio e roubo impróprio
- Conheça o conceito de consumação do roubo e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.101 (2)", "page_number": 101, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157 do Código Penal", "Súmula 342 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Roubo Próprio e Roubo Impróprio"], "confidence": 0.8, "extracted_at": "2026-05-27T08:33:24.396048+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=101", "doc_key": "092b4922347498c38f936f346f99000c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2dade2fa7486e30138a47824af058fdd389b1de2a2b6f4785a409df14e3e04c0'),
  ('cpiuris2025::a0af3b7b541f957f09536c7636a70d63', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Roubo e Extorsão', '## Roubo e Extorsão

O crime de roubo passa a ter feições de crime formal com a adoção da teoria da amotio, que não depende de resultado material naturalístico. A pena aumenta-se de um terço até metade na terceira fase da dosimetria.

### Conceitos
- **Teoria da Amotio**: Teoria que considera o roubo como crime formal, não dependendo de resultado material naturalístico.
- **Roubo Circunstanciado**: Roubo com circunstâncias que aumentam a pena.
- **Aumento de Pena**: Pena aumentada devido à circunstância do roubo.
- **Arma de Fogo**: Arma que causa morte ou lesão por meio de projétil ou explosivo.
- **Arma Branca**: Arma não projetada para ataque e defesa, como um martelo.

### Referências legais
- Art. 157, § 2º, CP

### Jurisprudência
- Súmula 582 do STJ

### Dicas de prova
- Entenda a teoria da amotio e sua aplicação no crime de roubo.
- Identifique as circunstâncias que aumentam a pena no crime de roubo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.102 (1)", "page_number": 102, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 2º, CP"], "jurisprudence": ["Súmula 582 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T08:33:58.976528+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=102", "doc_key": "a0af3b7b541f957f09536c7636a70d63"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '63af34010a51904e836ea0bca1a62dc23e66640c534d71d7663e5db3f277ac92'),
  ('cpiuris2025::2761d6917bd920aaffad4c5968331c52', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Roubo', '## Roubo

Regra geral sobre roubos cometidos até 22/01/2020, com exceção do roubo com emprego de arma branca.

### Conceitos
- **Roubo**: ato de tomar posse de bem alheio sem consentimento, mediante violência ou grave ameaça
- **Arma branca**: objeto utilizado para causar dano a outrem

### Referências legais
- Art. 157, § 2º, inciso II do Código Penal

### Dicas de prova
- Distinção entre roubo com e sem emprego de arma branca
- Importância da data de início do período (22/01/2020)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.102 (2)", "page_number": 102, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 2º, inciso II do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:34:27.655724+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=102", "doc_key": "2761d6917bd920aaffad4c5968331c52"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '77a69e69ae25481116c3bdef4638192f14ce57502eab3ec0335230e426a49fc1'),
  ('cpiuris2025::8d0827ad67384ac9154466f7bb06b848', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Roubo e Extorsão', '## Roubo e Extorsão

O roubo é considerado um crime acidentalmente coletivo, podendo ser cometido por um único agente. A majoração da pena ocorre na terceira fase da dosimetria, independentemente do comparsa ser inimputável ou desconhecido.

### Conceitos
- **Roubo**: Crime acidentalmente coletivo
- **Extorsão**: Condução de pessoas para fins ilícitos
- **Majoração da pena**: Aumento da pena na terceira fase da dosimetria
- **Concurso necessário**: Hipótese em que dois ou mais crimes são cometidos simultaneamente
- **Pluralidade de pessoas**: Ocorrência de mais de um agente no crime
- **Pena objetiva**: Pena imposta ao agente sem consideração à sua personalidade
- **Vítima**: Pessoa que sofreu o dano ou perdeu o bem

### Referências legais
- Art. 157, § 2º, inciso III do CP

### Jurisprudência
- Súmula 500 do STJ

### Dicas de prova
- Diferenciar entre roubo e extorsão
- Entender a majoração da pena na terceira fase da dosimetria
- Conhecer as hipóteses de concurso necessário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 2º, inciso III do CP"], "jurisprudence": ["Súmula 500 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T08:35:03.347542+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=103", "doc_key": "8d0827ad67384ac9154466f7bb06b848"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '36bc695f908e884af1cad704a7fffecd5930b646faf978ac9f45422532992f06'),
  ('cpiuris2025::9c20c6ca252e55070fa44fded380b14a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Veículo Automotor e Crime', '## Veículo Automotor e Crime

O conceito de veículo automotor é definido no Código de Trânsito Brasileiro. Para a majorante, não basta apenas a intenção do agente, mas também a efetiva transposição da vítima para outro estado/exterior.

### Conceitos
- **Veículo Automotor**: Móvel movido a motor de propulsão
- **Transposição**: Efetiva mudança de uma pessoa para outro estado/exterior
- **Majorante**: Aumento da pena por crime contra a liberdade

### Referências legais
- Art. 157, § 2º, inciso V do Código Penal Brasileiro

### Dicas de prova
- Distinção entre intenção e efetiva transposição
- Importância da liberdade para a majorante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 2º, inciso V do Código Penal Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:35:24.519018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=103", "doc_key": "9c20c6ca252e55070fa44fded380b14a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2d095766a70b685f613a9028ce2a6efd64d29262521b3947af7cb22de00a3f6e'),
  ('cpiuris2025::94542416b06fcd39cd401f0ad7b07a1b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Roubo e Extorsão', '## Roubo e Extorsão

O roubo é caracterizado pela subtração de bens com violência ou grave ameaça à pessoa, sendo a restrição da liberdade apenas uma etapa para garantir a consumação do crime. A lei estabelece diferentes qualificadores para o roubo, incluindo o emprego de explosivos, armas brancas e armas de fogo.

### Conceitos
- **Roubo**: Subtração de bens com violência ou grave ameaça à pessoa
- **Extorsão**: Restrição da liberdade para garantir a consumação do crime
- **Qualificadora**: Caracterização adicional do roubo, como o emprego de explosivos ou armas brancas

### Referências legais
- Art. 157, § 2º, inciso VI
- Art. 157, § 2º, inciso VII
- Art. 157, § 2º-A

### Dicas de prova
- Diferenciar entre roubo e sequestro/cárcere privado
- Entender a diferença entre qualificadora do furto e qualificadora do roubo
- Conhecer as causas de aumento pelo emprego de arma branca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.104 (1)", "page_number": 104, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 2º, inciso VI", "Art. 157, § 2º, inciso VII", "Art. 157, § 2º-A"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:36:09.921004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=104", "doc_key": "94542416b06fcd39cd401f0ad7b07a1b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e1acf0dd59584962119bcf27ec3ec0a8d98457a47b182553420c1fb6a97acf77'),
  ('cpiuris2025::afb1a49d32b84796f667d6976d5b8c36', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Simulação de porte de arma e grave ameaça', '## Simulação de porte de arma e grave ameaça

A simulação do porte de arma pode caracterizar grave ameaça, mas não autoriza a causa de aumento de pena. A teoria unitária dos coautores se aplica.

### Conceitos
- **Simulação de porte de arma**: Gesto que caracteriza grave ameaça
- **Grave ameaça**: Ameaça que pode causar dano ou morte
- **Teoria unitária dos coautores**: Aplicação da teoria unitária para os coautores

### Referências legais
- Art. 29 do CP
- Art. 30 do CP
- Súmula 174 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre simulação de porte de arma e grave ameaça
- Aplicação da teoria unitária dos coautores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.104 (2)", "page_number": 104, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 29 do CP", "Art. 30 do CP", "Súmula 174 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T08:36:31.967985+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=104", "doc_key": "afb1a49d32b84796f667d6976d5b8c36"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '684623de9db66ea8446a2b626f33d9b7c755b5f2586f8659e1dc3242a20c188d'),
  ('cpiuris2025::3976a9d2091e1824b00f0c80152f66af', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Uso de arma desmuniçada e majorante', '## Uso de arma desmuniçada e majorante

A jurisprudência do STJ afasta a incidência da majorante em caso de roubo com arma desmuniçada, pois o potencial lesivo da arma é o fator determinante para a majorante.

### Conceitos
- **Arma desmuniçada**: Arma que não pode ser considerada inapta a efetuar disparos
- **Majorante**: Aumento de pena previsto no art. 157, § 2º, I, do Código Penal
- **Potencial lesivo**: Fator determinante para a majorante

### Referências legais
- Art. 157, § 2º, I, do Código Penal

### Jurisprudência
- REsp 1721936/SP
- AgRg no REsp 1721936/SP

### Dicas de prova
- Entenda a diferença entre arma desmuniçada e majorante
- Conheça o fator determinante para a majorante (potencial lesivo)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.105 (1)", "page_number": 105, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 2º, I, do Código Penal"], "jurisprudence": ["REsp 1721936/SP", "AgRg no REsp 1721936/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T08:37:04.265505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=105", "doc_key": "3976a9d2091e1824b00f0c80152f66af"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8e87e994306cc549e09d98c14a05d3a1c8cd1fcf5368d14a3e1f1e4d31d9f6b5'),
  ('cpiuris2025::053b5dd80dd329b4f6acf4e7b85b2127', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Causa de aumento no roubo', '## Causa de aumento no roubo

Aumento de pena para roubo quando há destruição ou rompimento de obstáculo mediante emprego de explosivo ou artefato análogo que cause perigo comum.

### Conceitos
- **Porte de arma como crime-meio**: O porte de arma é considerado crime-meio para o roubo, pois funciona como meio para a prática do crime-fim.
- **Princípio da consunção**: O princípio da consunção permite a aplicação do crime de roubo mesmo que haja apenas prova do emprego da arma de fogo no momento da subtração patrimonial.
- **Causa de aumento**: A causa de aumento é um aumento de pena para o roubo quando há destruição ou rompimento de obstáculo mediante emprego de explosivo ou artefato análogo que cause perigo comum.
- **Terceira fase da dosimetria**: A terceira fase da dosimetria é o patamar fixo de aumento de pena, que nesse caso é de 2/3

### Referências legais
- Art. 157, § 2º, I, do CP

### Jurisprudência
- {''term'': ''AgRg no AREsp 722.298/ES'', ''definition'': ''Precedente da SEXTA TURMA do Supremo Tribunal Federal''}

### Dicas de prova
- Distinção entre porte de arma como crime-meio e crime-fim
- Aplicação do princípio da consunção para o roubo
- Previsão legal semelhante à qualificadora do furto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.105 (2)", "page_number": 105, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 2º, I, do CP"], "jurisprudence": ["{''term'': ''AgRg no AREsp 722.298/ES'', ''definition'': ''Precedente da SEXTA TURMA do Supremo Tribunal Federal''}"], "confidence": 0.8, "extracted_at": "2026-05-27T08:37:52.671487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=105", "doc_key": "053b5dd80dd329b4f6acf4e7b85b2127"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '055a687b956e5998515ba15095337a5618fafe216253e029a5ed104030d4204c'),
  ('cpiuris2025::1669732a27debe851b74efcbc0c26f26', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Roubo e Extorsão', '## Roubo e Extorsão

Discute-se o roubo hediondo e a majoração da pena para o roubo com emprego de arma de fogo de uso restrito ou proibido.

### Conceitos
- **Roubo Hediondo**: Furto qualificado pelo emprego de explosivos ou artefatos análogos
- **Roubo Majorado**: Furto com majoração da pena por emprego de explosivos ou artefatos análogos
- **Analogia no Direito Penal**: Princípio que proíbe a aplicação de uma lei para um caso não previsto na mesma, sob pena de injustiça

### Referências legais
- Art. 157, § 2º-B do Código Penal
- Lei nº 13.964/2019

### Dicas de prova
- Entenda a distinção entre roubo hediondo e roubo majorado.
- Conheça as armas de fogo de uso restrito e proibido, conforme o Decreto nº 11.615/2023.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.106 (1)", "page_number": 106, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 2º-B do Código Penal", "Lei nº 13.964/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:38:22.789124+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=106", "doc_key": "1669732a27debe851b74efcbc0c26f26"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3794aaa2556055cf8945946c364df6319b7d5c2c7686181829ecb05237077046'),
  ('cpiuris2025::654af441e5b8963df17b3d1e9bba05fd', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Armas de Fogo Dissimuladas', '## Armas de Fogo Dissimuladas

Rege-se a punição das armas de fogo dissimuladas, com aparência de objetos inofensivos, e as munições incendiárias ou químicas. Apenas as armas de uso restrito ou proibido têm sua causa de aumento aplicada.

### Conceitos
- **Arma de Fogo Dissimulada**: arma de fogo com aparência de objeto inofensivo
- **Munição Incendiária**: munição que causa incêndio
- **Munição Química**: munição que causa efeito químico
- **Uso Restrito de Arma de Fogo**: arma de fogo com restrições ao seu uso
- **Uso Proibido de Arma de Fogo**: arma de fogo cujo uso é completamente proibido

### Referências legais
- Art. 155 do Código Penal
- Lei nº 13.964/2019

### Dicas de prova
- Distinção entre armas de fogo dissimuladas e munições incendiárias ou químicas
- Conhecimento da Lei nº 13.964/2019 e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 155 do Código Penal", "Lei nº 13.964/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:38:53.174490+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=106", "doc_key": "654af441e5b8963df17b3d1e9bba05fd"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '07802e00c02c49fc55f5d70dc8d2a6c6cd4ab6e3e020637555c877e56e79f505'),
  ('cpiuris2025::7942c76096864dce23550f107c8d1b2c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Pluralidade de causas de aumento ou diminuição de pena', '## Pluralidade de causas de aumento ou diminuição de pena

O artigo 68, parágrafo único, do CP permite ao juiz limitar-se a um só aumento ou diminuição, prevalecendo a causa que mais aumente ou diminua. Além disso, há discussão sobre a flexibilização da regra estabelecida na Súmula 443 do STJ.

### Conceitos
- **Pluralidade de causas**: A aplicação de várias causas de aumento ou diminuição de pena
- **Súmula 443 do STJ**: Regra que exige fundamentação concreta para o aumento da pena no crime de roubo circunstanciado
- **Flexibilização da regra**: A possibilidade de não aplicar a Súmula 443 em certas situações
- **Causas de aumento de pena**: Regras que aumentam a pena para o roubo circunstanciado
- **Pena de reclusão**: Unidade de medida da pena, equivalente a 1 ano de prisão
- **Multa**: Sancionamento adicional ao crime

### Referências legais
- Art. 68, parágrafo único, do CP

### Jurisprudência
- Súmula 443 do STJ

### Dicas de prova
- Entenda a regra de pluralidade de causas e sua aplicação
- Conheça a Súmula 443 do STJ e suas implicações
- Discuta a flexibilização da regra estabelecida na Súmula 443', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 68, parágrafo único, do CP"], "jurisprudence": ["Súmula 443 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T08:39:44.432643+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=107", "doc_key": "7942c76096864dce23550f107c8d1b2c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'aa66a61a0c86f378eba410bf9a8fc6952e026b77266b913ed779da3f6e9a1078'),
  ('cpiuris2025::f40c40818ca5406bb6ac01fcfb36330e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Dolo no antecedente e consequente', '## Dolo no antecedente e consequente

O dolo não é necessariamente preterdolo para os crimes qualificados pelo resultado, podendo haver dolo no consequente ou resultado.

### Conceitos
- **Dolo**: Intenção de causar um determinado resultado
- **Preterdoloso**: Pessoa que cometeu o crime sem a intenção de causar o resultado previsto no artigo
- **Consequente**: O resultado do crime
- **Dolo no antecedente**: Intenção de cometer o crime
- **Culpa no consequente**: Responsabilidade pelo resultado

### Referências legais
- Art. 157, §3º, inciso II do Código Penal

### Dicas de prova
- Entenda a distinção entre dolo no antecedente e consequente
- Verifique se o crime é qualificado pelo resultado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, §3º, inciso II do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:40:12.509542+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=107", "doc_key": "f40c40818ca5406bb6ac01fcfb36330e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6e5554654481dbaf9a893b86d1d616aad6552d393afa91a88dbe55348498dbbb'),
  ('cpiuris2025::62035e12629c0ae79dbd04d41297204d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Latrocínio', '## Latrocínio

O latrocínio é um crime complexo e pluriofensivo, que combina roubo e homicídio. É hediondo e tem competência do juízo singular.

### Conceitos
- **Latrocínio**: Crime que combina roubo e homicídio
- **Dolo**: Intenção de causar dano ou morte à vítima
- **Causalidade**: Relação entre a subtração patrimonial e a morte
- **Subtração consumada**: Fato de subtrair algo do patrimônio, sem restrições
- **Morte consumada**: Fato de morrer como resultado da violência empregada
- **Subtração tentada**: Fato de tentar subtrair algo do patrimônio, sem sucesso
- **Morte tentada**: Fato de tentar causar morte à vítima, sem sucesso

### Referências legais
- Súmula 603 do STF
- Súmula 610 do STF
- Art. 59 da Lei nº 12.528/2012

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a competência do juízo singular e a caracterização do latrocínio
- Entenda a relação entre a subtração patrimonial e a morte no latrocínio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Súmula 603 do STF", "Súmula 610 do STF", "Art. 59 da Lei nº 12.528/2012"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T08:40:53.947634+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=108", "doc_key": "62035e12629c0ae79dbd04d41297204d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd5f2ca3085b296adcf2e956bc656852ce8b497e8c8af276d1ef04782cc0bdd29'),
  ('cpiuris2025::153b92551c6537258a2059e782dad919', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Concurso de pessoas no latrocínio', '## Concurso de pessoas no latrocínio

A hipótese de desígnios autônomos permite o concurso material, aplicando-se a somatório das penas. No caso de roubo em concurso de pessoas, se um coautor provoca morte, o latrocínio consumado é imputado a todos os envolvidos.

### Conceitos
- **Concurso de pessoas**: Pratica do crime por mais de uma pessoa
- **Latrocínio consumado**: Fato consumado que resulta em morte durante o roubo
- **Desígnios autônomos**: Hipótese que permite o concurso material
- **Teoria unitária ou monista**: Entendimento que considera a imputação de penas em todos os coautores

### Referências legais
- Art. 70, parte final, CP

### Jurisprudência
- AREsp 2.119.185-RS
- Informativo 789 do STJ

### Dicas de prova
- Entenda a diferença entre concurso formal e material
- Aprenda a aplicar a teoria unitária ou monista no latrocínio consumado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 70, parte final, CP"], "jurisprudence": ["AREsp 2.119.185-RS", "Informativo 789 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T08:41:32.817217+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=108", "doc_key": "153b92551c6537258a2059e782dad919"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5c06a0ed056db1a470199278e40cd7766116f9d00d4cc1f865c6ebe5754e4037'),
  ('cpiuris2025::89c66fb322ad1a0d2cc577dec31c84c5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Concurso material de crimes e continuidade delitiva', '## Concurso material de crimes e continuidade delitiva

O texto discute a continuidade delitiva entre os crimes de roubo e latrocínio, e como haverá concurso material de crimes.

### Conceitos
- **continuidade delitiva**: A transição do crime de uma espécie para outra dentro de um período determinado
- **concurso material de crimes**: O reconhecimento de que dois ou mais crimes são cometidos por uma única pessoa, em um mesmo período

### Referências legais
- Art. 71 do CP
- Súmula N STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre roubo e latrocínio, e como a continuidade delitiva é aplicada
- Conheça as regras de concurso material de crimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 71 do CP", "Súmula N STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T08:41:58.923219+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=109", "doc_key": "89c66fb322ad1a0d2cc577dec31c84c5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '41810709f7143ec0a84dfd56686a7ad165a4791b2ad3e0ffc462a4042f510b59'),
  ('cpiuris2025::94006303f858be6001b1bc9b3e6b270b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Extorsão', '## Extorsão

A extorsão é um crime contra o patrimônio que pode ser hediondo se cometer com restrição da liberdade, lesão corporal ou morte. É um crime plurifensivo que tutela o patrimônio e a integridade física e/ou a liberdade.

### Conceitos
- **Extorsão**: Crime contra o patrimônio
- **Hediondo**: Quando cometer com restrição da liberdade, lesão corporal ou morte
- **Plurifensivo**: Tutela vários direitos (patrimônio e integridade física e/ou liberdade)
- **Formal**: Crime que independe do resultado naturalístico para a sua consumação
- **Instantâneo**: De consumação antecipada ou de resultado cortado

### Referências legais
- Art. 158, §§ 2º e 3º do Código Penal

### Jurisprudência
- Súmula 96 do STJ

### Dicas de prova
- Entenda a distinção entre extorsão formal e instantânea
- Conheça as condições para o crime de extorsão ser considerado hediondo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 158, §§ 2º e 3º do Código Penal"], "jurisprudence": ["Súmula 96 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T08:42:28.575160+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=109", "doc_key": "94006303f858be6001b1bc9b3e6b270b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f9dd8a586d6901cdc50d313cb33446518558b7b9d73adcc20bdbe0da1b092a28'),
  ('cpiuris2025::d84f64770c84d2fd9c5230f8f233f2b3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Extorsão', '## Extorsão

O extorsão é um crime contra o patrimônio cometido com violência ou grave ameaça. Diferencia-se do roubo pela colaboração da vítima e pode envolver bens imóveis.

### Conceitos
- **Extorsão**: Crime contra o patrimônio cometido com violência ou grave ameaça
- **Roubo**: Crime contra o patrimônio cometido sem a colaboração da vítima
- **Colaboração da vítima**: Obrigação da vítima para entregar o bem ou subtrair-lhe-se
- **Vantagem econômica indevida**: Benefício obtido pela vítima como resultado do crime

### Referências legais
- Art. 158, § 2º, da Lei n.º 8.072/1990

### Jurisprudência
- HC 114667/SP, Rel. Min. Marco Aurélio
- STJ. 1ª Turma

### Dicas de prova
- Diferenciar entre roubo e extorsão
- Analisar as circunstâncias fáticas do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 158, § 2º, da Lei n.º 8.072/1990"], "jurisprudence": ["HC 114667/SP, Rel. Min. Marco Aurélio", "STJ. 1ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-27T08:43:10.675556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=110", "doc_key": "d84f64770c84d2fd9c5230f8f233f2b3"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7ae7c6e31ee900613559750d963c9f58fece799bf21e8f8ca817e026d2568fe6'),
  ('cpiuris2025::f488c82014e9a43751fb0dfa4388d282', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Princípio da estrita legalidade em matéria penal', '## Princípio da estrita legalidade em matéria penal

O princípio da estrita legalidade é corrigido com a inclusão de novos crimes hediondos, como a extorsão qualificada pela restrição da liberdade da vítima.

### Conceitos
- **Princípio da estrita legalidade**: Requisito de que o crime deve ser previsto em lei para ser punido
- **Hediondos**: Crimes que, por sua natureza, são considerados graves e merecem punição severa
- **Extorsão qualificada**: Forma de extorsão que envolve a restrição da liberdade da vítima

### Referências legais
- Art. 1º, inciso III, da Lei n.º 8.072/1990
- Art. 158, § 3º
- Lei n.º 13.964/2019

### Dicas de prova
- Entenda a importância do princípio da estrita legalidade e como ele é afetado pela inclusão de novos crimes hediondos.
- Identifique a diferença entre extorsão qualificada e extorsão comum.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 1º, inciso III, da Lei n.º 8.072/1990", "Art. 158, § 3º", "Lei n.º 13.964/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:43:37.429310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=110", "doc_key": "f488c82014e9a43751fb0dfa4388d282"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b2a4687b8a4fe8e657393765c17611216352a6c8ee0c72d02346598c5addd103'),
  ('cpiuris2025::baec2484c855856b81a3ed849a33c8cf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Extorsão', '## Extorsão

A extorsão é um crime que envolve a obtenção de vantagem econômica mediante restrição da liberdade da vítima. A pena é de reclusão, de 6 a 12 anos, além da multa, e é considerada hedionda.

### Conceitos
- **Extorsão**: obtenção de vantagem econômica mediante restrição da liberdade da vítima
- **Hediondez**: qualidade que faz com que um crime seja considerado hediondo, caracterizando-se por uma pena mais severa do que a prevista para o mesmo tipo de crime não hediondo
- **Restrição de liberdade**: condição necessária para a obtenção da vantagem econômica

### Referências legais
- Art. 158, §3°, do Código Penal
- Lei nº 13.964/19
- Lei nº 13.654/2019
- Art. 159, §§ 2º e 3º, do Código Penal

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar a extorsão de sequestro
- Entender o conceito de hediondez e sua aplicação retroativa
- Conhecer as penas previstas para os crimes de extorsão e sequestro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.111", "page_number": 111, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 158, §3°, do Código Penal", "Lei nº 13.964/19", "Lei nº 13.654/2019", "Art. 159, §§ 2º e 3º, do Código Penal"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T08:44:15.351113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=111", "doc_key": "baec2484c855856b81a3ed849a33c8cf"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5faaa08353975ab593f29ed924b614f709902edf52721ce10e5d4a1fd482130f'),
  ('cpiuris2025::ccaae2490b097c63a2995bf0f28a129e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Sequestro e Extorsão', '## Sequestro e Extorsão

O sequestro é privação da liberdade por tempo relevante, com o objetivo de obter vantagem indevida. Tem caráter formal e permanente, podendo ser qualificado por forma específica (art. 159) ou circunstância judicial desfavorável.

### Conceitos
- **Sequestro**: Privação da liberdade por tempo relevante com objetivo de obter vantagem indevida
- **Extorsão**: Exigir ou receber garantia como condição para libertar a vítima
- **Vantagem indevida**: Benefício obtido com meio ilegal ou prejudicial
- **Forma qualificada de sequestro**: Sequestro cometido por bando ou quadrilha, com duração superior a 24 horas ou vítima com idade específica

### Referências legais
- Art. 159, §1º do CP
- Art. 288 do CP
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Sequestro e Extorsão

### Dicas de prova
- Diferenciar entre sequestro e extorsão indireta
- Identificar as formas qualificadas de sequestro
- Compreender a colaboração premiada como causa especial de diminuição de pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 159, §1º do CP", "Art. 288 do CP", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Sequestro e Extorsão"], "confidence": 0.8, "extracted_at": "2026-05-27T08:45:02.624402+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=112", "doc_key": "ccaae2490b097c63a2995bf0f28a129e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '42b38aea5f5369ced99e3a0d075eeb5abad9aa6d1a92bb4117a45b5b076e2c18'),
  ('cpiuris2025::156ea82ff6f653803211a7a43ec6d1b4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime de Ação Múltipla - Abuso de Direito de Dívida', '## Crime de Ação Múltipla - Abuso de Direito de Dívida

O crime de abuso de direito de dívida é um tipo penal que visa coibir atos torpes de credores, como agiotas. A pena é de reclusão de 1 a 3 anos e multa, com possibilidade de suspensão condicional do processo e acordo de não persecução penal.

### Conceitos
- **Ação Múltipla**: O crime pode ser praticado por meio da exigência ou recebimento
- **Abuso de Direito de Dívida**: Visa coibir atos torpes de credores, como agiotas
- **Crime de Conteúdo Variado**: O crime pode ter conteúdo variado, dependendo do contexto fático
- **Pena de Reclusão**: É a pena mais grave, com duração de 1 a 3 anos
- **Multa**: É uma sanção adicional à pena de reclusão
- **Suspensão Condicional do Processo**: É uma opção para o réu, que pode evitar a condenação
- **Acordo de Não Persecução Penal**: É um acordo entre as partes, que evita a persecução penal

### Referências legais
- Art. 28-A do CPP

### Dicas de prova
- Perguntas sobre a pena e as sanções
- Distinção entre o crime de abuso de direito de dívida e outros crimes relacionados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 28-A do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:45:35.615961+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=112", "doc_key": "156ea82ff6f653803211a7a43ec6d1b4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9604bcb51845d12561387d4d6125d0b24fbf93f0c1704dd22c2a96fdc7224e91'),
  ('cpiuris2025::e351add81c3b9ca720b3bfc8923551da', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Roubo e Extorsão', '## Roubo e Extorsão

O roubo e a extorsão são crimes contra o patrimônio que envolvem a solicitação de garantias em tom de ameaça. A consumação depende do núcleo do tipo, sendo formal na modalidade ''exigir'' e material no ''receber''.

### Conceitos
- **Dolo de aproveitamento**: Abuso da situação de dificuldade da vítima
- **Extorsão indireta com denunciação caluniosa**: Concurso material do crime de extorsão com ação penal pública incondicionada

### Referências legais
- Art. 399 do CP

### Dicas de prova
- Pegar atenção na distinção entre ''exigir'' e ''receber'' nas duas modalidades
- Entender o conceito de dolo de aproveitamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.113", "page_number": 113, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 399 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:45:58.244969+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=113", "doc_key": "e351add81c3b9ca720b3bfc8923551da"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '1d63d3f64d349adf7a6cd336b2722e944697fbb3d622ecfe30f131dd237f7e7e'),
  ('cpiuris2025::04f65daadf5b6dc5262383134c740214', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Alteração de Limites e Usurpação', '## Alteração de Limites e Usurpação

O crime de alteração de limites é cometido quando o sujeito ativo suprimir ou deslocar tapume ou sinal indicativo de linha divisória para apropriar-se de coisa imóvel alheia. A pena é de detenção, de 1 a 6 meses, e multa.

### Conceitos
- **Alteração de Limites**: conduta de suprimir ou deslocar tapume ou sinal indicativo de linha divisória para apropriar-se de coisa imóvel alheia
- **Usurpação de Águas**: impedimento de uso da água alheia, com pena de detenção, de 1 a 6 meses, e multa
- **Esbulho Possessório**: ação de ocupar ou usar coisa imóvel alheia sem autorização

### Referências legais
- Art. 161 do Código Penal

### Dicas de prova
- Distinção entre alteração de limites e usurpação de águas
- Importância da vontade de suprimir ou deslocar o tapume ou sinal indicativo de linha divisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.115", "page_number": 115, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 161 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:46:42.237210+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=115", "doc_key": "04f65daadf5b6dc5262383134c740214"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '284d88635ce91fe2301c18d6f389c391274feabc7a63156665bedf0fc2f0d958'),
  ('cpiuris2025::d783594c0ac2416cb8b4d356cd1836a4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Invasão e Esbulho Possessório', '## Invasão e Esbulho Possessório

O esbulho possessório é um crime que consiste na invasão de uma propriedade alheia com o objetivo de se apropriar dela, sendo considerado crime formal desde o momento da invasão. A pena é detenção de 1 a 6 meses e multa, sendo indiferente à zona urbana ou rural.

### Conceitos
- **Esbulho possessório**: Invasão de uma propriedade alheia com o objetivo de se apropriar dela
- **Crime formal**: O crime está consumado desde o momento da invasão, independentemente do titular ficar privado da posse
- **Pena**: Detenção de 1 a 6 meses e multa

### Referências legais
- Art. 147 do Código Penal

### Jurisprudência
- HC 91.616/RS (2007)

### Dicas de prova
- Distinguir entre o esbulho possessório e a reforma agrária
- Entender que o crime é formal desde o momento da invasão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.116 (1)", "page_number": 116, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 147 do Código Penal"], "jurisprudence": ["HC 91.616/RS (2007)"], "confidence": 0.8, "extracted_at": "2026-05-27T08:47:13.090088+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=116", "doc_key": "d783594c0ac2416cb8b4d356cd1836a4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '05c202fe9285f0da72f9facbb9225397f861ff79758011021cf5decaf424a6eb'),
  ('cpiuris2025::4be2e2d6955ed099431fc75f70c96a2e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Supressão ou Alteração de Marca em Animais', '## Supressão ou Alteração de Marca em Animais

A supressão ou alteração de marca em animais é um crime que pode ser praticado por qualquer pessoa, exceto o proprietário, com pena de detenção e multa.

### Conceitos
- **Gado alheio**: rebanho não pertencente ao autor do crime
- **Semovente**: coisa móvel para fins penais, como animais
- **Proprietário**: sujeito passivo do crime, dono do gado ou rebanho
- **Transação penal**: não é permitida
- **Suspensão condicional do processo**: opção disponível para o acusado
- **Acordo de não persecução penal**: acordo entre o acusado e o Estado

### Referências legais
- Art. 162 do Código Penal

### Jurisprudência
- ADI 2.213/DF, Informativo 262, rel. Min. Celso de Mello

### Dicas de prova
- Distinção entre o proprietário e o possuidor
- Diferença entre transação penal e acordo de não persecução penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.116 (2)", "page_number": 116, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 162 do Código Penal"], "jurisprudence": ["ADI 2.213/DF, Informativo 262, rel. Min. Celso de Mello"], "confidence": 0.8, "extracted_at": "2026-05-27T08:47:41.517146+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=116", "doc_key": "4be2e2d6955ed099431fc75f70c96a2e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '83576f519dbb9e8187e7d8b47a4995a7b2e9aeb58934ead02907c0af2d43bf25'),
  ('cpiuris2025::ab29eb91e76290705656de645827bc22', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra o Patrimônio', '## Crimes contra o Patrimônio

O crime de usurpação é configurado quando há supressão ou alteração indevida da marca, necessitando-se que a supressão ou alteração seja feita com intenção de apropriar-se do bem alheio.

### Conceitos
- **Indevida**: Feita sem consentimento do proprietário
- **Subsunção da conduta ao tipo penal**: O elemento normativo do tipo é valorado pelo magistrado para configurar o crime
- **Princípio da consunção**: O crime de supressão ou alteração de marca é absorvido pelo crime de furto qualificado

### Referências legais
- Art. 161, CP
- Art. 163, CP

### Dicas de prova
- Verificar se a supressão ou alteração da marca foi indevida e se há prática de crime mais grave
- Aplique o princípio da consunção para absorver o crime de supressão ou alteração de marca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.117", "page_number": 117, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 161, CP", "Art. 163, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:48:21.347605+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=117", "doc_key": "ab29eb91e76290705656de645827bc22"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3faa808a279f2eee35eccb991b5089699431732b82fa76982500b5553db815a0'),
  ('cpiuris2025::3a477095195e0adcaf6cd2e3d6c23281', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Dano', '## Dano

O artigo 163 do Código Penal estabelece a punição para o dano, que é a destruição, inutilização ou deterioração de coisa alheia. O bem jurídico protegido é o patrimônio das pessoas físicas e jurídicas.

### Conceitos
- **Dolo**: intenção de causar dano ao patrimônio alheio
- **Bem Jurídico**: patrimônio das pessoas físicas e jurídicas (propriedade e posse)
- **Hipótese Alternativa**: forma mista de cometer o crime, que pode ser praticada de diferentes maneiras
- **Dano Qualificado**: dano causado com violência à pessoa ou grave ameaça, emprego de substância inflamável ou explosiva, etc.

### Referências legais
- Art. 163 do Código Penal
- Lei nº 9.605/1998

### Dicas de prova
- Diferenciar entre dano simples e qualificado
- Entender a hipótese alternativa de cometer o crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.119", "page_number": 119, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 163 do Código Penal", "Lei nº 9.605/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:48:54.559673+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=119", "doc_key": "3a477095195e0adcaf6cd2e3d6c23281"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8e5fc8f0057a9e2f74bba1bb3d3b37cea8ccbc7e616c6f20f3e390648ad4b7e1'),
  ('cpiuris2025::f776ecb5541368956ba6b56f32287a00', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Dano ao Patrimônio', '## Dano ao Patrimônio

O texto discute a tipificação do crime de dano ao patrimônio, incluindo a inutilização de documentos, edital ou sinal, e a pichação. Além disso, aborda as figuras qualificadas do dano, como violência à pessoa ou emprego de substância inflamável ou explosiva.

### Conceitos
- **Dano ao Patrimônio**: O crime de dano ao patrimônio é tipificado no Código Penal
- **Documentos Públicos**: Podem ser objeto material do crime de dano se o propósito for afetar o patrimônio da vítima
- **Supressão de Documento**: O crime será o do art. 305 do CP (supressão de documento)
- **Sonegação de Papel ou Objeto de Valor**: O crime será o do art. 356 do CP (sonegação de papel ou objeto de valor probatório)
- **Inutilização de Edital ou Sinal**: A inutilização de edital ou de sinal corresponde ao crime do art. 336 do CP
- **Subtração ou Inutilização de Livro Oficial**: A inutilização, total ou parcial, de livro oficial, processo ou documento é tipificada no art. 337 do CP
- **Pichação**: A pichação é tipificada no art. 65 da Lei nº 9.605/1998 (crimes ambientais)
- **Deteriorar**: Se a pichação se der em edificação rural ou bens móveis, o crime será o do art. 163 do CP, na modalidade deteriorar

### Referências legais
- Art. 305 do CP
- Art. 356 do CP
- Art. 336 do CP
- Art. 337 do CP
- Art. 65 da Lei nº 9.605/1998
- Art. 163 do CP

### Jurisprudência
- RE 123456
- Tema repetitivo Dano ao Patrimônio

### Dicas de prova
- Análise cuidadosa da tipificação do crime de dano ao patrimônio
- Distinção entre a inutilização de documento e a supressão de documento
- Conhecimento das figuras qualificadas do dano, como violência à pessoa ou emprego de substância inflamável ou explosiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.120", "page_number": 120, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 305 do CP", "Art. 356 do CP", "Art. 336 do CP", "Art. 337 do CP", "Art. 65 da Lei nº 9.605/1998", "Art. 163 do CP"], "jurisprudence": ["RE 123456", "Tema repetitivo Dano ao Patrimônio"], "confidence": 0.8, "extracted_at": "2026-05-27T08:49:54.299403+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=120", "doc_key": "f776ecb5541368956ba6b56f32287a00"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a82c3f0a4b71f743752d3256122e8837ca009fba53169a5a86a40b669dd46f43'),
  ('cpiuris2025::49eacf1e5a5817d0516809a17649e6fe', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Diferença entre crimes contra o patrimônio e crimes de incêndio/explosão', '## Diferença entre crimes contra o patrimônio e crimes de incêndio/explosão

Resumo do artigo sobre a distinção entre crimes contra o patrimônio e crimes de incêndio/explosão, destacando a intenção específica do agente e a presença ou não de perigo comum.

### Conceitos
- **Dano qualificado**: Crime contra o patrimônio alheio, com intenção específica de ofender o patrimônio da vítima
- **Incêndio**: Crime que cria perigo comum a um número indeterminado de pessoas
- **Explosão**: Crime que cria perigo comum a um número indeterminado de pessoas

### Referências legais
- Art. 250 do CP
- Art. 251 do CP
- Lei n.º 13.531/2017

### Jurisprudência
- Súmula N STJ
- HC 245.457/MG, Rel. Ministro NEFI CORDEIRO

### Dicas de prova
- Distinção entre crimes contra o patrimônio e crimes de incêndio/explosão
- Intenção específica do agente em crimes qualificados
- Princípio da estrita legalidade e vedação à analogia in malam partem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 250 do CP", "Art. 251 do CP", "Lei n.º 13.531/2017"], "jurisprudence": ["Súmula N STJ", "HC 245.457/MG, Rel. Ministro NEFI CORDEIRO"], "confidence": 0.8, "extracted_at": "2026-05-27T08:50:40.156853+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=121", "doc_key": "49eacf1e5a5817d0516809a17649e6fe"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '90f3b9b6325bf14161808b0516fb3d2eb7ab75aa3d7b0dc737891a4b2b5ac66a'),
  ('cpiuris2025::6c52a54520ba0eba98eb902f566502fc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Abandono de Animais em Propriedade Alheia', '## Abandono de Animais em Propriedade Alheia

O crime de abandono de animais em propriedade alheia é definido como o ato de introduzir ou deixar animais em imóvel alheio sem consentimento, resultando em prejuízo. A pena é detenção de 15 dias a 6 meses ou multa.

### Conceitos
- **Prejuízo**: Dano ou perda sofrida pela vítima
- **Transação Penal**: Negociação com o Estado para reduzir a pena
- **Suspensão Condicional do Processo**: Suspensão da execução da pena condicionalmente

### Referências legais
- Art. 164 CP

### Dicas de prova
- Diferenciar entre o crime de abandono e o crime de introdução de animais em propriedade alheia sem prejuízo
- Verificar a situação econômico-financeira da vítima para determinar a pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 164 CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:51:04.501759+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=121", "doc_key": "6c52a54520ba0eba98eb902f566502fc"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7699a336f68ab6ce58271fa76e0a9269f5a93abc2c062924000db58c9984f30e'),
  ('cpiuris2025::4287bfe7bc8ba351c464d7cef3857807', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra o Patrimônio', '## Crimes contra o Patrimônio

Resumo objetivo: Crimes contra o patrimônio são de ação múltipla, material e consumam-se no momento do prejuízo. O crime é privado ou público incondicionado, dependendo da natureza do dano.

### Conceitos
- **Ação Múltipla**: O crime é de ação múltipla, introduzir ou deixar.
- **Dano Material**: O crime é material, consumando-se no momento em que há o prejuízo.
- **Procedimento**: Somente se procede mediante queixa (art. 167 do CP).
- **Natureza do Dano**: O dano é simples ou qualificado, dependendo da natureza do prejuízo.
- **Ação Penal Privada**: A ação penal privada é para crimes de dano simples ou qualificado.
- **Ação Penal Pública Incondicionada**: A ação penal pública incondicionada é para demais infrações.
- **Consentimento do Proprietário**: Se houver o consentimento do proprietário ou possuidor, o fato será atípico.

### Referências legais
- Art. 167 do CP

### Dicas de prova
- Distinção entre apropriação indébita previdenciária e apropriação indébita de bens públicos.
- Entendimento do STJ sobre crimes contra o patrimônio e contra a administração pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.122 (1)", "page_number": 122, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 167 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:51:43.756542+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=122", "doc_key": "4287bfe7bc8ba351c464d7cef3857807"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9f09fc0067e33742e37b78db4d7935d0019af0737fab3244156aed1256d99e76'),
  ('cpiuris2025::0302f39ab31102a6e82c822c84027061', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Princípios e Teorias Gerais', '## Princípios e Teorias Gerais

Resumo do texto sobre princípios aplicados em crimes específicos.

### Conceitos
- **Princípio da Consunção**: Aplicação de um princípio para limitar a responsabilidade do agente
- **Extorsão**: Ameaça com o fim de obter vantagem econômica
- **Receptação**: Crime de receber bem ilícito
- **Dano ao Patrimônio Público**: Prejuízo causado a bem público

### Referências legais
- Art. 155, § 2º do CP
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o princípio da consunção e sua aplicação nos crimes de receptação e porte ilegal de arma.
- Diferencie entre extorsão e ameaça, e como elas são tratadas no direito penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.122 (2)", "page_number": 122, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 155, § 2º do CP", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T08:52:17.846082+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=122", "doc_key": "0302f39ab31102a6e82c822c84027061"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a0e9a789e4e167249d514e8c9782e03798944ee8a636121c1448344937313fa0'),
  ('cpiuris2025::d7177eb12b03320462a47e859d4249a6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Dano ao Patrimônio', '## Dano ao Patrimônio

Rege-se o dano ao patrimônio com a punição de destruir, inutilizar ou deteriorar coisa alheia, podendo ser aumentada em caso de violência à pessoa ou grave ameaça.

### Conceitos
- **Dano ao Patrimônio**: Lesão causada a um bem alheio
- **Destruir**: Causing danos irreversíveis a uma coisa alheia
- **Inutilizar**: Deixar uma coisa alheia inoperante ou impraticável
- **Deteriorar**: Aumentar o valor de perda causada ao patrimônio

### Referências legais
- Art. 163 do Código Penal

### Dicas de prova
- Entenda a diferença entre ''destruir'' e ''deteriorar''.
- Não confunda o dano com a lesão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.123", "page_number": 123, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 163 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:52:41.104732+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=123", "doc_key": "d7177eb12b03320462a47e859d4249a6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a235e9b2586dec4c38f5c6dbecbf5db91af265b791df464c331b88de5836d4dc'),
  ('cpiuris2025::655f240eebc6fc83f82284067ccd02a3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Apropriação Indébita', '## Apropriação Indébita

Crime de apropriar-se de coisa alheia móvel, de que tem a posse ou detenção, com pena de reclusão de 1 a 4 anos e multa.

### Conceitos
- **Apropriar-se**: Tomar como própria coisa alheia
- **Posse ou detenção desvigiada**: Situação em que o agente não tem controle sobre a coisa
- **Dolo**: Elemento subjetivo do crime, que não se admite na modalidade culposa
- **Estelionato**: Delito que ocorre quando o sujeito recebe a coisa de boa-fé e já tem o dolo de se apropriar

### Referências legais
- Art. 168, caput; Art. 170 do CP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre apropriação indébita e estelionato
- Requisitos para a tipicidade da conduta: entrega voluntária do bem, posse ou detenção desvigiada, boa-fé do agente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.125", "page_number": 125, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 168, caput; Art. 170 do CP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T08:53:14.894404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=125", "doc_key": "655f240eebc6fc83f82284067ccd02a3"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4117e9c5322eac41172d1619c8491405b65052e884001d4ab85c0b6790741272'),
  ('cpiuris2025::68fa1f4e5293bf749aeef420bffc4962', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Apropriação Indébita Previdenciária', '## Apropriação Indébita Previdenciária

O art. 168-A estabelece a punição para deixar de repassar contribuições previdenciárias, considerando-se omissivo próprio e puro, pois o tipo descreve um comportamento negativo.

### Conceitos
- **Apropriação Indébita**: conduta que envolve a tomada de coisa alheia sem consentimento
- **Omissão**: falta de ação ou omissão de dever
- **Deixar de repassar**: negligência de cumprir obrigação legal
- **Contribuições Previdenciárias**: sacrifício obrigatório feito pelo empregador para a previdência social
- **Crime Omissivo**: conduta que não envolve a ocorrência de um fato positivo, mas sim a falta de ação ou omissão de dever

### Referências legais
- Art. 168-A do Código Penal
- Súmula 383/STF

### Jurisprudência
- RE 123456
- Tema da Apropriação Indébita Previdenciária

### Dicas de prova
- Entenda a diferença entre apropriação e omissão
- Conheça as características do crime omissivo próprio e puro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.126 (1)", "page_number": 126, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 168-A do Código Penal", "Súmula 383/STF"], "jurisprudence": ["RE 123456", "Tema da Apropriação Indébita Previdenciária"], "confidence": 0.8, "extracted_at": "2026-05-27T08:54:00.820917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=126", "doc_key": "68fa1f4e5293bf749aeef420bffc4962"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '83bb0c339c8a8dd37fe7a67c87d48ffbaf3d13b91edc307d6b1735dafc946412'),
  ('cpiuris2025::08d2f4eca1e0fd07015379b469eb32a2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Competência e procedimento administrativo para ação penal', '## Competência e procedimento administrativo para ação penal

A competência para processar contribuições previdenciárias é da Justiça Federal, exceto nos casos de contribuições do regime previdenciário próprio dos Estados, Distrito Federal e municípios, que passam a ser da Justiça Estadual. O procedimento administrativo prévio é necessário para a ação penal.

### Conceitos
- **Competência**: A competência é a autoridade judiciária responsável por processar um caso
- **Procedimento administrativo**: O procedimento administrativo é o processo pelo qual uma entidade pública se pronome sobre uma questão ou situação
- **Ação penal**: A ação penal é o processo judicial que visa punir um indivíduo por um crime
- **Contribuição previdenciária**: A contribuição previdenciária é uma obrigação tributária que deve ser cumprida pelos contribuintes

### Referências legais
- Art. 149, § 1º, da CF/88

### Jurisprudência
- STJ. 3ª Seção. REsp 1.982.304/SP
- RE 123456

### Dicas de prova
- Pergunte sobre a competência e procedimento administrativo para ação penal
- Entenda o conceito de contribuição previdenciária e sua importância no contexto do Direito Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.126 (2)", "page_number": 126, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 149, § 1º, da CF/88"], "jurisprudence": ["STJ. 3ª Seção. REsp 1.982.304/SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T08:54:32.441040+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=126", "doc_key": "08d2f4eca1e0fd07015379b469eb32a2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4eb75a728814f1375c4a38e3444a20c57f46f9587a6c26758017ffee913e87b9'),
  ('cpiuris2025::a05be988e8f9597f8024e1455c3f5d6c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Apropropriação Indébita e Tributação', '## Apropropriação Indébita e Tributação

Rejeição da denúncia se não houver condição de procedibilidade, inquérito policial não pode ser instaurado pela autoridade policial, tentativa é impossível, penas para não recolher contribuições ou benefícios devidos à previdência social.

### Conceitos
- **Apropropriação Indébita**: Fato que configura crime
- **Tentativa**: Impossível em crimes omissivos
- **Contribuições devidas à previdência social**: Importâncias destinadas à previdência social
- **Benefícios devidos à previdência social**: Prestação de segurado ou terceiro
- **Punibilidade**: Extinção da punibilidade após pagamento do débito tributário

### Referências legais
- Art. 142 do CTN
- Súmula Vinculante 2421

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre tentativa e omissão
- Entender a previsão de penas para não recolher contribuições ou benefícios devidos à previdência social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.127 (1)", "page_number": 127, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 142 do CTN", "Súmula Vinculante 2421"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T08:55:05.872903+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=127", "doc_key": "a05be988e8f9597f8024e1455c3f5d6c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ea4154147ffd27e7b62a15158843d1af53284da9cbbd5495f11ab820bb1cb5ed'),
  ('cpiuris2025::d7c15bf1a3437a2710c14a180400d6bc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Princípio da Insignificância', '## Princípio da Insignificância

A aplicação do princípio da insignificância é questionada no contexto de crimes de sonegação de contribuição previdenciária e apropriação indébita previdenciária. A tendência jurisprudencial é não ser possível a exclusão da tipicidade material desses crimes.

### Conceitos
- **Princípio da Insignificância**: Regra que exclui a punibilidade por ilícitos de baixa gravidade
- **Tipicidade Material**: Característica fundamental para a configuração do crime

### Referências legais
- Art. 168-A do CP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a tipicidade material e a gravidade dos crimes de sonegação de contribuição previdenciária e apropriação indébita previdenciária.
- Conheça a tendência jurisprudencial sobre o princípio da insignificância em relação a esses crimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.127 (2)", "page_number": 127, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 168-A do CP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T08:55:44.137108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=127", "doc_key": "d7c15bf1a3437a2710c14a180400d6bc"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '515ea5bfe37140d80313b02e295187b6bd287e9af9bce3c4c5c05d6837ca0984'),
  ('cpiuris2025::cc2c1f99be529b5c59cd00a0f9251bca', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Apropriação Indébita', '## Apropriação Indébita

O crime de apropriação indébita é classificado em infrações de menor potencial ofensivo, com pena de detenção ou multa. A propriedade da Previdência Social aumenta a reprovabilidade do agente que atenta contra este bem jurídico supraindividual.

### Conceitos
- **Apropriação Indébita**: Infração de menor potencial ofensivo
- **Previdência Social**: Bem jurídico protegido que aumenta a reprovabilidade do agente
- **Erro**: Caso que justifica a punição mais branda
- **Furto Privilegiado**: Pena reduzida para o criminoso primário

### Referências legais
- Art. 169 do CP

### Jurisprudência
- REsp 1783334/PB

### Dicas de prova
- Diferenciar entre apropriação indébita e furto privilegiado
- Entender o conceito de Previdência Social e seu impacto na punição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.128 (1)", "page_number": 128, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 169 do CP"], "jurisprudence": ["REsp 1783334/PB"], "confidence": 0.8, "extracted_at": "2026-05-27T08:56:15.040305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=128", "doc_key": "cc2c1f99be529b5c59cd00a0f9251bca"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '98d51244866d9b9985c1b7315a5ff2def97cd58b842baf0b9b1b1a24b3c29058'),
  ('cpiuris2025::5f923ba8e66a84375c230562bb02b90c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Responsabilidade de Hermes', '## Responsabilidade de Hermes

Hermes vende um veículo para terceiro, mantendo-o e usando o valor recebido para despesas pessoais. Ele deve responder por qual crime?

### Conceitos
- **Furto simples**: Ouro de uma joalheria roubado
- **Peculato-furto**: Aquisição ilegal de bens públicos ou privados por funcionário público
- **Furto mediante fraude**: Roubo com engano ou fraude

### Referências legais
- Art. 157 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre Furto Simples e Peculato-Furto
- Importância da boa-fé no caso de terceiro bem-entendido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.128 (2)", "page_number": 128, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T08:56:35.016832+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=128", "doc_key": "5f923ba8e66a84375c230562bb02b90c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '22502bd4841fb674ead640b940d433f9eb20fd2fb5f3fe0c51e2922cf44be0c8'),
  ('cpiuris2025::5bd05b2d8383db7f3b795ea03fc88797', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — AproPRIAÇÃO INDÉBITA', '## AproPRIAÇÃO INDÉBITA

O crime de apropriação indébita pressupõe que o agente já tenha posse do objeto, diferente do furto que implica ausência de posse.

### Conceitos
- **Peculato-desvio**: Forma específica de apropriação indébita
- **Apropriação Indébita**: Crime que pressupõe o agente já ter posse do objeto

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciar apropriação indébita de furto
- Entender que o peculato-desvio é uma forma específica de apropriação indébita', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.129", "page_number": 129, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:57:04.553479+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=129", "doc_key": "5bd05b2d8383db7f3b795ea03fc88797"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3e1fda3ed1acb8986025f060e20ae85f03c75e57deef483dd0987402d9119a5c'),
  ('cpiuris2025::caeffefb0b793758c05289aa6487f40f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Estelionato', '## Estelionato

O estelionato é um crime contra o patrimônio que envolve fraude, dissimulação e meios enganosos para obter vantagem ilícita em prejuízo alheio.

### Conceitos
- **Estelionato**: Crime contra o patrimônio que envolve fraude, dissimulação e meios enganosos.
- **Vantagem ilícita**: Benefício obtido em prejuízo alheio
- **Fraude**: Método enganoso utilizado para obter vantagem ilícita
- **Ardil**: Método enganoso utilizado para obter vantagem ilícita

### Referências legais
- Art. 171 do CP

### Jurisprudência
- Súmula 17 do STJ

### Dicas de prova
- Entenda a diferença entre fraude material e moral.
- Conheça as hipóteses de estelionato, como a falsidade documental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.131", "page_number": 131, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 171 do CP"], "jurisprudence": ["Súmula 17 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T08:57:36.563131+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=131", "doc_key": "caeffefb0b793758c05289aa6487f40f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e405aa0d5304ab3388f130880c749547ed73d3959b8a15c7eb9e0084debcaf2a'),
  ('cpiuris2025::e16dd5ca1adbc780501b309a40a471a7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Fraude no pagamento por meio de cheque', '## Fraude no pagamento por meio de cheque

O crime de fraude no pagamento por meio de cheque é cometido quando o emitente do cheque emite cheque sem suficiente provisão de fundos em poder do sacado, ou lhe frustra o pagamento.

### Conceitos
- **Suficiente provisão de fundos**: Quantidade mínima de dinheiro que deve estar disponível na conta do sacado para garantir o pagamento
- **Sacado**: Pessoa física ou jurídica que recebe o cheque e deve pagar a quantia expressa nele

### Referências legais
- Art. 183 do CP

### Dicas de prova
- Verifique se o emitente do cheque tem suficiente provisão de fundos em poder do sacado
- Entenda a noção de sacado e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 183 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:58:03.113691+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=132", "doc_key": "e16dd5ca1adbc780501b309a40a471a7"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4d59a32586cbbbdb94c3394b2252674c345eeaee512d588fae00d8f89515254a'),
  ('cpiuris2025::2b05d44a253bac13e34bb11730a2da51', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsificação de Cheque', '## Falsificação de Cheque

O sujeito passivo pode ser qualquer pessoa e responderá pelo delito de estelionato se for enganar terceiros com um cheque falsificado.

### Conceitos
- **Estelionato**: Delito que consiste na ação de enganar terceiros para obter vantagem ou lucro
- **Falsificação**: Ação de criar ou alterar documentos, como cheques, com o objetivo de enganar terceiros
- **Sujeito passivo**: Pessoa que é alvo do delito e pode ser responsabilizada pelo crime

### Referências legais
- Art. 171, caput
- Código Penal

### Dicas de prova
- Distinção entre estelionato propriamente dito e outras figuras criminais
- Importância de identificar o sujeito passivo no crime de falsificação de cheque', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 171, caput", "Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T08:58:37.075226+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=132", "doc_key": "2b05d44a253bac13e34bb11730a2da51"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e9b0f638709f6572be3b5a2a44e51f702c1f11101ad8a1ed0cf9689f7a889383'),
  ('cpiuris2025::41704bfc58b13c7fddaedd1428ee79fe', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Emissão de Cheque Sem Fundos e Estelionato', '## Emissão de Cheque Sem Fundos e Estelionato

O crime de emissão de cheque sem fundos não se configura quando o cheque é emitido pós-datado, pois o indivíduo não emitiu o cheque sem fundos. A reparação do dano antes do recebimento da denúncia obsta a instauração da ação penal, conforme Súmula 554 do STF.

### Conceitos
- **Emissão de Cheque Sem Fundos**: Crime que não se configura quando o cheque é emitido pós-datado
- **Estelionato**: Modo de estelionato em comento, onde a reparação do dano antes do recebimento da denúncia obsta a instauração da ação penal
- **Súmula 554 do STF**: Estabelece que o pagamento de cheque emitido sem provisão de fundos, após o recebimento da denúncia, não obsta o prosseguimento da ação penal
- **Súmula 246 do STF**: Estabelece que comprovado não ter havido fraude, não se configura o crime de emissão de cheque sem fundos

### Referências legais
- Art. 70 § 4º do Código de Processo Penal
- Súmula 554 do Supremo Tribunal Federal
- Súmula 246 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre emissão de cheque pós-datado e crime de estelionato
- Reparação do dano antes do recebimento da denúncia
- Competência para os crimes de estelionato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 70 § 4º do Código de Processo Penal", "Súmula 554 do Supremo Tribunal Federal", "Súmula 246 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T08:59:20.460961+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=133", "doc_key": "41704bfc58b13c7fddaedd1428ee79fe"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cfb4422a19587ee25db834ff789f3a4cea332199ebffd8c60eb7c7128d958f29'),
  ('cpiuris2025::624a85407e7c57c45f2ba4079489d0c4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Competência para julgamento do estelionato', '## Competência para julgamento do estelionato

A competência para julgamento do estelionato mudou com a Lei nº 14.155/2021, que prevê que o foro competente é o local onde se deu a recusa do pagamento pelo sacado, desde que o banco sacado não esteja no domicílio da vítima.

### Conceitos
- **Competência**: A competência é a capacidade do juiz ou tribunal de julgar um caso específico.
- **Lei nº 14.155/2021**: Lei que alterou a regra de competência para julgamento do estelionato
- **Domicílio da vítima**: O local onde se encontra o sacado, no caso de emissão de cheque sem fundos.
- **Foro competente**: O tribunal ou juiz que tem a competência para julgar um caso específico.

### Referências legais
- Art. 70, § 4º, do CPP
- Súmula 48 do STJ
- Lei nº 14.155/2021

### Jurisprudência
- RE 123456
- Súmula 244 do STJ
- Súmula 521 do STF

### Dicas de prova
- Destacar a mudança de regra de competência com a Lei nº 14.155/2021
- Entender o conceito de domicílio da vítima e foro competente
- Conhecer as Súmulas 244 do STJ e 521 do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 70, § 4º, do CPP", "Súmula 48 do STJ", "Lei nº 14.155/2021"], "jurisprudence": ["RE 123456", "Súmula 244 do STJ", "Súmula 521 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T08:59:58.313905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=133", "doc_key": "624a85407e7c57c45f2ba4079489d0c4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'aafd0e36978db7b30d6f0e64cc037ae05da73c921602fe9f176774c0b36213ae'),
  ('cpiuris2025::3cd64a8bd6255708ac25b59ff4b03d7f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Reparação do dano em estelionato e fraude eletrônica', '## Reparação do dano em estelionato e fraude eletrônica

A reparação do dano antes ou após a sentença não impede a ação penal, exceto para o estelionato previsto no art. 171, § 2º, inciso VI, do CP. A fraude eletrônica é punida com pena de reclusão de 4 a 8 anos e multa.

### Conceitos
- **Arrependimento posterior**: causa de diminuição de pena
- **Atenuante genérica**: aplicação do art. 65, inciso III, alínea b, parte final, do CP
- **Fraude eletrônica**: punição mais grave para aqueles que se utilizam de redes sociais para cometer fraude

### Referências legais
- Art. 16 do CP
- Art. 65, inciso III, alínea b, parte final, do CP
- Súmula 554 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre a reparação do dano antes e após a sentença
- Entender a distinção entre o estelionato previsto no art. 171, § 2º, inciso VI, do CP e outras hipóteses', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.134 (1)", "page_number": 134, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 16 do CP", "Art. 65, inciso III, alínea b, parte final, do CP", "Súmula 554 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:00:42.762750+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=134", "doc_key": "3cd64a8bd6255708ac25b59ff4b03d7f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b74ba61228ac7240826c7880a285df70df60911f8057882c23e770f7f3132551'),
  ('cpiuris2025::051ecac2db3a516adf043b36feada462', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Golpes e fraude digital', '## Golpes e fraude digital

A vítima é ludibriada com informações falsas, como contato telefônico ou e-mail, para efetuar depósitos bancários. O crime é considerado se o resultado gravoso for relevante.

### Conceitos
- **Golpe**: Ato de enganar alguém com informações falsas
- **Fraude digital**: Uso de tecnologia para enganar ou prejudicar alguém

### Referências legais
- Art. 147, § 2º-B do Código Penal

### Dicas de prova
- Distinção entre golpe e fraude digital
- Relevância do resultado gravoso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.134 (2)", "page_number": 134, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 147, § 2º-B do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:01:02.398419+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=134", "doc_key": "051ecac2db3a516adf043b36feada462"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cc65c365096b950f4c383539ab781cc773253b122415f8dd6df83e9f53b46eff'),
  ('cpiuris2025::6d52d4aaf0f519d6a94b361b7ffb9147', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Estelionato e Fraudes', '## Estelionato e Fraudes

O estelionato é um crime contra o patrimônio que pode ser instantâneo ou permanente, dependendo da situação. A pena aumenta-se de um terço se o crime é cometido em detrimento de entidade de direito público ou instituto de economia popular.

### Conceitos
- **Estelionato**: crime contra o patrimônio
- **Fraude**: ação de enganar alguém para obter vantagem
- **Pena aumentada**: aumento da pena imposta ao autor do crime
- **Crime instantâneo**: ocorre quando a consumação do crime é imediata e não há prazo prescricional
- **Crime permanente**: ocorre quando a consumação do crime é postergada no tempo e há prazo prescricional

### Referências legais
- Art. 14.155/2021

### Jurisprudência
- {''term'': ''Súmula 456/STF'', ''definition'': ''relevância da definição do início do prazo prescricional no crime permanente''}

### Dicas de prova
- Distinção entre crime instantâneo e permanente
- Relevância da definição do início do prazo prescricional
- Aumento de pena em casos de estelionato contra entidades públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.135 (1)", "page_number": 135, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 14.155/2021"], "jurisprudence": ["{''term'': ''Súmula 456/STF'', ''definition'': ''relevância da definição do início do prazo prescricional no crime permanente''}"], "confidence": 0.8, "extracted_at": "2026-05-27T09:01:40.376657+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=135", "doc_key": "6d52d4aaf0f519d6a94b361b7ffb9147"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '1cde82213854bfbe1f13fd8e7caaad5afd33fe075d96421dfd15b06e2f2065e5'),
  ('cpiuris2025::908349f4b37e4b5e9592fa5c1b2f317e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Estelionato Previdenciário', '## Estelionato Previdenciário

A continuidade delitiva é aplicável ao estelionato previdenciário, onde cada saque do beneficiário após a morte é considerado um novo crime.

### Conceitos
- **Continuidade Delitiva**: Aplicação de lei a uma série de atos criminosos que ocorrem em continuação uns aos outros
- **Estelionato Previdenciário**: Crime de fraude contra beneficiários de benefícios previdenciários

### Referências legais
- Art. 171, § 4º da Lei n.º 14.155/2021

### Jurisprudência
- Súmula 523 do STJ

### Dicas de prova
- Distinção entre continuidade delitiva e crime permanente
- Relevância do resultado gravoso para a aplicação da causa de aumento de pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.135 (2)", "page_number": 135, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 171, § 4º da Lei n.º 14.155/2021"], "jurisprudence": ["Súmula 523 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T09:02:13.426016+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=135", "doc_key": "908349f4b37e4b5e9592fa5c1b2f317e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3baae179fc9d79d8f3eb07b8f4571fd082d8374810e4b7c95247d03d4960047f'),
  ('cpiuris2025::ae94995be6dc2eca57a8446110f74e8b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Ação penal para o estelionato', '## Ação penal para o estelionato

A Lei nº 13.964/2019 preveu que a ação penal para o estelionato será pública condicionada à representação, salvo em casos específicos como crianças, adolescentes, pessoas com deficiência mental ou idosos. A discussão relevante é sobre a retroatividade da nova previsão.

### Conceitos
- **Ação penal**: procedimento judicial que visa punir o autor de um crime
- **Representação**: necessária para a ação penal ser iniciada
- **Retroatividade**: aplicação de uma norma legal a situações anteriores
- **Pacote Anticrime**: Lei que introduziu mudanças no Código Penal
- **Estelionato**: crime de fraude ou engano

### Referências legais
- Art. 171 do CP
- Lei nº 13.964/2019

### Jurisprudência
- HC 610.201/SP
- STF. 2ª Turma. ARE 1230095 AgR

### Dicas de prova
- Entenda a diferença entre ação penal pública e condicionada à representação.
- Conheça as exceções para a aplicação da nova previsão legal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.136 (1)", "page_number": 136, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 171 do CP", "Lei nº 13.964/2019"], "jurisprudence": ["HC 610.201/SP", "STF. 2ª Turma. ARE 1230095 AgR"], "confidence": 0.8, "extracted_at": "2026-05-27T09:02:51.865355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=136", "doc_key": "ae94995be6dc2eca57a8446110f74e8b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0717d29c5b869513aa739f2a35a94344776498dc167411de1b2fdee607777ba2'),
  ('cpiuris2025::81607cea7a8f40a1eb060489c955aeef', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Competência nos crimes de estelionato', '## Competência nos crimes de estelionato

A competência nos crimes de estelionato foi alterada pelo art. 70, § 4º, do CPP, que define a competência pelo local do domicílio da vítima para os crimes praticados mediante depósito, por emissão de cheques ou transferência de valores.

### Conceitos
- **Competência**: A capacidade jurídica de um juiz ou tribunal decidir sobre uma questão específica
- **Estelionato**: Falso engano para obter vantagem de alguém
- **Depósito**: O ato de entregar algo em segurança para outra pessoa
- **Emissão de cheques**: O ato de emitir um cheque para pagar uma dívida
- **Transferência de valores**: O ato de transferir dinheiro de um lugar para outro

### Referências legais
- Art. 70, § 4º, do CPP
- Lei nº 14.155/2021

### Jurisprudência
- HC 583.837/SC
- STJ. 3ª Seção. CC 180.832-RJ

### Dicas de prova
- Entenda a alteração da competência nos crimes de estelionato e como ela se aplica às diferentes situações.
- Identifique o artigo do CPP que regula a competência nos crimes de estelionato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.136 (2)", "page_number": 136, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 70, § 4º, do CPP", "Lei nº 14.155/2021"], "jurisprudence": ["HC 583.837/SC", "STJ. 3ª Seção. CC 180.832-RJ"], "confidence": 0.8, "extracted_at": "2026-05-27T09:03:24.533444+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=136", "doc_key": "81607cea7a8f40a1eb060489c955aeef"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e6828b29013d99fd5cf24dcbf3560060227b19962be46ce7a056d4889fb121dc'),
  ('cpiuris2025::43d6e623c9d11d0acbaa347db08cf43b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra o Patrimônio', '## Crimes contra o Patrimônio

Lei nº 14.478 introduziu o art. 171-A no Código Penal, definindo crimes contra o patrimônio relacionados a ativos virtuais e valores mobiliários.

### Conceitos
- **Estelionato**: Falsidade ideacional ou material com o objetivo de obter vantagem ilícita
- **Duplicata Simulada**: Emissão de fatura, duplicata ou nota de venda que não corresponde à mercadoria vendida
- **Crimes contra o Sistema Financeiro Nacional**: Tipificados na Lei nº 7.492/86

### Referências legais
- Art. 171-A do Código Penal
- Art. 109, inc. VI da Constituição

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre estelionato e duplicata simulada
- Conflito de normas envolvendo art. 171-A e crimes contra o Sistema Financeiro Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 171-A do Código Penal", "Art. 109, inc. VI da Constituição"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:04:04.735882+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=137", "doc_key": "43d6e623c9d11d0acbaa347db08cf43b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b4358467ae555dd609fa043c5ce391a0c1a5ecfad586351823f73ced882e2593'),
  ('cpiuris2025::454103fb4ab5705054a0a8c33832e0f4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Abuso de Incapazes', '## Abuso de Incapazes

O crime de abuso de incapazes é formal e tem pena de reclusão de 2 a 6 anos, com multa. É infração de maior potencial ofensivo.

### Conceitos
- **Abuso de Incapazes**: conduta que induz uma pessoa a praticar um ato em prejuízo próprio ou de terceiro
- **Formalidade do Crime**: o crime é formal, bastando a potencialidade do dano
- **Pena**: reclusão de 2 a 6 anos, com multa

### Referências legais
- Art. 182 do CP

### Dicas de prova
- Diferenciar entre abuso de incapazes e outros tipos de exploração
- Entender a formalidade do crime e as consequências legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 182 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:04:26.395961+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=137", "doc_key": "454103fb4ab5705054a0a8c33832e0f4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e5813ed4829303fcaca67aaf338f439a159ee75aa587eff1cc04846e92ffd74a'),
  ('cpiuris2025::c127c1c60f5a3be32409733699003547', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Abuso de incapaz', '## Abuso de incapaz

O crime de abusar de incapaz envolve induzir alguém a praticar um ato que cause prejuízo ao incapaz ou a outra pessoa, com o intuito de proveito próprio ou alheio.

### Conceitos
- **Abuso**: Aproveitar-se ou prevalecer-se de uma condição para tirar vantagem
- **Induzir**: Fazer nascer a ideia na mente de outrem
- **Dolo específico**: Intuito de proveito próprio ou alheio
- **Consumação do crime**: Instante em que a vítima pratica o ato a que foi induzida

### Referências legais
- Art. 174, inc. I, c/c o Código de Processo Civil
- Súmula 273 do STF

### Jurisprudência
- RE 456.123
- Tema repetitivo: abuso de incapaz

### Dicas de prova
- Diferenciar entre abuso e indução
- Entender o conceito de dolo específico
- Conhecer a regra de consumação do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.138 (1)", "page_number": 138, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 174, inc. I, c/c o Código de Processo Civil", "Súmula 273 do STF"], "jurisprudence": ["RE 456.123", "Tema repetitivo: abuso de incapaz"], "confidence": 0.8, "extracted_at": "2026-05-27T09:04:57.621550+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=138", "doc_key": "c127c1c60f5a3be32409733699003547"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c04de5e6c9514560fb0a45f7a342c04667857de8c7b6473185d7c2c0c3085a0f'),
  ('cpiuris2025::8ddd3e7a99c0ab8d056a54a396134199', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Fraude no Comércio', '## Fraude no Comércio

Configura crime de fraude no comércio a conduta de enganar o adquirente ou consumidor, seja vendendo mercadoria falsificada ou deteriorada, ou entregando uma mercadoria por outra.

### Conceitos
- **Engano**: falta de veracidade na informação
- **Falsificação**: transformação ilegal de um produto para fazê-lo parecer diferente do que é
- **Deterioração**: perda ou diminuição da qualidade de um produto
- **Comércio**: atividade econômica relacionada à compra e venda de mercadorias
- **Adquirente**: pessoa que compra uma mercadoria
- **Consumidor**: pessoa física que compra uma mercadoria para uso pessoal

### Referências legais
- Art. 182 do CP
- Código Penal (Brasil)

### Dicas de prova
- Distinção entre fraude no comércio e estelionato
- Consumação do crime independe do prejuízo à vítima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.138 (2)", "page_number": 138, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 182 do CP", "Código Penal (Brasil)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:05:34.512462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=138", "doc_key": "8ddd3e7a99c0ab8d056a54a396134199"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '404e9debd94ba1aabee90b654e49e4ad8139074ac9271d53ee4f9809237f2642'),
  ('cpiuris2025::46eeefecf0b48e08e9641ac667adccef', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Estelionato e Fraudes', '## Estelionato e Fraudes

O estelionato é um crime próprio que se caracteriza pela prática de fraude contra o patrimônio, geralmente em atividade comercial. A lei não foi revogada pelas Leis n.º 8.078/1990 e 8.137/1990.

### Conceitos
- **atividade comercial**: exigência de continuidade, profissionalização e habitualidade
- **princípio da especialidade**: aplicação do princípio para crimes cometidos no âmbito da atividade comercial
- **natureza material**: característica do crime de consumir-se no momento em que o ofendido é enganado
- **privilégio**: instituto que permite ao juiz reduzir a pena de 1/3 a 2/3

### Referências legais
- Art. 155, § 2º do CP
- Lei n.º 8.078/1990
- Lei n.º 8.137/1990

### Dicas de prova
- Distinção entre estelionato e fraude contra a fidelidade
- Entendimento do princípio da especialidade no estelionato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.139 (1)", "page_number": 139, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 155, § 2º do CP", "Lei n.º 8.078/1990", "Lei n.º 8.137/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:06:07.769370+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=139", "doc_key": "46eeefecf0b48e08e9641ac667adccef"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8e5c781bb5d9e02ef8934fca6a5338391e359408d3a912aec4321b42e0a94853'),
  ('cpiuris2025::6f66f53b40c6100052dae32c53b30a12', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Procedimento e Pena em Crime', '## Procedimento e Pena em Crime

Resumo objetivo: O parágrafo único prevê que o crime só pode ser procedido mediante representação e que o juiz pode deixar de aplicar a pena, dependendo da situação. A pena pode ser perdida se o sujeito não pagar as comodidades.

### Conceitos
- **Representação**: O requisito para proceder com o crime
- **Pena**: A sanção aplicada ao autor do crime
- **Perdão Judicial**: A possibilidade de a pena ser perdida, dependendo da situação
- **Calote**: Ilícito civil que ocorre quando o sujeito não paga as comodidades
- **Pendura**: Tradição nos cursos de Direito que se refere à possibilidade de perdão da pena

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegadinha ou distinção relevante para prova: A importância do parágrafo único no procedimento do crime
- Diferenciar entre perdão judicial e calote', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.139 (2)", "page_number": 139, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T09:06:33.633219+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=139", "doc_key": "6f66f53b40c6100052dae32c53b30a12"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f48546853c27d1dbd317236d6c53995cfb400db13ec6aab6d6b37378d5e44f31'),
  ('cpiuris2025::93c6d3cbff9f34d13049fdda55d55d65', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Fraudes e Abusos na Administração de Sociedades por Ações', '## Fraudes e Abusos na Administração de Sociedades por Ações

O artigo 177 do CP criminaliza a conduta de promover fundação de sociedade por ações com afirmação falsa ou ocultação de fatos, punindo-se com reclusão de 1 a 4 anos e multa.

### Conceitos
- **fraude**: conduta que visa enganar ou prejudicar alguém
- **abusos**: práticas ilícitas na administração de sociedades por ações
- **infração formal**: crime que não exige resultado lesivo aos acionistas
- **crimes contra a economia popular**: tipos de crimes previstos na Lei n.º 1.521/1951

### Referências legais
- Art. 177 do CP

### Dicas de prova
- Reconheça a diferença entre fraude e abuso na administração de sociedades por ações
- Entenda o conceito de infração formal e como se aplica ao crime previsto no art. 177 do CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 177 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:07:14.508366+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=140", "doc_key": "93c6d3cbff9f34d13049fdda55d55d65"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f5d3c6928e7722c0075e95907e80a62c44e1bc081fe7febbd71fe51738c95557'),
  ('cpiuris2025::137d6f6a7c82f10eacfbe50d48c3dcec', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Título de Crédito e Depósito', '## Título de Crédito e Depósito

O crime é comum, relacionado ao título de crédito e depósito de mercadorias.

### Conceitos
- **Depósito**: Ação de deixar uma mercadoria em um armazém geral
- **Título de Crédito**: Documento que serve como prova da propriedade e do depósito de uma mercadoria
- **Warrant**: Garantia real em relação às mercadorias depositadas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre o conhecimento de depósito e o warrant
- Lembre-se de que o depósito é uma ação e o título de crédito é um documento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:07:35.482624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=140", "doc_key": "137d6f6a7c82f10eacfbe50d48c3dcec"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '06974ec429f4c9035bfb00539e6c200ee6bb2cb1fb4df52cd9343a29479e1677'),
  ('cpiuris2025::7a409666a85eeb0de9357a51c8af737f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Fraude à Execução', '## Fraude à Execução

O crime de fraude à execução é definido como a conduta de frustrar o pagamento devido aos credores, podendo ser cometida por alienação, desvio, destruição ou danificação de bens ou simulação de dívidas.

### Conceitos
- **Fraude à Execução**: conduta que frustra o pagamento devido aos credores
- **Alienação**: venda ou transferência de bens sem a devida autorização
- **Desvio**: uso indevido de bens alheios
- **Destruição**: dano intencional a bens
- **Simulação de dívidas**: falsificação de dívidas para evitar o pagamento

### Referências legais
- Art. 179, Código Penal

### Dicas de prova
- Entenda a distinção entre fraude à execução e outros crimes contra o patrimônio
- Conheça as regras de decadência e transação penal no crime de estelionato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.141", "page_number": 141, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 179, Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:08:09.327863+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=141", "doc_key": "7a409666a85eeb0de9357a51c8af737f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ec98aa674a9cbb6208afa4742a27519850fb51be188660d463bfe6f87190ff11'),
  ('cpiuris2025::55c0c3a13b19e1c9fa91bdd257646522', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Ações contra o patrimônio', '## Ações contra o patrimônio

Resumo objetivo: A ação contra o patrimônio pode ser pública condicionada à representação, com exceções que são processadas por meio de ação penal pública incondicionada.

### Conceitos
- **Ação pública**: Processo em que o Estado é parte do litígio
- **Representação**: Obrigação de alguém de denunciar um crime cometido por outrem
- **Ação penal pública condicionada**: Processo em que a ação é pública, mas depende da representação do vítima para prosseguir
- **Ação penal pública incondicionada**: Processo em que a ação é pública e não depende da representação do vítima

### Referências legais
- Art. 79, § 2º, da Lei nº 9.039/96

### Dicas de prova
- Diferenciar entre ação pública condicionada e incondicionada
- Entender o papel da representação na ação pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.142", "page_number": 142, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 79, § 2º, da Lei nº 9.039/96"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:08:44.583380+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=142", "doc_key": "55c0c3a13b19e1c9fa91bdd257646522"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '85531aa3a303bfba52983cd75e15d48f4371fb70e43d48fa66045c9331bf2b3c'),
  ('cpiuris2025::0294615b3009ebd7992f1b17843f0dd2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Receptação', '## Receptação

Receptação é o crime de adquirir, receber, transportar, conduzir ou ocultar coisa que sabe ser produto de crime, em proveito próprio ou alheio. A pena é de reclusão, de 1 a 4 anos, e multa.

### Conceitos
- **Receptação**: Adquirir, receber, transportar, conduzir ou ocultar coisa que sabe ser produto de crime
- **Dolo**: Necessário para a receptação
- **Crime antecedente**: Não necessário um prévio ajuste entre o autor do crime e o receptador
- **Ato infracional**: A coisa pode ser produto de ato infracional, mas não necessariamente de contravenção penal
- **Pena**: Reclusão, de 1 a 4 anos, e multa
- **Infração de médio potencial ofensivo**: A receptação é considerada infração de médio potencial ofensivo
- **Suspensão condicional do processo**: Admite-se suspensão condicional do processo e acordo de não persecução penal

### Referências legais
- Art. 180, CP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Dolo é necessário para a receptação
- O crime antecedente não é necessário um prévio ajuste entre o autor do crime e o receptador
- A coisa pode ser produto de ato infracional, mas não necessariamente de contravenção penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.144", "page_number": 144, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 180, CP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T09:09:25.230398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=144", "doc_key": "0294615b3009ebd7992f1b17843f0dd2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0bfa0271714e497afa7a817a6e0e6cda9ae39269a52b0378705f243b7beba1ed'),
  ('cpiuris2025::160631a5f3dddf8cdbfd829d7942d089', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Receptação', '## Receptação

O crime de receptação própria é material e consuma-se no momento em que a coisa ingressa na esfera do agente. A forma imprópria é formal, bastando a influência ao terceiro de boa-fé.

### Conceitos
- **Receptação**: Ato de receber ou adquirir coisa que sabe ser produto de crime
- **Tentativa**: Conduzimento da conduta criminosa em direção ao resultado previsto na lei
- **Influência**: Ato de influenciar o terceiro para que ele faça algo que sabe ser prejudicial à vítima
- **Dolo eventual**: O estado mental do agente que o obriga a realizar uma conduta, mesmo que não seja intencional

### Referências legais
- Art. 157, § 1º, CP
- STJ AgRg no REsp 1687766/DF
- STF Súmula 444

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre receptação própria e imprópria
- Entender a noção de tentativa na forma própria
- Conhecer o princípio da insignificância e sua aplicabilidade à receptação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.145 (1)", "page_number": 145, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157, § 1º, CP", "STJ AgRg no REsp 1687766/DF", "STF Súmula 444"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T09:10:02.721247+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=145", "doc_key": "160631a5f3dddf8cdbfd829d7942d089"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '977b0afc9df21b647e04069d149267d848dec3382a6f48d741ab664f6b84315b'),
  ('cpiuris2025::6f41b095d88ee94c88165022b6c79f53', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Desproporção entre valor e preço de cheques', '## Desproporção entre valor e preço de cheques

A desproporção entre o valor do cheque e seu preço pode ser considerada uma conduta culposa, pois o indivíduo tem condições de agir com maior diligência antes de adquirir o produto.

### Conceitos
- **Desproporção**: Diferença entre o valor do produto e seu preço
- **Culposa**: Conduzida por negligência ou imperícia
- **Potencial ofensivo**: Infração que pode causar dano a outrem

### Referências legais
- Art. 186 do Código Penal
- ...

### Jurisprudência
- 24 STJ: CC 112.108/SP
- ...

### Dicas de prova
- Pergunte sobre a definição de desproporção e sua relação com a conduta culposa
- Entenda a noção de potencial ofensivo e como se aplica à infração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.145 (2)", "page_number": 145, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 186 do Código Penal", "..."], "jurisprudence": ["24 STJ: CC 112.108/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:10:37.139148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=145", "doc_key": "6f41b095d88ee94c88165022b6c79f53"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3aad9bc1493762bc83b6fa0dff1886065d989cb9b99f189406bb37e6cf04b61e'),
  ('cpiuris2025::c580ffbcd64a81f1b52351cf0b0dda0b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Receptação', '## Receptação

A receptação é um crime que pode ser punível mesmo se o autor não for conhecido ou não for punível por qualquer razão. A autonomia da receptação preserva-se, mesmo em casos de crimes parasitários.

### Conceitos
- **Receptação**: Aquisição, recebimento, transporte, ocultação ou venda de coisa ilícita sem a devida causalidade
- **Parasitário**: Crime que se desenvolve em detrimento de outro crime

### Referências legais
- Art. 4º, § 4º do CP

### Dicas de prova
- Distinção entre receptação simples e culposa
- Pena aplicada na hipótese de receptação dolosa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.146 (1)", "page_number": 146, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 4º, § 4º do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:11:00.919219+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=146", "doc_key": "c580ffbcd64a81f1b52351cf0b0dda0b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '20affe0c30ef5a1ab902e310f7ec6970fc907b864ae96ad082f6f6661525c4f1'),
  ('cpiuris2025::8d2ca9b65465bad5a74f467c3a36fca5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Elemento subjetivo especial no crime', '## Elemento subjetivo especial no crime

O crime tem elemento subjetivo especial que inclui a finalidade de produção ou comercialização, exigindo um dolo específico. O dolo propriamente dito é o de ''deve saber ser produto de crime''.

### Conceitos
- **Dolo especial**: Tendência interna transcendente, dolo específico ou especial fim de agir
- **Dolo direto**: Expressão que abrange tanto o dolo eventual como o dolo direto
- **Deve saber ser produto de crime**: Exigência para o dolo propriamente dito

### Referências legais
- Art. 28 da Lei nº 9.434/1997

### Jurisprudência
- Súmula 373 do STJ
- RE 123456

### Dicas de prova
- Distinção entre dolo especial e dolo direto
- Importância da expressão ''deve saber ser produto de crime'' para o dolo propriamente dito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.146 (2)", "page_number": 146, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 28 da Lei nº 9.434/1997"], "jurisprudence": ["Súmula 373 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T09:11:23.933595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=146", "doc_key": "8d2ca9b65465bad5a74f467c3a36fca5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cb1a792e51f5dba94d9171ebd4ef7c4821d4bdbfc1d46fe7974508acc8226645'),
  ('cpiuris2025::c81deb72d536b2dc98127a758594eb34', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Receptação', '## Receptação

A receptação é punida com pena de 2 a 5 anos desde a Lei nº 13.330/2016, que especificou a conduta e diminuiu a pena em comparação com a receptação qualificada prevista no § 1º do art. 180.

### Conceitos
- **Receptação**: prática de receber ou receber-se algo com a finalidade de produção ou comercialização
- **Lei nº 13.330/2016**: Lei que especificou a conduta de receptação e diminuiu a pena em comparação com a receptação qualificada prevista no § 1º do art. 180
- **Receptação Qualificada**: prática de receber ou receber-se algo com a finalidade específica de produção ou comercialização, prevista no § 1º do art. 180 do CP

### Referências legais
- Art. 180-A do CP
- Lei nº 13.330/2016

### Dicas de prova
- Distinguir entre receptação e receptação qualificada
- Entender a finalidade da Lei nº 13.330/2016 em relação à receptação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.147", "page_number": 147, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 180-A do CP", "Lei nº 13.330/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:12:07.765033+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=147", "doc_key": "c81deb72d536b2dc98127a758594eb34"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '1b310c154dd56079c18e05a09ba88ab473a9b6135ea0457d708415e51b84fb2b'),
  ('cpiuris2025::1ba01c0c107250ba4a3e1848656476f3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Imunidades Penais', '## Imunidades Penais

Descreve as imunidades penais absolutas e relativas, estabelecidas pelo art. 181 e art. 182 do CP.

### Conceitos
- **Imunidade Penal Absoluta**: Isenção total da pena para o agente que cometeu um crime contra o patrimônio em prejuízo de cônjuge, ascendente ou descendente.
- **Imunidade Penal Material**: Isenção parcial da pena para o agente que cometeu um crime contra o patrimônio em prejuízo de pessoas não relacionadas por víncios de parentesco.
- **Imunidade Penal Relativa ou Processual**: Transformação da ação penal pública incondicionada em condicionada à representação, mas não isentando de pena.

### Referências legais
- Art. 181 do CP

### Dicas de prova
- Entenda a distinção entre imunidades penais absolutas e relativas.
- Conheça as exceções ao art. 181, como o caso de uniões estáveis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.149", "page_number": 149, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 181 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:12:38.321441+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=149", "doc_key": "1ba01c0c107250ba4a3e1848656476f3"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '47543f0d5c09950beffa980e68bee63e3c1d7793901280d804fde68f2047170e'),
  ('cpiuris2025::e7ca15d101523a3f7adb5349ebbdd06d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Exceções aos artigos antecedentes', '## Exceções aos artigos antecedentes

O artigo 183 prevê exceções ao disposto nos dois artigos anteriores, relacionadas à natureza do crime e à idade da vítima.

### Conceitos
- **art. 183**: prevê exceções ao disposto nos dois artigos anteriores
- **emprego de grave ameaça ou violência à pessoa**: exceção para crimes de roubo ou extorsão
- **participação do estranho no crime**: exceção ao disposto nos dois artigos anteriores
- **crime contra pessoa com idade igual ou superior a 60 anos**: exceção ao disposto nos dois artigos anteriores
- **instituições financeiras e prestadores de serviço de segurança privada**: áreas que beneficiam do aumento de pena

### Referências legais
- Art. 183 Código Penal

### Jurisprudência
- Súmula 343 STF

### Dicas de prova
- Entenda a exceção para crimes de roubo ou extorsão
- Conheça a idade mínima para configurar a exceção ao disposto nos dois artigos anteriores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.150", "page_number": 150, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 183 Código Penal"], "jurisprudence": ["Súmula 343 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T09:13:09.350619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=150", "doc_key": "e7ca15d101523a3f7adb5349ebbdd06d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0057da2253cdbbab38179b91e674411a14fb11ad31ad42763a0cbd87b70da9fb'),
  ('cpiuris2025::140eb688edf1eb2b75e5b97a98a04964', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Violação de Direitos Autorais', '## Violação de Direitos Autorais

Rege-se a pena de detenção ou multa por violação de direitos autorais, com benefícios da Lei n.º 9.099/1995.

### Conceitos
- **Direito Autoral**: Bem móvel que pode ser patrimônio ou moral
- **Pena de Detenção**: Pena imposta por violação de direitos autorais, com duração entre 3 meses e 1 ano
- **Lei n.º 9.099/1995**: Lei que dispõe sobre a transação penal e a suspensão condicional do processo
- **Direitos Morais**: Direitos insuscetíveis de alienação, imprescritíveis e irrenunciáveis relacionados à paternidade da obra

### Referências legais
- Art. 5º, inciso IX, CF/88
- Art. 216, CF/88
- Art. 41, Lei n.º 9.610/1998
- Lei n.º 9.610/1998

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre direitos patrimoniais e morais
- Benefícios da Lei n.º 9.099/1995
- Há crime impossível (art. 17 do CP) em casos de falsificação ou imitação grosseiras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.152", "page_number": 152, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 5º, inciso IX, CF/88", "Art. 216, CF/88", "Art. 41, Lei n.º 9.610/1998", "Lei n.º 9.610/1998"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T09:13:59.758594+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=152", "doc_key": "140eb688edf1eb2b75e5b97a98a04964"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7698c022ff84e1a5ee6b67a3424c3646a247c4d4c1c6353c14e9d3bdad73bfb7'),
  ('cpiuris2025::6d3624c089d927ab68e445a349ef84f3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Propriedade Imaterial', '## Crimes contra a Propriedade Imaterial

O crime é classificado como formal e não exige resultado naturalístico. Não há tipicidade se não houver autorização expressa.

### Conceitos
- **Dolo**: Elemento subjetivo do tipo
- **Formalidade**: O crime prescinde de resultado naturalístico
- **Lucro**: Intuito de direto ou indireto é necessário para as figuras qualificadas
- **Autorização expressa**: Necessária para a tipicidade da conduta

### Referências legais
- Art. 46 a 48, Lei n.º 9.610/1998

### Dicas de prova
- Diferenciar entre crimes formais e qualificados
- Entender o conceito de lucro direto e indireto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.153 (1)", "page_number": 153, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 46 a 48, Lei n.º 9.610/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:14:26.441076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=153", "doc_key": "6d3624c089d927ab68e445a349ef84f3"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cc7ad243e5ae613a36147c69fd67f6882a23856726645fb6b2e1c49fa7ec97c0'),
  ('cpiuris2025::7e0774a4acdc7b037f34be84299a3957', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Uso de obras protegidas por direito autoral', '## Uso de obras protegidas por direito autoral

O artigo 184, § 4º, do CP prevê exceções ao crime de violação de direitos autorais, como a cópia de obra intelectual para uso privado sem intuito de lucro. A Súmula 502 do STJ considera que a conduta de expor à venda CDs e DVDs piratas é típica nesse contexto.

### Conceitos
- **Materialidade**: Condição necessária para o crime ser cometido
- **Autoria**: Responsabilidade pelo ato criminoso
- **Direito autoral**: Direito que protege as obras intelectuais
- **Uso privado**: Uso da obra para fins pessoais, não comerciais
- **Intuito de lucro**: Motivo pelo qual a conduta é realizada

### Referências legais
- Art. 184, § 4º do CP
- Lei n.º 9.610/1998
- arts. 46 a 48

### Jurisprudência
- Súmula 502 do STJ

### Dicas de prova
- Entenda a distinção entre uso privado e intuito de lucro
- Conheça as exceções ao crime de violação de direitos autorais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.153 (2)", "page_number": 153, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 184, § 4º do CP", "Lei n.º 9.610/1998", "arts. 46 a 48"], "jurisprudence": ["Súmula 502 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T09:14:58.789291+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=153", "doc_key": "7e0774a4acdc7b037f34be84299a3957"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'af154fe6ccc1bb6a2d3d2e0599d43ad85939a46e3771c87579758504e38598dd'),
  ('cpiuris2025::dd26a148da1cf446aa8f4f05ac033317', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Violação de direitos autorais', '## Violação de direitos autorais

Resumo objetivo: A violação de direitos autorais é um crime contra a propriedade imaterial, que pode ser tratado como ação penal privada ou pública incondicionada. A exposição à venda de cópias não autorizadas de filmes sob a forma de DVD constitui um delito, que pode ser classificado como contravenção relativa à violação de objeto.

### Conceitos
- **Violação de direitos autorais**: Delito contra a propriedade imaterial
- **Ação penal privada**: Tratamento da ação penal para casos sem intuito de lucro
- **Ação penal pública incondicionada**: Tratamento da ação penal para crimes contra entidades públicas ou sociedades de economia mista

### Referências legais
- Art. 184, § 2º do CP

### Jurisprudência
- Súmula 574 do STJ
- Súmula 502 do STJ

### Dicas de prova
- Entenda a diferença entre ação penal privada e pública incondicionada
- Conheça as hipóteses de ação penal pública condicionada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.154", "page_number": 154, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 184, § 2º do CP"], "jurisprudence": ["Súmula 574 do STJ", "Súmula 502 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T09:15:40.609681+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=154", "doc_key": "dd26a148da1cf446aa8f4f05ac033317"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '84c6b668599d2049dd3496352247bf09eed1beebb6c80cd6626997aabfa7305f'),
  ('cpiuris2025::56c37ed2e3db1d7d82d50e34bcf8bb87', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Organização do Trabalho', '## Crimes contra a Organização do Trabalho

O bem jurídico tutelado é a organização do trabalho, e as condutas previstas no CP envolvem violência ou fraude para atrapalhar o desempenho do trabalho. A competência da Justiça Federal não alcança os delitos que atingem somente direitos individuais de trabalhadores.

### Conceitos
- **Atentado contra a liberdade de trabalho**: conduta que constrange alguém a exercer ou não exercer uma profissão, arte ou indústria
- **Parede**: abandono coletivo do trabalho, sinônimo de greve
- **Violência no trabalho**: uso de força física ou ameaças para coagir alguém a participar de uma paralisação de atividade econômica

### Referências legais
- Art. 197, CP
- Art. 200, CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre atentado contra a liberdade de trabalho e parede
- Entender que a competência da Justiça Federal não alcança os delitos que atingem somente direitos individuais de trabalhadores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.156", "page_number": 156, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 197, CP", "Art. 200, CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:16:16.029117+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=156", "doc_key": "56c37ed2e3db1d7d82d50e34bcf8bb87"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f924dd096dcdd8dc9f03670615e4ccd91eab5c6a04575f42e73fba9a8f0c59ac'),
  ('cpiuris2025::fad83a5d704b538d6e5edd9ef1c5d1e2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Organização do Trabalho', '## Crimes contra a Organização do Trabalho

Descreve os crimes de atentado contra a liberdade de contrato de trabalho e boicotagem violenta, bem como o crime de atentado contra a liberdade de associação.

### Conceitos
- **Atentado contra a liberdade de contrato de trabalho**: Constranger alguém a celebrar um contrato de trabalho mediante violência ou grave ameaça
- **Boicotagem violenta**: Constranger alguém a não fornecer ou não adquirir de outrem matéria-prima ou produto industrial agrícola
- **Atentado contra a liberdade de associação**: Constranger alguém a participar ou deixar de participar de determinado sindicato ou associação profissional
- **Direito à livre associação**: O direito de não se associar, garantido constitucionalmente

### Referências legais
- Art. 198 da Lei nº 7.853/89
- Súmula 284 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- RE 123456
- Tema repetitivo: crimes contra a liberdade de associação e trabalho

### Dicas de prova
- Distinção entre atentado contra a liberdade de contrato de trabalho e boicotagem violenta
- Entendimento majoritário sobre o tipo misto cumulativo dos crimes contra a organização do trabalho', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.157 (1)", "page_number": 157, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 198 da Lei nº 7.853/89", "Súmula 284 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["RE 123456", "Tema repetitivo: crimes contra a liberdade de associação e trabalho"], "confidence": 0.8, "extracted_at": "2026-05-27T09:16:53.843946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=157", "doc_key": "fad83a5d704b538d6e5edd9ef1c5d1e2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b1984bbc937d6cb2ae4fabcb7b377c5d4ed8b8cfaa1bf0b0ffc62a1034f612d7'),
  ('cpiuris2025::3a392a68bb019e7532b07a1973385903', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Paralisação de Trabalho e Violência', '## Paralisação de Trabalho e Violência

Crime praticado a título doloso sem especial fim de agir. Ação penal pública incondicionada. Paralisação de trabalho com violência ou perturbação da ordem consideradas crimes.

### Conceitos
- **Dolo**: Intenção de causar dano
- **Ação Penal Pública Incondicionada**: Não requer a concordância do agente com a punição
- **Paralisação de Trabalho**: Suspensão ou abandono coletivo de trabalho

### Referências legais
- Art. 200, § 1º da Lei nº 7.853/89

### Dicas de prova
- Distinção entre paralisação individual e coletiva
- Importância do concurso de empregados para considerar o abandono de trabalho como coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.157 (2)", "page_number": 157, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 200, § 1º da Lei nº 7.853/89"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:17:26.013014+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=157", "doc_key": "3a392a68bb019e7532b07a1973385903"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'fbafcceeb9af730f2d751897f0129e851f8ac2f43cc8d4221c25f7e988534e1e'),
  ('cpiuris2025::a4b4ab1e3bb25ebaf6eab5f14af0b616', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Organização do Trabalho', '## Crimes contra a Organização do Trabalho

Descreve crimes relacionados à greve, suspensão de trabalho e paralisação de serviços de interesse coletivo.

### Conceitos
- **Abandono coletivo**: Desligamento coletivo de trabalhadores
- **Greve**: Desligamento coletivo de trabalhadores
- **Suspensão coletiva**: Suspensão do trabalho por parte do empregador
- **Lock out**: Suspensão do trabalho por parte do empregador
- **Paralisação de trabalho**: Interrupção temporária do trabalho
- **Crime contra a Organização do Trabalho**: Infrações cometidas contra a ordem trabalhista

### Referências legais
- Art. 9º, caput, da CF
- Art. 201

### Dicas de prova
- Diferenciar entre abandono coletivo e greve
- Entender a diferença entre suspensão coletiva e lock out
- Identificar o sujeito ativo e passivo nos crimes contra a Organização do Trabalho', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.158", "page_number": 158, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 9º, caput, da CF", "Art. 201"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:17:59.759442+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=158", "doc_key": "a4b4ab1e3bb25ebaf6eab5f14af0b616"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0bf89d43b34e123e51a7195cecdd0f68029396b1b4eb3e78addd3712c4f67a9d'),
  ('cpiuris2025::8c3118506a1834d3c58c1d38adde6111', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Frustramento de Direitos Asssegurados pela Lei Trabalhista e Nacionalização do Trabalho', '## Frustramento de Direitos Asssegurados pela Lei Trabalhista e Nacionalização do Trabalho

Descreve os crimes de frustramento de direitos asssegurados pela lei trabalhista e nacionalização do trabalho, incluindo as penas e características dos crimes.

### Conceitos
- **Frustramento de Direito Asssegurado**: Ação que impede ou embaraça o curso normal do trabalho
- **Infração de Menor Potencial Ofensivo**: Caracterização da infração como menos grave e com pena menor
- **Ação Múltipla ou Conteúdo Variado**: Caracterização da infração que envolve mais de um tipo de conduta
- **Vulnerabilidade**: Condição que torna a vítima mais suscetível à exploração

### Referências legais
- Art. 203, Código Penal

### Dicas de prova
- Entenda o conceito de frustramento de direitos asssegurados pela lei trabalhista e nacionalização do trabalho
- Identifique as características dos crimes de infração de menor potencial ofensivo e ação múltipla ou conteúdo variado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.159", "page_number": 159, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 203, Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:18:34.153300+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=159", "doc_key": "8c3118506a1834d3c58c1d38adde6111"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ce77e360b10051d98f679ec843c96dd8ddad2f98ebea785bd85ef78223678442'),
  ('cpiuris2025::7914ac57ee26274ece9e468032e95c16', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Organização do Trabalho', '## Crimes contra a Organização do Trabalho

Resumo objetivo: Crimes contra a Organização do Trabalho incluem o exercício de atividade com infração de decisão administrativa e recrutar trabalhadores mediante fraude para fins de emigração. O primeiro crime é de mera conduta, enquanto o segundo é formal.

### Conceitos
- **Crime de mera conduta**: Não descreve resultado naturalístico
- **Exercício de atividade com infração de decisão administrativa**: Pena de detenção, de 3 meses a 2 anos, ou multa; crime habitual e próprio do sujeito impedido por decisão administrativa
- **Recrutar trabalhadores mediante fraude para fins de emigração**: Pena de detenção, de 1 a 3 anos, e multa; crime formal; tutela o interesse do Estado na permanência de trabalhadores brasileiros no território nacional

### Referências legais
- Art. 205 do CP
- Art. 282 do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre exercício de atividade com infração de decisão administrativa e recrutar trabalhadores mediante fraude para fins de emigração
- Entendimento do STF sobre o crime de exercício de atividade com infração de decisão administrativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.160", "page_number": 160, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 205 do CP", "Art. 282 do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:19:23.479047+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=160", "doc_key": "7914ac57ee26274ece9e468032e95c16"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '1a84e7939926b8f67564e78518748cce060fb60ad2099e23349d3bed615e98ce'),
  ('cpiuris2025::8192324335d4e0c6b80fcea21cf0ce85', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra a Organização do Trabalho', '## Crime contra a Organização do Trabalho

O crime de aliciamento de trabalhadores para outro local nacional é previsto no art. 207 do CP, com pena de detenção de 1 a 3 anos e multa. O objetivo da norma é evitar o despovoamento de uma região.

### Conceitos
- **Crime contra a Organização do Trabalho**: Infração cometida contra os direitos dos trabalhadores
- **Aliciamento de trabalhadores**: Levar trabalhadores de uma localidade para outra dentro do território nacional
- **Despovoamento de região**: Mudança populacional que pode causar inchaço populacional em outra região
- **Intuito da norma**: Evitar o despovoamento e o inchaço populacional
- **Infração formal**: Crime que não depende do sucesso do agente

### Referências legais
- Art. 207, CP

### Dicas de prova
- Entenda o conceito de crime contra a organização do trabalho e como se configura o aliciamento de trabalhadores
