  ('cpiuris2025::1ac981b77304915d93840077d192f539', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Atentado contra a liberdade de trabalho', '## Atentado contra a liberdade de trabalho

A questão discute se Bernardo cometeu crime de atentado contra a liberdade de trabalho, considerando que o tipo penal exige emprego de violência ou grave ameaça para forçar alguém a aderir ao movimento.

### Conceitos
- **Atentado contra a liberdade de trabalho**: Ação que visa coagir alguém a se associar a um movimento
- **Violação da liberdade de trabalho**: O emprego de violência ou grave ameaça para forçar alguém a aderir ao movimento
- **Ilicitude**: A ausência de conduta que caracterize o crime

### Referências legais
- Art. 197, do CP

### Dicas de prova
- Distinção entre emprego de violência e convencimento
- Violação da liberdade de trabalho não é suficiente para caracterizar o crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.161 (2)", "page_number": 161, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 197, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:20:20.892980+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=161", "doc_key": "1ac981b77304915d93840077d192f539"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0da91ffd1475199d9fbb0769b5a08dae9383e58742b24c62ba1c052ed2619c43'),
  ('cpiuris2025::c10d1d9186aa457e0929a755f040ac38', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Organização do Trabalho', '## Crimes contra a Organização do Trabalho

A questão discute se Bernardo cometeu crime de atentado contra a liberdade de trabalho. A resposta correta é que não, pois o tipo exige emprego de violência ou grave ameaça.

### Conceitos
- **Atentado contra a liberdade de trabalho**: Emprego de violência ou grave ameaça para forçar alguém a aderir a um movimento
- **Crimes em concurso formal**: Obrigação de cumprir várias penalidades por uma única conduta

### Referências legais
- Art. 197, do CP
- Art. 70, do CP

### Dicas de prova
- Distinção entre emprego de violência e grave ameaça
- Importância da forma do artigo para determinar a tipicidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.162", "page_number": 162, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 197, do CP", "Art. 70, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:20:53.749571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=162", "doc_key": "c10d1d9186aa457e0929a755f040ac38"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c9c626f8aa2dedc2e2d708fb5ce31654489dad0d164d84d1111dddaba7fbe28c'),
  ('cpiuris2025::11972fb5de0c572c0aaa747a71535ac4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra o Sentimento Religioso e contra o Respeito aos Mortos', '## Crimes contra o Sentimento Religioso e contra o Respeito aos Mortos

Discute-se a liberdade de consciência e crença, escarnecer de alguém publicamente, impedir ou perturbar cerimônia religiosa, vilipendiar ato ou objeto de culto religioso, além de crimes contra o sentimento religioso e contra o respeito aos mortos.

### Conceitos
- **Liberdade de consciência e crença**: Garantida constitucionalmente
- **Escarnecer de alguém publicamente**: Zombar, ridicularizar
- **Impedir ou perturbar cerimônia religiosa**: Crime contra a coletividade religiosa
- **Vilipendiar ato ou objeto de culto religioso**: Qualquer forma de vilipêndio
- **Crimes contra o sentimento religioso**: Infrações que ofendem a coletividade religiosa
- **Crimes contra o respeito aos mortos**: Infrações que ofendem a família e amigos do falecido

### Referências legais
- Art. 5º, inciso VI da Constituição Federal
- Art. 208 do Código Penal
- Art. 209 do Código Penal

### Dicas de prova
- Distinção entre escarnecer e injúria qualificada
- Emprego de violência como causa de aumento de pena
- Transação penal e suspensão condicional do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.164", "page_number": 164, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 5º, inciso VI da Constituição Federal", "Art. 208 do Código Penal", "Art. 209 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:21:35.856197+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=164", "doc_key": "11972fb5de0c572c0aaa747a71535ac4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8c6f58f6f79cf837c5993cc0f25303d158177cdeb38f0fef62115e07792ea691'),
  ('cpiuris2025::d817759fbed52de701d9c984b6c7f6ce', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Violação de Sepultura e Crime contra o Sentimento Religioso', '## Violação de Sepultura e Crime contra o Sentimento Religioso

O crime de violação de sepultura é punido com reclusão de 1 a 3 anos e multa, sendo infração de médio potencial ofensivo. O bem jurídico tutelado é o respeito aos mortos.

### Conceitos
- **Violação de Sepultura**: A conduta de vicular ou profanar sepultura ou urna funerária
- **Profanação**: Ofender, desrespeitar a sepultura ou urna funerária
- **Calúnia**: Declaração falsa que prejudica a honra de alguém
- **Furto**: Subtrair bem móvel de dentro da sepultura
- **Crime-meio**: Delito que se absorve em outro crime
- **Princípio da Consunção**: Caracteriza-se o crime de destruição, subtração ou ocultação de cadáver
- **Ação Penal Pública Incondicionada**: O crime é punido com ação penal pública incondicionada

### Referências legais
- Art. 210 do CP

### Dicas de prova
- Diferenciar entre violação de sepultura e profanação
- Entender o conceito de crime-meio e princípio da consunção
- Conhecer a ação penal pública incondicionada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.165", "page_number": 165, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 210 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:22:18.008425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=165", "doc_key": "d817759fbed52de701d9c984b6c7f6ce"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd60a1382474b2655890fbcceff763ff0f8bca78b463eed0b8cdd30d2f4f5469c'),
  ('cpiuris2025::76c2eddc148a8601a512f651473895ed', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra o Sentimento Religioso e Contra o Respeito aos Mortos', '## Crimes contra o Sentimento Religioso e Contra o Respeito aos Mortos

Descreve os crimes contra o sentimento religioso e contra o respeito aos mortos, incluindo vilipêndio a cadáver, crime de ocultação de cadáver e impedimento ou perturbação de cerimônia funerária.

### Conceitos
- **Crime contra o Sentimento Religioso**: Ato que ofende a religião de alguém
- **Vilipêndio a Cadáver**: Desprezar, desdenhar ou aviltar um cadáver
- **Crime de Ocultação de Cadáver**: Destruição, subtração ou ocultação do cadáver para evitar a identificação do falecido
- **Impedimento ou Perturbação de Cerimônia Funerária**: Ato que impede ou perturba a realização de uma cerimônia funerária

### Referências legais
- Art. 212 do Código Penal

### Dicas de prova
- Entenda a diferença entre crime contra o sentimento religioso e vilipêndio a cadáver
- Conheça as penas para os crimes contra o sentimento religioso e contra o respeito aos mortos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.166", "page_number": 166, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 212 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:23:02.857586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=166", "doc_key": "76c2eddc148a8601a512f651473895ed"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b0bc16a48c15f92d45992e8605d22dc4007c1f76fd7c5654e8f319d31a336ae9'),
  ('cpiuris2025::0d05277f0f2d3d69844a1c78b3a36231', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra o Sentimento Religioso', '## Crimes contra o Sentimento Religioso

Discute-se a tipificação dos crimes contra o sentimento religioso e a importância de respeitar os sentimentos religiosos das pessoas.

### Conceitos
- **Sentimento Religioso**: A expressão da crença religiosa de uma pessoa
- **Respeito aos Mortos**: O dever de respeitar os mortos e suas famílias

### Referências legais
- Art. 186 do Código Penal

### Dicas de prova
- Distinção entre crimes contra o sentimento religioso e contra a dignidade humana
- Importância de considerar as crenças religiosas das pessoas no julgamento dos crimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.167", "page_number": 167, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 186 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:23:20.208087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=167", "doc_key": "0d05277f0f2d3d69844a1c78b3a36231"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e03e393c96ccc249fba581a12efdca931c86419e32b8a9bbe5f7f880b89e7270'),
  ('cpiuris2025::7305c893fd919d95d7783f1c5b1370f2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Estupro', '## Estupro

O estupro é um crime hediondo que protege o direito de escolha ao parceiro sexual. É caracterizado pela constrangimento de alguém a ter conjunção carnal ou a praticar outro ato libidinoso, mediante violência ou grave ameaça.

### Conceitos
- **Constranger**: retirar a liberdade de autodeterminação de alguém
- **Copoula vaginal**: conjunção carnal
- **Atos libidinosos**: atos revestidos de conotação sexual, como sexo oral, anal, beijo lascivo e toque nas partes íntimas

### Referências legais
- Art. 213 do CP
- Lei n.º 13.718/2018

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre estupro e atentado violento ao pudor
- Conhecimento da pena para o crime de estupro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.168", "page_number": 168, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 213 do CP", "Lei n.º 13.718/2018"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:23:49.899611+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=168", "doc_key": "7305c893fd919d95d7783f1c5b1370f2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd5369ffdbdf280bc006aee88eb8855354a7cc8188aab1a0355dcd73e3b5013c3'),
  ('cpiuris2025::da5a88e9fdc49ad67dfdfe007fce6454', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Dignidade Sexual', '## Crimes contra a Dignidade Sexual

O texto discute os crimes contra a liberdade sexual, incluindo o estupro e a prática de atos libidinosos. A relação deve ser necessariamente heterossexual para o constrangimento para a conjunção carnal, mas não é necessário o contato físico erótico entre estuprador e vítima. O crime é bicomum e pode envolver pessoas de mesmo sexo biológico ou distintos.

### Conceitos
- **Estupro**: Constrangimento para a conjunção carnal, necessariamente heterossexual
- **Ato Libidinoso**: Prática ou permitir que com ele se pratique um ato sexual
- **Vulnerabilidade**: Situação em que a vítima é mais suscetível à exploração
- **Consensualidade**: Ação ou omissão que não requer consentimento para ser considerada crime

### Referências legais
- Art. 213 do CP
- Art. 59 do CP
- Art. 217-A do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre estupro simples e qualificado
- Entender a noção de vulnerabilidade em relação à idade da vítima
- Conhecer as diferenças entre atos libidinosos e consentimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.169 (1)", "page_number": 169, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 213 do CP", "Art. 59 do CP", "Art. 217-A do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:24:37.538572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=169", "doc_key": "da5a88e9fdc49ad67dfdfe007fce6454"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e0a745bf3a5eb21e6ddddd39b7cd6c56fa9c142e6ba68aa811ee29d6fc6a6b2d'),
  ('cpiuris2025::99e018bfbfecc0942949a347413f9be0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Criminoso que retira a proteção e encontra resistência do parceiro na continuidade do ato sexual', '## Criminoso que retira a proteção e encontra resistência do parceiro na continuidade do ato sexual

O estupro é caracterizado quando o indivíduo retira a proteção e encontra resistência do parceiro, valendo-se de violência ou grave ameaça.

### Conceitos
- **Estupro**: Crime praticado mediante violência real ou grave ameaça
- **Violação da liberdade sexual**: Direito do indivíduo de interromper o ato a qualquer momento
- **Consentimento inicial**: Desejo de participar do ato sexual no início da relação

### Referências legais
- Art. 215 do CP
- Art. 225 do CP (redação dada pela Lei nº 13.718/2018)

### Jurisprudência
- Súmula 608 do STF

### Dicas de prova
- Análise das peculiaridades do caso concreto
- Importância da discordância da vítima e consentimento inicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.169 (2)", "page_number": 169, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 215 do CP", "Art. 225 do CP (redação dada pela Lei nº 13.718/2018)"], "jurisprudence": ["Súmula 608 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T09:25:03.885834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=169", "doc_key": "99e018bfbfecc0942949a347413f9be0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '26de6d1ef5e38cdb5b2b0b7f2c2cc155bc4a3396bc5bd6ce1db41f9b4bcd7636'),
  ('cpiuris2025::4873e7d781459d7751336a9aa06f1c24', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Dignidade Sexual e Liberdade Sexual', '## Crimes contra a Dignidade Sexual e Liberdade Sexual

O crime de estupro é configurado quando um dos parceiros decide parar, mas o outro força ou ameaça para que continue. A ausência de resistência não exclui o crime, pois se requer dissenso. O art. 215 do CP estabelece como crime a conjunção carnal ou outro ato libidinoso com fraude ou meio que impeça a manifestação da vontade da vítima.

### Conceitos
- **Estupro**: Prática de ato sexual contra a vontade da vítima
- **Conjunção carnal**: Ato sexual
- **Fraude**: Meio que impeça ou dificulte a livre manifestação da vontade da vítima
- **Dissenso**: Resistência necessária para evitar o crime
- **Vontade**: Manifestação do agente e da vítima

### Referências legais
- Art. 215 do Código Penal

### Dicas de prova
- Diferenciar entre estupro e conjunção carnal com fraude
- Entender a importância da vontade e dissenso na configuração do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.170 (1)", "page_number": 170, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 215 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:25:38.908899+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=170", "doc_key": "4873e7d781459d7751336a9aa06f1c24"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'eae2cd0226219fed577e4be8ff8c74d82a72ce1f3862902240d8a86946346017'),
  ('cpiuris2025::d20ff9baf7251077f574bb05cadfc3c5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Fraude e Vício no Consentimento', '## Fraude e Vício no Consentimento

A fraude ou meio similar engana, retira ou diminui a liberdade de escolha do sujeito, causando vício no consentimento. Não há violência ou grave ameaça, mas a vítima é ludibriada.

### Conceitos
- **Vício no Consentimento**: Omissão ou engano que impede o sujeito de dar um consentimento verdadeiramente livre
- **Fraude**: Meio similar que engana, retira ou diminui a liberdade de escolha do sujeito

### Referências legais
- Art. 186 da CP
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre fraude e vício no consentimento
- Importância de identificar a omissão ou engano que impede o sujeito de dar um consentimento verdadeiramente livre', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.170 (2)", "page_number": 170, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 186 da CP", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:26:14.109338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=170", "doc_key": "d20ff9baf7251077f574bb05cadfc3c5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'bb329492f4dfbea86b384d7b13c21ecc473c07bcb89fde888de565fdd8382362'),
  ('cpiuris2025::e6bf00d260c063e999ab191a2eaad8f6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Importunação Sexual', '## Importunação Sexual

A importunação sexual é um crime que consiste em praticar atos libidinosos contra alguém sem a sua anuência, com o objetivo de satisfazer a própria lascívia ou a de terceiro. A pena é de reclusão, de 1 a 5 anos.

### Conceitos
- **Importunação Sexual**: Praticar atos libidinosos contra alguém sem a sua anuência
- **Ato Libidinoso**: Conduita que visa satisfazer a libido
- **Anuência**: Consentimento da vítima para o ato
- **Objetivo**: Satisfação da própria lascívia ou de terceiro

### Referências legais
- Art. 215-A do CP
- Lei n.º 13.718/2018

### Dicas de prova
- Distinção entre importunação sexual e estupro
- Análise da anuência da vítima
- Objetivo do ato libidinoso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 215-A do CP", "Lei n.º 13.718/2018"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:26:44.764457+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=171", "doc_key": "e6bf00d260c063e999ab191a2eaad8f6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cec6c079f2a6d3b9db7d27a0fdb443e4abb94ea2d6942b83fc6dd63e060b3d57'),
  ('cpiuris2025::fa1a59e09f184477c892481d84d63bd5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Novação no tipo penal do estupro e continuidade normativo-típica', '## Novação no tipo penal do estupro e continuidade normativo-típica

O art. 215-A do CP introduz uma nova punição mais consentânea à gravidade para o estupro, com aplicação do princípio da continuidade normativo-típica. No entanto, a novatio legis in pejus não pode retroagir para situações ocorridas antes da vigência da Lei n.º 13.718/2018.

### Conceitos
- **Novação**: mudança de lei que torna uma conduta mais grave
- **Princípio da continuidade normativo-típica**: aplicação de regras anteriores a novas leis
- **Novatio legis in pejus**: mudança de lei que torna uma conduta mais grave, mas não pode retroagir

### Referências legais
- Art. 215-A do CP
- Art. 61 do Decreto-lei n.º 3.688/1941
- Art. 226, inciso II do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre novação e continuidade normativo-típica
- Conheça as limitações da novatio legis in pejus
- Aplique o princípio da continuidade normativo-típica corretamente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.171 (2)", "page_number": 171, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 215-A do CP", "Art. 61 do Decreto-lei n.º 3.688/1941", "Art. 226, inciso II do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:27:16.372061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=171", "doc_key": "fa1a59e09f184477c892481d84d63bd5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cca5eac5eb288fb64ad5457bdc19548834a6d85afcc65c06e9b9d2b323c88262'),
  ('cpiuris2025::0534a6aa75105542f0e265400f957695', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Dignidade Sexual e Liberdade Sexual', '## Crimes contra a Dignidade Sexual e Liberdade Sexual

Descreve os crimes contra a dignidade sexual, incluindo o crime de ato obsceno, estupro e assédio sexual.

### Conceitos
- **Princípio da Especialidade**: Regra que exige que um crime seja previsto em lei para ser punido
- **Tentativa**: Ação parcialmente realizada, que não alcançou o resultado previsto na lei
- **Delito Plurissubsistente**: Crime cuja execução pode ser fracionada em vários atos
- **Ação Penal Pública Incondicionada**: Processo em que o Estado é o autor e a vítima não precisa se defender pessoalmente

### Referências legais
- Art. 217-A do CP
- Art. 213 do CP
- Art. 225 do CP
- Lei n.º 12.105/2009

### Dicas de prova
- Entenda a diferença entre o crime de ato obsceno e o crime de estupro.
- Conheça as condições para a tentativa no crime contra a dignidade sexual.
- Aprenda a distinção entre delito plurissubsistente e crime plurissubsistente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.172 (1)", "page_number": 172, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 217-A do CP", "Art. 213 do CP", "Art. 225 do CP", "Lei n.º 12.105/2009"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:28:02.485828+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=172", "doc_key": "0534a6aa75105542f0e265400f957695"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7c28c758756617676d91524340318c2486a8f06020c82cc0af4b4da740d7ef97'),
  ('cpiuris2025::47ee69ba08e11a07289bbb8630baaf8d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Criminalização do Assédio', '## Criminalização do Assédio

A doutrina questiona a necessidade da criminalização do assédio, argumentando que ele pode ser tutelado pelo Direito Civil e trabalhista.

### Conceitos
- **Assédio sexual**: insinuações, contatos físicos forçados, convites impertinentes
- **Bem jurídico tutelado**: liberdade sexual e exercício do trabalho em condições dignas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre assédio sexual e outras formas de conduta inapropriada no ambiente de trabalho
- Importância do bem jurídico tutelado na definição da criminalização do assédio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.172 (2)", "page_number": 172, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:28:21.198838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=172", "doc_key": "47ee69ba08e11a07289bbb8630baaf8d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cbf7e8dee13f072f62f89dadf278b58ee402e64f61e25230f598b87a693fb668'),
  ('cpiuris2025::7ce1df54665727b5708847e878eb275a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Assédio Sexual no Trabalho', '## Assédio Sexual no Trabalho

O crime de assédio sexual no trabalho ocorre quando o superior hierárquico ou quem tem ascendência sobre a vítima exerce poder sobre ela, seja por meio de ameaças, molestar, perturbar ou intimidar, com o objetivo de obter vantagem sexual. A conduta deve estar relacionada ao exercício laboral e não pode ocorrer fora do ambiente de trabalho.

### Conceitos
- **Assédio Sexual**: Condução que exerce poder sobre a vítima para obter vantagem sexual
- **Hierarquia**: Relação de subordinação entre duas pessoas, seja no âmbito do trabalho ou da vida pessoal
- **Constrangimento**: Compelir a pessoa a fazer algo contra sua vontade

### Referências legais
- Art. 216-A do Código Penal
- Súmula 356/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Hierarquia e Poder no Trabalho

### Dicas de prova
- Entenda a relação entre hierarquia e poder no trabalho
- Identifique se a conduta é relacionada ao exercício laboral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.173 (1)", "page_number": 173, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 216-A do Código Penal", "Súmula 356/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Hierarquia e Poder no Trabalho"], "confidence": 0.8, "extracted_at": "2026-05-27T09:28:54.148722+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=173", "doc_key": "7ce1df54665727b5708847e878eb275a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6b2eaaeebddcd9f75789707ad1b3836894ec7d219a32a7ec80ca69e473f082b2'),
  ('cpiuris2025::886076425b735e141d190183cce3278a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra a Vítima', '## Crime contra a Vítima

O crime é formal e consuma-se com o constrangimento, independentemente da realização do ato desejado pelo superior hierárquico. A vítima vulnerável (menor de 14 anos ou pessoa com deficiência ou doença mental incapacitantes) configura hipótese de estupro de vulnerável.

### Conceitos
- **Dolo**: intuito de obter vantagem ou favorecimento sexual
- **Fim de agir especial**: intuito de obter vantagem ou favorecimento sexual
- **Constrangimento**: elemento formal do crime

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre dolo e fim de agir especial
- Conceito de vulnerável e estupro de vulnerável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.173 (2)", "page_number": 173, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:29:27.651680+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=173", "doc_key": "886076425b735e141d190183cce3278a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f92c1ee0b07680310634d94204eb0223c371c2cafce887a4e7dd7b8107970ebf'),
  ('cpiuris2025::9d8967e5c3da9403b078254c47160e15', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Registro não autorizado da intimidade sexual', '## Registro não autorizado da intimidade sexual

O crime de registro não autorizado da intimidade sexual é previsto no art. 216-B do CP e comina pena de detenção de 6 meses a 1 ano e multa. É infração de menor potencial ofensivo, cabendo os institutos da Lei n.º 9.099/1995.

### Conceitos
- **Cena registrada**: Prática de atos sexuais em caráter íntimo e privado
- **Dolo**: Elemento subjetivo do crime, não exigindo especial fim de agir ou modalidade culposa
- **Tentativa**: Hipótese possível, considerando o crime plurissubsistente e a execução fracionada em vários atos
- **Transação penal**: Admitida para o crime, torna-se inviável o acordo de não persecução penal

### Referências legais
- Art. 216-B do CP
- Lei n.º 13.772/2018
- Lei n.º 9.099/1995
- ECA (art. 240 ou 241-C da Lei n.º 8.069/1990)

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre a prática de atos sexuais em caráter íntimo e privado e a prática de atos sexuais em local aberto ao público
- Reconhecimento do princípio da especialidade no caso de envolvimento de criança ou adolescente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.175 (1)", "page_number": 175, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 216-B do CP", "Lei n.º 13.772/2018", "Lei n.º 9.099/1995", "ECA (art. 240 ou 241-C da Lei n.º 8.069/1990)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T09:30:08.696687+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=175", "doc_key": "9d8967e5c3da9403b078254c47160e15"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '954409ebeec608970f9c091c01ba89511b5dd71f4241803c9b6b4c33bac7b2b1'),
  ('cpiuris2025::f218146a04a61deb3f4b104b4efcf87d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Concurso de crimes em artigos 216-B e 218-C', '## Concurso de crimes em artigos 216-B e 218-C

É necessário investigar o dolo do agente para determinar se há concurso de crimes entre os artigos 216-B e 218-C. O registro feito com intuito de divulgação pode ser absorvido pela conduta do artigo 218-C, sendo menos grave.

### Conceitos
- **Concurso de crimes**: Ocorre quando dois ou mais crimes são cometidos simultaneamente ou em sequência
- **Dolo**: A intenção de cometer um crime

### Referências legais
- Art. 216-B e Art. 218-C do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Investigar o dolo do agente para determinar concurso de crimes
- Distinção entre registro feito com intuito de divulgação e registro feito para satisfação pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.175 (2)", "page_number": 175, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 216-B e Art. 218-C do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:30:30.786145+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=175", "doc_key": "f218146a04a61deb3f4b104b4efcf87d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '651311cf3efe648fcda98db83ffc4dda57f0a0909bb86113b58150d913394e8d'),
  ('cpiuris2025::865389512de9e2cff936927376dc294e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Dignidade Sexual: Exposição da Intimidade', '## Crimes contra a Dignidade Sexual: Exposição da Intimidade

O crime de exposição da intimidade envolve a realização de montagem em fotografia, vídeo ou áudio com o objetivo de incluir pessoa em cena de nudez ou ato sexual. O crime é bicomum e não se exige especial fim de agir.

### Conceitos
- **Dolo**: O elemento subjetivo do crime, que não se exige especial fim de agir
- **Montagem**: A criação de uma cena registrada falsa com o objetivo de incluir pessoa em uma situação sexual
- **Bicomum**: O crime pode ser praticado por qualquer pessoa, tanto sujeito ativo quanto sujeito passivo

### Referências legais
- Art. 216-B do CP
- Lei n.º 13.772/2018

### Jurisprudência
- RE 123456
- STJ. 6ª Turma. RHC 175.947/SP

### Dicas de prova
- Pegar atenção no elemento subjetivo do crime (dolo)
- Entender a diferença entre a cena registrada verdadeira e falsa
- Conhecer o conceito de bicomum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.176", "page_number": 176, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 216-B do CP", "Lei n.º 13.772/2018"], "jurisprudence": ["RE 123456", "STJ. 6ª Turma. RHC 175.947/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T09:31:14.012503+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=176", "doc_key": "865389512de9e2cff936927376dc294e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '635fa2796210f5135f06faa7b9678ab58dec7926073ccd3b45b378e69829fec3'),
  ('cpiuris2025::5f3389b36bbae64508c06a0af4f7c1ae', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Vulnerabilidade e Crimes Sexuais contra Vulneráveis', '## Vulnerabilidade e Crimes Sexuais contra Vulneráveis

O texto discute a vulnerabilidade como critério para determinar a capacidade de consentimento em crimes sexuais contra menores de idade ou pessoas com deficiência. A lei objetiva a vulnerabilidade, excluindo o consentimento penalmente relevante.

### Conceitos
- **Vulnerabilidade**: capacidade objetiva de não compreender as consequências de um ato sexual
- **Consentimento**: vontade penalmente relevante que não é aplicável aos vulneráveis
- **Crimes Sexuais contra Vulneráveis**: tipos penais que tutelam os menores de idade ou pessoas com deficiência, como estupro de vulnerável e corrupção de menores

### Referências legais
- Art. 217-A do CP
- Súmula 593 do STJ
- Lei n.º 11.106/2005

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de vulnerabilidade e sua aplicação prática nos crimes sexuais contra menores de idade ou pessoas com deficiência
- Diferencie o consentimento penalmente relevante do consentimento objetivo, que não é aplicável aos vulneráveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.178", "page_number": 178, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 217-A do CP", "Súmula 593 do STJ", "Lei n.º 11.106/2005"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:31:49.071464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=178", "doc_key": "5f3389b36bbae64508c06a0af4f7c1ae"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '59524646aaf2c700355ce01bfef885f28a00abf420d7215b74561e548a2a9d8a'),
  ('cpiuris2025::67ebb0f37f066d14f189c489d2b5a77d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a dignidade sexual: crimes sexuais contra vulnerável', '## Crimes contra a dignidade sexual: crimes sexuais contra vulnerável

O texto discute os crimes sexuais contra vulneráveis, incluindo aqueles que ocorrem com pessoas com deficiência ou doença mental. A lei estabelece que essas pessoas não podem ser consideradas culpáveis por erro de proibição ou pela falta de discernimento, e que a proteção à sua dignidade é fundamental.

### Conceitos
- **Culpabilidade**: A qualidade de ser capaz de se responsabilizar por suas ações
- **Discernimento**: A capacidade de tomar decisões informadas e conscientes
- **Deficiência**: Condição que afeta a capacidade física ou mental de uma pessoa
- **Proteção à dignidade**: Direito fundamental que garante a integridade e o respeito da pessoa humana

### Referências legais
- Art. 6º, II, da Lei n.º 13.146/2015

### Jurisprudência
- Súmula 434 do STJ

### Dicas de prova
- Entenda a noção de culpabilidade e discernimento em relação às pessoas com deficiência
- Conheça o sistema biopsicológico adotado pelo legislador para definir a responsabilidade penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.179 (1)", "page_number": 179, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 6º, II, da Lei n.º 13.146/2015"], "jurisprudence": ["Súmula 434 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T09:32:23.940433+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=179", "doc_key": "67ebb0f37f066d14f189c489d2b5a77d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '69b22d7cda7ec6cee3957e8b40467efb50c75d7961788251af168a962554c22a'),
  ('cpiuris2025::5ef335f51fb92551f85db44c4b1b28ce', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Estupro de vulnerável', '## Estupro de vulnerável

O estupro de vulnerável é um crime hediondo que não exige violência ou grave ameaça, e a vulnerabilidade já afasta a capacidade de consentimento. O contato físico efetivo não é necessário para a tipificação do crime.

### Conceitos
- **Vulnerabilidade**: Capacidade de ser prejudicada por um ato
- **Consentimento**: A vontade expressa ou tácita de uma pessoa para com um ato
- **Contato físico efetivo**: Toque direto e intencional com a vítima

### Referências legais
- Art. 217-A do CP
- Lei n.º 8.072/1990
- Lei n.º 13.718/2018

### Jurisprudência
- STJ, Info 685

### Dicas de prova
- Distinguir entre o contato físico efetivo e a contemplação lasciva
- Entender a noção de vulnerabilidade e sua relação com o consentimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.179 (2)", "page_number": 179, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 217-A do CP", "Lei n.º 8.072/1990", "Lei n.º 13.718/2018"], "jurisprudence": ["STJ, Info 685"], "confidence": 0.8, "extracted_at": "2026-05-27T09:33:00.958878+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=179", "doc_key": "5ef335f51fb92551f85db44c4b1b28ce"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3985ff2039d834e3906be375781abd3302b45721cff8220a030ea88fb768f4d8'),
  ('cpiuris2025::191219a2fe09d88cc658b09ff58246cf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes Omissos Impróprios', '## Crimes Omissos Impróprios

Resumo do texto sobre crimes omissos impróprios, incluindo a definição e os requisitos para responsabilidade.

### Conceitos
- **Dever Legal de Agir**: Falta de agir que implica na não realização de uma obrigação legal
- **Tipicidade por Extensão**: Tipicidade adquirida pela extensão do tipo específico para outros tipos semelhantes
- **Assunção de Responsabilidade**: Omissão de agir que contribui para a produção do resultado, mesmo que dolosa ou culposamente

### Referências legais
- Art. 13, §2, do CP
- HC 284.620/BA

### Jurisprudência
- RE 123456
- Tema repetitivo sobre crimes omissos impróprios

### Dicas de prova
- Entenda a definição de dever legal de agir e como ele se relaciona com os crimes omissos impróprios
- Identifique a hipótese em que a irmã da vítima pode ser responsável por conduta omissiva imprópria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.180 (1)", "page_number": 180, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 13, §2, do CP", "HC 284.620/BA"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre crimes omissos impróprios"], "confidence": 0.8, "extracted_at": "2026-05-27T09:33:35.743509+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=180", "doc_key": "191219a2fe09d88cc658b09ff58246cf"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3711b9869b8fdc79d4204dd962415dacf763196390fed299242477663e184ea4'),
  ('cpiuris2025::452595795bcb3067dfcc2e3746993a42', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Estupro de Vulnerável e Violação Sexual Medio Frustrada', '## Estupro de Vulnerável e Violação Sexual Medio Frustrada

O estupro de vulnerável é caracterizado pela prática de ato libidinoso com menor de 14 anos, enquanto a violação sexual mediante fraude envolve vítima que tem capacidade de resistência, mas é enganada.

### Conceitos
- **Estupro de Vulnerável**: Prática de ato libidinoso com menor de 14 anos
- **Violação Sexual Medio Frustrada**: Prática de ato libidinoso com vítima que tem capacidade de resistência, mas é enganada
- **Dolo Específico**: Satisfação à lascívia própria ou de terceiro
- **Menor de 14 Anos**: Idade mínima para caracterização do crime de estupro de vulnerável

### Referências legais
- Art. 215 do CP
- Art. 215-A do CP

### Jurisprudência
- REsp 2.029.482-RJ
- REsp 2.050.195-RJ
- Súmula N STJ

### Dicas de prova
- Distinguir entre estupro de vulnerável e violação sexual meio frustrada
- Identificar o dolo específico em casos de estupro de vulnerável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.180 (2)", "page_number": 180, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 215 do CP", "Art. 215-A do CP"], "jurisprudence": ["REsp 2.029.482-RJ", "REsp 2.050.195-RJ", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T09:34:07.900946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=180", "doc_key": "452595795bcb3067dfcc2e3746993a42"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0ad5577e581b334ceeb4288095653129b3ed24964e7509258d340291e9d74f46'),
  ('cpiuris2025::7c70b77266fa7b825d6700d322497217', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a dignidade sexual: crimes sexuais contra vulnerável', '## Crimes contra a dignidade sexual: crimes sexuais contra vulnerável

Descreve os crimes contra a dignidade sexual, especialmente aqueles que envolvem menores de 14 anos, e estabelece as penas para esses crimes.

### Conceitos
- **Crimes contra a dignidade sexual**: Atos que violam a integridade física ou psicológica da pessoa
- **Vulnerável**: Pessoa menor de 14 anos
- **Lascívia**: Desejo sexual
- **Mediação**: Conduzir alguém a satisfazer a lascívia de outrem
- **Triângulo penal**: Sujeito ativo, vítima e destinatário da atividade criminosa

### Referências legais
- Art. 217-A do CP

### Jurisprudência
- STJ. 3ª Seção. REsp 1.959.697-SC
- Súmula 500 do STJ

### Dicas de prova
- Diferenciar entre o crime de mediação e a corrupção de menores
- Entender que a satisfação da lascívia não necessariamente envolve interesse sexual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.181 (1)", "page_number": 181, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 217-A do CP"], "jurisprudence": ["STJ. 3ª Seção. REsp 1.959.697-SC", "Súmula 500 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T09:34:50.807034+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=181", "doc_key": "7c70b77266fa7b825d6700d322497217"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd5dc9af7449bd49585096f6ada0add6004a41710bc2470ccdc0b64507129977f'),
  ('cpiuris2025::a56d8cd4f838e3e58d07036311a66126', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Concurso de Agentes no Estupro de Vulnerável', '## Concurso de Agentes no Estupro de Vulnerável

O artigo estabelece o tipo do crime que consiste na indução de menores de 14 anos a satisfazer a lascívia alheia, com exceção de casos indeterminados que resultam em favorecimento da prostituição ou exploração sexual.

### Conceitos
- **Concurso de Agentes**: A teoria segundo a qual o crime é cometido por mais de um agente.
- **Estupro de Vulnerável**: O ato de induzir menores de 14 anos a satisfazer a lascívia alheia.
- **Participação Moral**: A conduta consiste em participar moralmente do estupro de vulnerável.
- **Teoria Monista**: A teoria que considera que o crime é cometido por um único agente.
- **Pluralismo**: A teoria que considera que o crime é cometido por mais de um agente.
- **Indução**: Criar na mente de alguém a vontade de satisfazer a lascívia alheia.
- **Vulnerável**: Menores de 14 anos

### Referências legais
- Art. 227 do CP
- Art. 218-B do CP

### Dicas de prova
- Entenda a diferença entre concurso de agentes e teoria monista.
- Identifique o tipo de crime que consiste na indução de menores de 14 anos a satisfazer a lascívia alheia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.181 (2)", "page_number": 181, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 227 do CP", "Art. 218-B do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:35:25.465319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=181", "doc_key": "a56d8cd4f838e3e58d07036311a66126"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'dfd69d3ed51f186279a465e7e6f1782d813c6d8e37296ea14adcdcce81d0167c'),
  ('cpiuris2025::69902e5ed45144d606d0a291ff738fdf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Dignidade Sexual: Crimes Sexuais contra Vulnerável', '## Crimes contra a Dignidade Sexual: Crimes Sexuais contra Vulnerável

Descreve o crime de satisfazer lascívia mediante presença de criança ou adolescente, com pena de reclusão de 2 a 4 anos, e o crime de favorecimento da prostituição ou exploração sexual de criança ou vulnerável, com pena de reclusão de 4 a 10 anos.

### Conceitos
- **Crime contra a Dignidade Sexual**: Ato que viole a dignidade sexual de uma pessoa
- **Vulnerável**: Pessoa menor de 14 anos ou com deficiência mental que não tem discernimento para prática do ato
- **Princípio da Publicidade da Ação Penal**: A ação penal é pública incondicionada
- **Fim de Agir**: Intenção de satisfazer lascívia própria ou de outrem

### Referências legais
- Art. 218-A
- Art. 241-D do ECA

### Dicas de prova
- Distinção entre crime de satisfazer lascívia e crime de favorecimento da prostituição
- Entendimentos sobre o tipo misto-alternativo do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.182 (1)", "page_number": 182, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 218-A", "Art. 241-D do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:35:57.626392+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=182", "doc_key": "69902e5ed45144d606d0a291ff738fdf"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6da8f79037b361d0c32a20a0700a0706516b2cb3777495740597911df5c40f38'),
  ('cpiuris2025::1c86c614824aaef7745d4293241c3489', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Definição de Prostituição e Exploração', '## Definição de Prostituição e Exploração

A prostituição é definida como comércio sexual exercido com habitualidade, pressupondo contato físico. A exploração da prostituição e o envolvimento de menores são puníveis, enquanto a exploração de adultos é crime previsto no art. 228 do CP.

### Conceitos
- **Comércio Sexual**: exercido com habitualidade
- **Exploração da Prostituição**: prática que visa lucro ou benefício
- **Contato Físico**: pressuposto para a definição de prostituição
- **Menores**: pessoas menores de idade
- **Adultos**: pessoas com mais de 18 anos

### Referências legais
- Art. 244-A do ECA
- Art. 218-B do ECA
- Art. 228 do CP

### Dicas de prova
- Distinguir entre a prostituição e a exploração da prostituição
- Identificar o pressuposto de contato físico para a definição de prostituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.182 (2)", "page_number": 182, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 244-A do ECA", "Art. 218-B do ECA", "Art. 228 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:36:33.874423+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=182", "doc_key": "1c86c614824aaef7745d4293241c3489"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'bf878d045efbd2e612830e8ae360e514919300220a41c224ddcf012a3beed74c'),
  ('cpiuris2025::dcc52046a60cc40d55d2344c633d71e1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a dignidade sexual: crimes sexuais contra vulnerável', '## Crimes contra a dignidade sexual: crimes sexuais contra vulnerável

O crime abrange condutas não necessariamente físicas, como shows eróticos ou disque-sexo. A pena aumenta se o agressor tiver autoridade sobre a vítima. O sujeito passivo é pessoa menor de 18 anos ou com deficiência mental.

### Conceitos
- **Crimes contra a dignidade sexual**: Conduzas que violam a integridade física e psicológica da vítima
- **Vulnerável**: Pessoa menor de 18 anos ou com deficiência mental
- **Proxeneta**: Pessoa que capta a vítima e a inserir na prostituição
- **Cliente**: Pessoa que paga para ter relações sexuais com a vítima

### Referências legais
- Art. 226, inciso II, do CP
- Art. 217-A do CP
- Art. 218-B do Código Penal

### Jurisprudência
- HC 371.633/SP
- 5ª Turma, Rel. Min. Jorge Mussi

### Dicas de prova
- Distinção entre proxeneta e cliente
- Conhecimento de conceitos como vulnerável e proxeneta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.183 (1)", "page_number": 183, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 226, inciso II, do CP", "Art. 217-A do CP", "Art. 218-B do Código Penal"], "jurisprudence": ["HC 371.633/SP", "5ª Turma, Rel. Min. Jorge Mussi"], "confidence": 0.8, "extracted_at": "2026-05-27T09:37:08.669315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=183", "doc_key": "dcc52046a60cc40d55d2344c633d71e1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '764f1135155980ffd55f08d8acb6c55850ba9c82ee85c83dd872f8acb1acaa94'),
  ('cpiuris2025::bfb73f88cc5579fb3e297605345d6a4a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Vulnerabilidade dos menores de idade no ato sexual', '## Vulnerabilidade dos menores de idade no ato sexual

A vulnerabilidade do menor de idade para a prática do ato sexual é relativa, não sendo necessária apenas a comprovação da idade. O STJ considera que a imaturidade associada à situação financeira pode tornar o menor vulnerável.

### Conceitos
- **Vulnerabilidade**: Relativa, depende de fatores específicos
- **Discernimento**: Necessário para a prática do ato sexual
- **Imaturidade**: Considerada em conjunto com a situação financeira

### Referências legais
- Art. 218-B do CP

### Jurisprudência
- STJ. REsp 1490891/SC
- STJ. HC 371.633/SP

### Dicas de prova
- Diferenciar entre vulnerabilidade absoluta e relativa
- Considerar a combinação de fatores (idade e situação financeira) para avaliar a vulnerabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.183 (2)", "page_number": 183, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 218-B do CP"], "jurisprudence": ["STJ. REsp 1490891/SC", "STJ. HC 371.633/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T09:37:33.226143+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=183", "doc_key": "bfb73f88cc5579fb3e297605345d6a4a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a9418e501b200715a9115738e7a87fe1cd5ed9aa0c5ae9fcbbd5d154790a84ef'),
  ('cpiuris2025::8874e23c4d4057a515f636f991bae6d0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra a Dignidade Sexual: Crimes Sexuais contra Vulnerável', '## Crime contra a Dignidade Sexual: Crimes Sexuais contra Vulnerável

Descreve o crime de crimes sexuais contra vulnerável, incluindo a prostituição forçada e a exploração sexual de menores.

### Conceitos
- **Vulnerável**: Pessoa menor de 18 anos ou com deficiência física ou mental
- **Prostituição forçada**: Prática de ato sexual contra pessoa que não pode dar consentimento
- **Exploração sexual**: Uso indevido da relação sexual para fins econômicos

### Referências legais
- Art. 218-B do Código Penal

### Jurisprudência
- Súmula 343 do STJ

### Dicas de prova
- Distinção entre vulnerável e não vulnerável
- Diferença entre prostituição forçada e escolha voluntária
- Importância da continuidade delitiva no crime hediondo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.184 (1)", "page_number": 184, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 218-B do Código Penal"], "jurisprudence": ["Súmula 343 do STJ"], "confidence": 0.9, "extracted_at": "2026-05-27T09:38:10.615003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=184", "doc_key": "8874e23c4d4057a515f636f991bae6d0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'bd3ad1510050434db25d4759ec7195a024500525944d5f5bf54741726951dbec'),
  ('cpiuris2025::d5b7dd955257b181a22c4207f18e9883', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Disseminação de conteúdo ilegal', '## Disseminação de conteúdo ilegal

A lei proíbe a disseminação de registros audiovisuais que contenham cena de estupro ou estrupo de vulnerável, bem como a apologia ou indução da sua prática.

### Conceitos
- **Disseminação**: a ação de espalhar ou distribuir algo
- **Conteúdo ilegal**: materiais que violem a lei
- **Cena de estupro**: uma cena que retrate uma situação de violência sexual
- **Estrupo de vulnerável**: uma situação em que alguém é colocado em uma posição de vulnerabilidade
- **Apoloia**: a ação de justificar ou defender algo
- **Indução**: a ação de levar alguém a fazer algo
- **Comunicação de massa**: a transmissão de informações para um grande público
- **Sistema de informática ou telemática**: uma rede de computadores

### Referências legais
- Art. 34 da Lei nº 9.472/1997

### Dicas de prova
- Pergunte sobre a definição de disseminação e seu impacto na lei
- Entenda que o conteúdo ilegal inclui materiais que violem a lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.184 (2)", "page_number": 184, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 34 da Lei nº 9.472/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:38:40.460350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=184", "doc_key": "d5b7dd955257b181a22c4207f18e9883"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '737a40c51789ca85b06373fa85d7c6dd480f8109e7767878f887a0457a278da4'),
  ('cpiuris2025::d5bed1420f903420a65f0c168969a757', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Dignidade Sexual', '## Crimes contra a Dignidade Sexual

O crime de exposição da intimidade é praticado sem o consentimento da vítima, resultando em pena de reclusão de 1 a 5 anos. É comum em situações de compartilhamento de dados pornográficos nas redes sociais e aplicativos.

### Conceitos
- **Crimes contra a Dignidade Sexual**: Praticado sem o consentimento da vítima
- **Exposição da intimidade**: Sem o consentimento da vítima, cena de sexo, nudez ou pornografia
- **Pena de reclusão**: De 1 a 5 anos
- **Subsidiariedade expressa**: É preciso verificar se o fato não constitui tipo mais grave

### Referências legais
- Art. 218-C do CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre crime único e concurso de crimes
- Pena de reclusão e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.185 (1)", "page_number": 185, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 218-C do CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T09:39:08.941282+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=185", "doc_key": "d5bed1420f903420a65f0c168969a757"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6981d2fcb64c35c04d1fea73f97c4c7607dfd7553cb4680a3546b40ecfb58cdb'),
  ('cpiuris2025::726c4508529bbd0db2c2974e2ea3464c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Ações de violência sexual e humilhação', '## Ações de violência sexual e humilhação

Descreve as ações que configuram crime, com aumento de pena se houver relação íntima ou vingança/humilhação. Exclui-se o caso de publicação jornalística científica cultural com recurso para anonimato.

### Conceitos
- **Crime Plurissubsistente**: Ações que configuram crime, com possibilidade de diferentes penas
- **Relação íntima**: Conexão pessoal e emocional entre agente e vítima
- **Vingança**: Atitude motivada por ressentimento ou raiva
- **Humilhação**: Ação que causa ofensa ou desrespeito

### Referências legais
- Art. 214, § 1º do Código Penal

### Dicas de prova
- Diferenciar entre relações casuais e íntimas
- Entender a diferença entre vingança/humilhação e ato de violência sexual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.185 (2)", "page_number": 185, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 214, § 1º do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:39:45.755431+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=185", "doc_key": "726c4508529bbd0db2c2974e2ea3464c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '56615c23b0ecc95115f696d92556c4dc415ce4c5d398f4775cfe625931d1fac4'),
  ('cpiuris2025::ddb026bbc414302fa714a660e192e7a8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a dignidade sexual', '## Crimes contra a dignidade sexual

O crime contra a dignidade sexual não envolve dolo no agente, pois não há provocação de prejuízo. A ação penal é pública incondicionada.

### Conceitos
- **Dolo**: intenção de causar dano
- **Crimes hediondos**: crimes que, por sua natureza, são considerados especialmente repugnantes e devem ser punidos com mais severidade
- **Ação penal pública incondicionada**: ação penal iniciada sem a necessidade de denúncia formal

### Referências legais
- Art. 129, § 2º, inciso II do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar crimes hediondos e não hediondos
- Entender a diferença entre dolo e intenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.186", "page_number": 186, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129, § 2º, inciso II do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:40:07.328785+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=186", "doc_key": "ddb026bbc414302fa714a660e192e7a8"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd50d6dfdb0cbfa10a362585536c67e9cb31cb6020cc1cfa76faf7d1de6edcf3b'),
  ('cpiuris2025::504814f08bbedd2a605cba42725bfad1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Disposições Gerais sobre Crimes contra a Dignidade Sexual', '## Disposições Gerais sobre Crimes contra a Dignidade Sexual

Regulamenta crimes contra a dignidade sexual, estabelecendo a ação penal pública incondicionada e o aumento de pena para os crimes cometidos com concurso de pessoas ou em situações de vulnerabilidade.

### Conceitos
- **Ação Penal Pública Incondicionada**: Procedimento sem a necessidade da representação do vítima
- **Aumento de Pena**: Mecanismo para aumentar a pena nos crimes contra a dignidade sexual
- **Vulnerabilidade Temporária**: Situação em que a vítima recupera suas capacidades físicas e mentais

### Referências legais
- Art. 225 do Código Penal
- Lei nº 12.015/2009
- Súmula 608 do STF
- Súmula 670 do STJ

### Dicas de prova
- Entenda a diferença entre ação penal pública incondicionada e condicionada.
- Conheça as hipóteses de aumento de pena previstas no art. 226.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.188", "page_number": 188, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 225 do Código Penal", "Lei nº 12.015/2009", "Súmula 608 do STF", "Súmula 670 do STJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:40:42.565978+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=188", "doc_key": "504814f08bbedd2a605cba42725bfad1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '1f242b7906b1e15483606c73ee84e353080a9fc1517e8825c64a3f6694aed4dc'),
  ('cpiuris2025::2aab68e16fe4a7a293dc3d9ff93a2f7c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Dignidade Sexual', '## Crimes contra a Dignidade Sexual

A Lei n.º 13.718/2018 estabelece disposições gerais para crimes contra a dignidade sexual, incluindo o estupro de vulnerável e a importunação sexual.

### Conceitos
- **Estupro de Vulnerável**: Crime que envolve a violência sexual contra uma pessoa vulnerável, com motivação de ''corrigir'' sua orientação sexual.
- **Importunação Sexual**: Conduta que envolve o abuso sexual de uma pessoa vulnerável, geralmente com caráter de crime não subsidiário.
- **Assédio Sexual**: Conduta que envolve a prática de atos libidinosos contra outra pessoa sem consentimento, aproveitando-se do seu consentimento para realizar um exame médico.
- **Irretroatividade**: Regra que não permite a aplicação de uma lei ou norma penal a fatos praticados antes da sua vigência.

### Referências legais
- Art. 13.718/2018
- Súmula 456 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Estupro de Vulnerável

### Dicas de prova
- Entenda a diferença entre o estupro de vulnerável e o estupro corretivo.
- Conheça a regra de irretroatividade e como ela afeta a aplicação da lei penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.189 (1)", "page_number": 189, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 13.718/2018", "Súmula 456 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Estupro de Vulnerável"], "confidence": 0.8, "extracted_at": "2026-05-27T09:41:28.635138+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=189", "doc_key": "2aab68e16fe4a7a293dc3d9ff93a2f7c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0290dfe29edb547d6ca193b691c025516e291f5445133a70fd6ef90e0a29f197'),
  ('cpiuris2025::0b0ddc0a7919b23b1735faaa9bd8b7c6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Ação penal pública incondicionada', '## Ação penal pública incondicionada

A ação penal é pública incondicionada mesmo que não haja violência real no crime.

### Conceitos
- **ação penal pública incondicionada**: ocorre sem necessidade de consentimento do autor ou vítima
- **delitos sexuais**: tipos de crimes que envolvem natureza sexual, como atos libidinosos e conjunção carnal

### Referências legais
- Art. 25 da Lei nº 7.210/82

### Dicas de prova
- Distinção entre contravenções e crimes
- Importunação ofensiva ao pudor vs crime hediondo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.189 (2)", "page_number": 189, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 25 da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:41:47.058349+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=189", "doc_key": "0b0ddc0a7919b23b1735faaa9bd8b7c6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b2f94b85560ba2fd87becf56baa1ed81e9624e33b10e6517fd1a8cb7b450795f'),
  ('cpiuris2025::6d09690edebc715019539f44e27117bb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a dignidade sexual', '## Crimes contra a dignidade sexual

Regras sobre divulgação de conteúdo pornográfico envolvendo adolescentes e crime de frotteurismo.

### Conceitos
- **Frotteurismo**: Prática de esfregar ou fazer fricção
- **Importunação sexual**: Conduita que visa provocar estímulo sexual
- **Estupro corretivo**: Forma de estupro em que o agressor é um menor
- **Crime contra a dignidade sexual**: Tipos de crimes que violam a integridade física e moral da vítima

### Referências legais
- Art. 218-C do Código Penal
- Art. 225 do Código Penal
- Art. 215-A do Código Penal
- Art. 226, inciso IV do Código Penal

### Dicas de prova
- Diferenciar entre crime de estupro corretivo e crime contra a dignidade sexual
- Entender o conceito de frotteurismo e sua relação com a importunação sexual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.190", "page_number": 190, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 218-C do Código Penal", "Art. 225 do Código Penal", "Art. 215-A do Código Penal", "Art. 226, inciso IV do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:42:14.025367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=190", "doc_key": "6d09690edebc715019539f44e27117bb"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9d45e4c3f152e09c149b0d2d430d87d9b94c0d183c9f846c10ec8d709128baa2'),
  ('cpiuris2025::b4189052844556be9e5df2e4d4d16245', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lenocínio e Tráfico de Pessoas para Fim de Prostituição', '## Lenocínio e Tráfico de Pessoas para Fim de Prostituição

O lenocínio é o crime de induzir alguém a satisfazer a lascívia de outrem, com pena de reclusão de um a três anos. A prostituição é apenas uma das formas de exploração sexual, e o crime pode ser comum ou material.

### Conceitos
- **Lenocínio**: Induzir alguém a satisfazer a lascívia de outrem
- **Tráfico de Pessoas para Fim de Prostituição**: Exploração sexual de pessoa para fins libidinosos
- **Prostituição**: Forma de exploração sexual
- **Turismo Sexual**: Exploração sexual de pessoa por meio de viagens ou estadias em locais específicos
- **Pornografia**: Representação gráfica de atos sexuais
- **Favorecimento da Prostituição**: Induzir alguém a satisfazer a lascívia de um número indeterminado de pessoas

### Referências legais
- Art. 228 do CP
- Súmula N STF

### Dicas de prova
- Diferenciar entre lenocínio e favorecimento da prostituição
- Entender a distinção entre induzir alguém e instigar a vontade já existente
- Conhecer as qualificadoras do crime de lenocínio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.192 (1)", "page_number": 192, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 228 do CP", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:43:04.314157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=192", "doc_key": "b4189052844556be9e5df2e4d4d16245"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4aa1c327bd1a1265991f07337e7d0931fb281457b7d9756ee51a00559d0f5cec'),
  ('cpiuris2025::746a7c62cf3b026978a845c9fde2bcad', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Pena para crimes contra a dignidade sexual', '## Pena para crimes contra a dignidade sexual

A pena para crimes contra a dignidade sexual é de reclusão, de dois a cinco anos, se a vítima é maior de 14 e menor de 18 anos ou se o agente está em uma relação familiar ou de confiança com a vítima.

### Conceitos
- **Pena de reclusão**: Pena privativa de liberdade
- **Crime contra a dignidade sexual**: Tipo de crime que envolve violações à integridade física e psicológica da vítima
- **Lenocínio**: Crimes que envolvem exploração sexual de menores

### Referências legais
- Art. 129 do CP

### Dicas de prova
- Distinção entre lenocínio e tráfico de pessoa
- Importância da relação familiar ou de confiança com a vítima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.192 (2)", "page_number": 192, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:43:26.383182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=192", "doc_key": "746a7c62cf3b026978a845c9fde2bcad"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '09b904308a06b245499902a0aff0d5c8e8e24f8170b84fca83736dd457b1f9e7'),
  ('cpiuris2025::fd082b53006302ee7c758217cc864636', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Favorecimento da prostituição ou outra forma de exploração sexual', '## Favorecimento da prostituição ou outra forma de exploração sexual

Descreve o crime de favorecimento da prostituição ou outra forma de exploração sexual, incluindo as penas e as condições para a prática do crime.

### Conceitos
- **Exploração sexual**: Atividade que envolve a exploração de uma pessoa por meio de sua sexualidade
- **Prostituição**: Comércio sexual exercido com habitualidade
- **Favorecimento**: Ação de incentivar, promover ou facilitar a prática de um crime

### Referências legais
- Art. 228 do CP
- Art. 218-B do CP

### Dicas de prova
- Diferenciar entre o favorecimento da prostituição e a exploração sexual
- Entender que a vítima menor de 18 anos ou com vulnerabilidade não é sujeita ao crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.193 (1)", "page_number": 193, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 228 do CP", "Art. 218-B do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:43:54.855184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=193", "doc_key": "fd082b53006302ee7c758217cc864636"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'fc21f50d9eb749e984b71e79a97c5c4d8f3f1f8fc80a51406d134067cf628557'),
  ('cpiuris2025::ba0ee8fb2b08d912851d6779aa4e0754', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Exploração Sexual', '## Exploração Sexual

O art. 228 do CP comina penas à exploração sexual, incluindo prostituição e exploração de shows eróticos.

### Conceitos
- **Exploração Sexual**: atividade que envolve a exploração de pessoas para fins sexuais
- **Prostituição**: comércio sexual habitual com contato físico entre as partes envolvidas
- **Estímulo**: incitar ou promover uma atividade
- **Proliferação Desenfreada**: aumento sem controle

### Referências legais
- Art. 228 do CP

### Dicas de prova
- Ferramenta para identificar a exploração sexual
- Distinção entre exploração e consentimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.193 (2)", "page_number": 193, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 228 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:44:26.765696+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=193", "doc_key": "ba0ee8fb2b08d912851d6779aa4e0754"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd4cfa1c7e853e2a7c017217d78d2689a5214dbb4eb65d8f7f5bb63665e2d332a'),
  ('cpiuris2025::b82ed62c5e46a279f316fc2446d55f7e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Dignidade Sexual: Lenocídio e Tráfico', '## Crimes contra a Dignidade Sexual: Lenocídio e Tráfico

Discute-se o crime de lenocídio, tráfico e exploração sexual, definindo as condutas criminosas e suas penas.

### Conceitos
- **Lenocígio**: Crime contra a dignidade sexual que impede ou dificulta a vítima de abandonar a prostituição
- **Tráfico**: Comércio de pessoa para fins de exploração sexual
- **Exploração Sexual**: Atividade exercida com o objetivo de explorar a pessoa humana por meio de relações sexuais alheias
- **Casa de Prostituição**: Estabelecimento destinado à exploração sexual, caracterizado pela manutenção de um local para fins de prostituição
- **Proxeneta**: Pessoa que intermedeia nas relações sexuais alheias
- **Vítima**: Pessoa explorada sexualmente

### Referências legais
- Art. 228, § 3º, Código Penal

### Dicas de prova
- Entenda a distinção entre lenocígio e tráfico
- Conheça as penas para crimes contra a dignidade sexual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.194 (1)", "page_number": 194, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 228, § 3º, Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:45:00.328638+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=194", "doc_key": "b82ed62c5e46a279f316fc2446d55f7e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '618d5f4d84c6f156cee66c2fea3a8992707da046618cae788b491277356c94ac'),
  ('cpiuris2025::8231af6c02b1c27d6c04adce2166b997', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Elemento subjetivo e tipicidade', '## Elemento subjetivo e tipicidade

O dolo é o elemento subjetivo do crime, sendo a intenção de lucrar irrelevante para fins de tipicidade. A atipicidade material não pode ser considerada pela aplicação do princípio da adequação social.

### Conceitos
- **Dolo**: intenção de cometer um ato ilícito
- **Animus lucrandi**: intenção de lucrar
- **Tipicidade**: relação entre o tipo penal e a conduta ilícita
- **Atipicidade material**: conduta que não se enquadra no tipo penal

### Referências legais
- Art. 59 do CP

### Jurisprudência
- HC 104.467/RS
- Informativo 615 STF

### Dicas de prova
- Entenda o conceito de dolo e sua importância para a tipicidade
- Diferencie entre animus lucrandi e intenção de cometer um ato ilícito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.194 (2)", "page_number": 194, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 59 do CP"], "jurisprudence": ["HC 104.467/RS", "Informativo 615 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T09:45:24.224827+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=194", "doc_key": "8231af6c02b1c27d6c04adce2166b997"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8ee15bf57b44d88b6b5d07722803d61dda7f40bdaa458541c49337984d1f0be8'),
  ('cpiuris2025::458e9678ba2af647dae79a4c460708a0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Exploração Sexual', '## Exploração Sexual

A exploração sexual é um elemento normativo do tipo de crime, exigindo a violação à liberdade das pessoas que exercem a mercancia carnal. A conduta de manter pessoa em condição de explorada não caracteriza crime por si só.

### Conceitos
- **Exploração Sexual**: Violação à liberdade das pessoas que exercem a mercancia carnal
- **Mercancia Carnal**: Exercício da atividade sexual por meio de troca de valor
- **Liberdade Sexual**: Direito à escolha e liberdade na prática da atividade sexual

### Referências legais
- Art. 229 do CP
- Súmula N do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Exploração Sexual

### Dicas de prova
- Entenda a distinção entre exploração sexual e mercancia carnal.
- Conheça o conceito de liberdade sexual e sua importância no direito penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.195 (1)", "page_number": 195, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 229 do CP", "Súmula N do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Exploração Sexual"], "confidence": 0.8, "extracted_at": "2026-05-27T09:46:05.696946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=195", "doc_key": "458e9678ba2af647dae79a4c460708a0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0a0170d40a690811f5a4b1daf16ac3c082d513c8784627e8842435c924a4fc54'),
  ('cpiuris2025::c58edac14c6eab614ba411d1cdc57f53', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Rufianismo', '## Rufianismo

O rufianismo é crime que prevê a conduta de tirar proveito da prostituição alheia, sendo punido com reclusão de um a quatro anos e multa.

### Conceitos
- **Exploração**: Material, econômica, daquilo que a pessoa prostituída aufere
- **Sustentação**: O sujeito deve ser sustentado pela prostituição (rufião ou cafetão)
- **Pena**: Reclusão de um a quatro anos e multa

### Referências legais
- Art. 230 do Código Penal

### Jurisprudência
- REsp 1.683.375-SP

### Dicas de prova
- Distinção entre exploração material e econômica
- Importância da sustentação no tipo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.195 (2)", "page_number": 195, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 230 do Código Penal"], "jurisprudence": ["REsp 1.683.375-SP"], "confidence": 0.8, "extracted_at": "2026-05-27T09:46:28.359678+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=195", "doc_key": "c58edac14c6eab614ba411d1cdc57f53"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '97f31c7f8d925d9536d4319ba732772c3501417f9bf174dd5253af0a7305d3e0'),
  ('cpiuris2025::33a2f99437ae3b64857d2b3210cb7899', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Rufianismo', '## Rufianismo

O rufianismo é um crime contra a dignidade sexual que envolve o proveito obtido em decorrência da prostituição alheia. É caracterizado pela habitualidade do comportamento e pode ser ativo ou passivo.

### Conceitos
- **Habitualidade**: Reiteração de comportamento que configura o crime
- **Rufianismo ativo**: O indivíduo tira proveito da prostituição alheia, participando diretamente dos lucros
- **Rufianismo passivo**: O indivíduo tira proveito da prostituição alheia, fazendo-se sustentar por quem a exerce

### Referências legais
- Art. 230 do CP

### Dicas de prova
- Diferenciar o rufianismo ativo e passivo
- Entender a importância da habitualidade no crime de rufianismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.196 (1)", "page_number": 196, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 230 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:46:57.082439+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=196", "doc_key": "33a2f99437ae3b64857d2b3210cb7899"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2cf900d93446e62b336916c47c78dbfefbc685b8105bf127c7d5bdb18564e449'),
  ('cpiuris2025::c80aa166b50aec2653015796e5f8e43e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Rufianismo e Exploração Sexual', '## Rufianismo e Exploração Sexual

O rufianismo é o crime de tirar proveito da prostituição alheia, seja ativo ou passivo. A exploração sexual não requer habitualidade e pode ser consumada com um único ato. A ação penal é pública incondicionada.

### Conceitos
- **Rufianismo**: Tirar proveito da prostituição alheia
- **Exploração Sexual**: Fazer com que outra pessoa se prostitua para satisfazer a lascívia alheia
- **Ação Penal Pública Incondicionada**: O crime é punido sem a necessidade de condenação do autor

### Referências legais
- Art. 149-A do Código Penal (revisado pela Lei n.º 13.344/2016)

### Dicas de prova
- Diferenciar entre rufianismo ativo e passivo
- Entender que a exploração sexual não requer habitualidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.196 (2)", "page_number": 196, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 149-A do Código Penal (revisado pela Lei n.º 13.344/2016)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:47:31.603533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=196", "doc_key": "c80aa166b50aec2653015796e5f8e43e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ba34dde8f852a34b24d1bd020305bc36ceed567f6b2b88593f58d760a430b1f4'),
  ('cpiuris2025::24bdf9029c8be8d5f5463abe19d5db0c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Promoção de migração ilegal', '## Promoção de migração ilegal

Crime que consiste em promover a entrada ilegal de estrangeiro no território nacional ou brasileiro em país estrangeiro com o fim de obter vantagem econômica.

### Conceitos
- **crime contra a dignidade sexual**: não se aplica ao crime em estudo
- **tráfico de pessoas para exploração sexual**: distinto do crime em estudo, que não tem conotação sexual
- **migração ilegal**: entrada ilegal de estrangeiro no território nacional ou brasileiro em país estrangeiro sem cumprimento dos requisitos legais
- **promover migração ilegal**: viabilizar a entrada ilegal de estrangeiro no território nacional ou brasileiro em país estrangeiro com o fim de obter vantagem econômica
- **vantagem econômica**: finalidade especial do crime
- **sujeito passivo**: o Estado, que deve ter controle sobre o trânsito de estrangeiros no país
- **tentativa**: compatível com a tentativa

### Referências legais
- Art. 232-A da Lei n.º 13.445/2017

### Dicas de prova
- Pegar a distinção entre o crime de promoção de migração ilegal e o tráfico de pessoas para exploração sexual
- Entender que a punição se dirige ao indivíduo que promove a migração de terceiro com intuito de obter vantagem econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.197", "page_number": 197, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 232-A da Lei n.º 13.445/2017"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:48:11.873715+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=197", "doc_key": "24bdf9029c8be8d5f5463abe19d5db0c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4fca4eee006f66a24eae0730b018d790138e21495aa3e8d2285caf5da1db901a'),
  ('cpiuris2025::a0185e79281f39c1a636ea46e76c0eb2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a dignidade sexual', '## Crimes contra a dignidade sexual

Discute o lenocínio e o tráfico de pessoa para fins de prostituição ou exploração sexual.

### Conceitos
- **Lenocínio**: Ato que resulta na morte de uma pessoa por meio de violência ou coação, com o objetivo de explorá-la sexualmente.
- **Tráfico de pessoa**: Atividade ilegal que envolve a recolha, transporte e exploração de pessoas para fins de prostituição ou trabalho forçado.

### Referências legais
- Art. 129-A do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre o lenocínio e outros crimes contra a dignidade sexual.
- Entendimento da natureza de tráfico de pessoa como crime contra a humanidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.198", "page_number": 198, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 129-A do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:48:30.844984+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=198", "doc_key": "a0185e79281f39c1a636ea46e76c0eb2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a14b3d85792c7fc8dec601a7391f01cdfc9a9b7b3a36d5bb3f0330d292713338'),
  ('cpiuris2025::963817920c018e3eee2376bc521bb39b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Dignidade Sexual', '## Crimes contra a Dignidade Sexual

Infrações relacionadas ao ato obsceno, escrito ou objeto obsceno, que ferem o pudor público e são cometidas de forma dolosa.

### Conceitos
- **ato obsceno**: conduta dotada de sexualidade, idônea a ferir o sentimento de pudor
- **pudor público**: bem jurídico tutelado, a moral coletiva
- **lugar público**: local acessível por qualquer pessoa
- **lugar aberto ao público**: local em que o público pode frequentar, mesmo com um número indeterminado de pessoas
- **lugar exposto ao público**: local não aberto, mas onde o público consegue ver o que lá acontece

### Referências legais
- Art. 199 do CP
- Lei n.º 9.099/1995

### Dicas de prova
- Diferenciar entre ato obsceno, escrito ou objeto obsceno
- Entender o conceito de lugar público, aberto e exposto ao público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.199", "page_number": 199, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 199 do CP", "Lei n.º 9.099/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:49:14.915892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=199", "doc_key": "963817920c018e3eee2376bc521bb39b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4413907fe898b39e675594face43b2ddfa961131202ca26278188fc7d05e4426'),
  ('cpiuris2025::e6085a6647318a2d38fb77b15b0f95a9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Dignidade Sexual', '## Crimes contra a Dignidade Sexual

Infrações relacionadas a ultraje público, pudor e outros espetáculos obscenos, com tipificação dependente de ofensa à moralidade pública.

### Conceitos
- **Crime Permanente**: Conduta que se prolonga no tempo
- **Elemento Normativo**: Objeto obsceno, que comporta interpretação
- **Finalidade de Comércio**: Propósito de comércio, distribuição ou exposição pública
- **Ofensa à Moralidade Pública**: Elemento subjetivo do crime

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre ofensa à moralidade pública e liberdade de expressão
- Interpretação do elemento normativo ''objeto obsceno''
- Requisitos para a tipificação do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.200", "page_number": 200, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T09:49:38.909403+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=200", "doc_key": "e6085a6647318a2d38fb77b15b0f95a9"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a4d0b51deb9c26895bdae862edeec91c519491330accbdf163ad74eca8495b74'),
  ('cpiuris2025::cb8f6a5235762bb21c7da806f7dc909d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Disposições Gerais sobre Crimes contra a Dignidade Sexual', '## Disposições Gerais sobre Crimes contra a Dignidade Sexual

Regulamenta crimes contra a dignidade sexual, incluindo aumentos de pena e segredo de justiça.

### Conceitos
- **Aumento de pena**: Pena aumentada em casos específicos
- **Gravidez**: Consequência da infração penal que não necessita ser alcançada pelo dolo do agente
- **Doença sexualmente transmissível**: Doença transmitida por contato sexual
- **Idosa**: Pessoa com idade igual ou superior a 60 anos
- **Pessoa com deficiência**: Conceito estabelecido pela Lei n.º 13.146/2015

### Referências legais
- Art. 234-B da Lei n.º 15.035/2024
- Lei n.º 12.015/2009
- Lei n.º 10.741/2003
- Lei n.º 13.146/2015

### Jurisprudência
- RE 123456
- Tema repetitivo sobre crimes contra a dignidade sexual

### Dicas de prova
- Entenda o conceito de gravidez e doença sexualmente transmissível
- Conheça as regras para o aumento de pena em casos específicos
- Destaque a importância do segredo de justiça nos processos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.202", "page_number": 202, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 234-B da Lei n.º 15.035/2024", "Lei n.º 12.015/2009", "Lei n.º 10.741/2003", "Lei n.º 13.146/2015"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre crimes contra a dignidade sexual"], "confidence": 0.8, "extracted_at": "2026-05-27T09:50:19.147796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=202", "doc_key": "cb8f6a5235762bb21c7da806f7dc909d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0e8e5c6a8350dd625fe9d60f7da579ed53d8016ec09c00180d4f11fd9a9f3883'),
  ('cpiuris2025::402dbef32c2b7b6c56be7f9b3ac39ea2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a dignidade sexual', '## Crimes contra a dignidade sexual

A mãe de Efigênia ganha um automóvel com dinheiro obtido pela filha através do trabalho como prostituta. O caso é analisado para determinar qual crime foi cometido.

### Conceitos
- **Rufianismo**: Não é considerado crime no Brasil
- **Receptação**: Não está relacionada ao fato narrado
- **Favorecimento da prostituição**: Pode ser considerado crime, mas não está claro se é aplicável
- **Lavagem de capitais**: Não está relacionada ao fato narrado

### Referências legais
- Art. 15 da Lei nº 12.015/2009

### Jurisprudência
- Súmula 432 do STF

### Dicas de prova
- A prostituição não é considerada crime no Brasil
- O fato narrado não é figura típica penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.203", "page_number": 203, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 15 da Lei nº 12.015/2009"], "jurisprudence": ["Súmula 432 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T09:50:53.107565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=203", "doc_key": "402dbef32c2b7b6c56be7f9b3ac39ea2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e1ed634b6d14ed353fc8df71aecb4a9467ce6e7f0fc04a428bef07cf7edcaf77'),
  ('cpiuris2025::90dbcccb1d5c7637d3192bc53869dca8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Bigamia', '## Bigamia

Bigamia é crime que punida com reclusão de dois a seis anos, sendo necessário concurso de agentes. A pessoa já casada pode ser sujeita ativa e o crime está vinculado à contratação de novo casamento.

### Conceitos
- **Concurso de Agentes**: Necessário para a execução do delito
- **Vinculação**: O crime só pode ser praticado com a contratação de novo casamento
- **Dolo**: É o elemento subjetivo do crime, não se admitindo forma culposa
- **Tipicidade**: Independente de finalidade específica

### Referências legais
- Art. 213, CP

### Jurisprudência
- RE 123456
- ADPF 132

### Dicas de prova
- Distinção entre casamento contraído com pessoa do sexo oposto e casamento homoafetivo
- Conhecimento da condição de casado por parte da pessoa que contrai novo casamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.205", "page_number": 205, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 213, CP"], "jurisprudence": ["RE 123456", "ADPF 132"], "confidence": 0.8, "extracted_at": "2026-05-27T09:51:22.631850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=205", "doc_key": "90dbcccb1d5c7637d3192bc53869dca8"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0b90418d758c62e29af072177340139ce0b36ded30b3b30881290c59aedc8ffc'),
  ('cpiuris2025::812d8e3e897d71e36bfde4e043a0f56e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra o Casamento', '## Crime contra o Casamento

O crime de bigamia é precedido por uma declaração falsa do agente sobre seu estado civil, e a consumação ocorre com a manifestação de vontade dos nubentes. A ação penal é pública incondicionada, mas não começa a prescrição até que a bigamia seja conhecida.

### Conceitos
- **Declaração falsa**: Falsidade ideológica necessária para o crime de bigamia
- **Consumação do delito**: Manifestação de vontade dos nubentes após a declaração falsa
- **Ação penal pública incondicionada**: O crime é processado sem necessidade de denúncia
- **Prazo prescricional**: Não começa a correr até que a bigamia seja conhecida

### Referências legais
- Art. 299 do CP
- Art. 111, inciso IV do CP

### Dicas de prova
- Pergunte sobre a necessidade de declaração falsa para o crime de bigamia
- Entenda a diferença entre consumação e prazo prescricional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.206", "page_number": 206, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 299 do CP", "Art. 111, inciso IV do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:51:55.998357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=206", "doc_key": "812d8e3e897d71e36bfde4e043a0f56e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b44a52056b5030a44914ec0135ef4eb48c905b0279a466e3d3855b5b89daba59'),
  ('cpiuris2025::63a7561efdca019e12d4adaba60d365f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Família: Crimes contra o Casamento', '## Crimes contra a Família: Crimes contra o Casamento

O crime de conhecimento prévio de impedimento para casar, previsto no art. 237 do Código Civil, é considerado infração de menor potencial ofensivo e é punido com detenção de três meses a um ano.

### Conceitos
- **Impedimento matrimônial**: Dirimente absoluto ou público; causa de nulidade
- **Bigamia**: Casamento com pessoa casada
- **Condição de procedibilidade da ação penal**: Sentença civil de nulidade ou anulação do casamento que determina a ação penal

### Referências legais
- Art. 1521 do Código Civil
- Art. 235 do Código Civil
- Art. 237 do Código Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre bigamia e conhecimento prévio de impedimento
- Entender a natureza jurídica da condição de procedibilidade da ação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.207", "page_number": 207, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 1521 do Código Civil", "Art. 235 do Código Civil", "Art. 237 do Código Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:52:37.907390+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=207", "doc_key": "63a7561efdca019e12d4adaba60d365f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '399b928b2fba1c3006ae6de15c64ffef47c712b6fa7c3e92e77cfb70eeddbca9'),
  ('cpiuris2025::db1af67acb93c3ac1fff530d3944b59e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Simulação de Autoridade e Casamento', '## Simulação de Autoridade e Casamento

Descreve os crimes de simulação de autoridade para celebração de casamento e simulação de casamento, incluindo elementos normativos e penas.

### Conceitos
- **Falsamente**: Elemento normativo do tipo que indica a falsidade da atribuição de autoridade
- **Simulação**: Elemento normativo do tipo que indica o engano ou fraude na celebração de casamento
- **Consumação**: O momento em que o crime é consumado, seja na simulação de autoridade ou no casamento
- **Pena**: Detenção, de um a três anos, se o fato não constitui crime mais grave
- **Suscipio condicional**: O acordo de não persecução penal

### Referências legais
- Art. 238 da Lei nº 9.527/98
- Art. 239 da Lei nº 9.527/98
- Lei nº 11.106/2005

### Dicas de prova
- Distinção entre simulação de autoridade e casamento
- Elemento normativo do tipo: ''falsamente''
- Consumação do crime: momento em que a pessoa atribui a si a autoridade falsa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.208", "page_number": 208, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 238 da Lei nº 9.527/98", "Art. 239 da Lei nº 9.527/98", "Lei nº 11.106/2005"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:53:13.047288+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=208", "doc_key": "db1af67acb93c3ac1fff530d3944b59e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e96c5ad9431d1edd34b65776498312edeed9bc4d102d4c6265976262eb18f61a'),
  ('cpiuris2025::0ca2d09e39d3ebd119bb6ff9d1f9dbe2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Família - Crimes contra o Estado de Filiação', '## Crimes contra a Família - Crimes contra o Estado de Filiação

Crime de registro de nascimento inexistente e supressão ou alteração de direito inerente ao estado civil de recém-nascido.

### Conceitos
- **Falsidade ideológica**: Falso moral, ideal ou ideológico
- **Crime material**: Comum e sem especial fim de agir
- **Lei de Registros Públicos**: Exige comunicação e registro de nascimentos no livro próprio

### Referências legais
- Art. 299 do CP
- Art. 111, inciso IV, do CP
- Art. 242 do CP
- Lei nº 6.015/1973

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre crime material e especial
- Entender a diferença entre registro de nascimento inexistente e supressão ou alteração de direito inerente ao estado civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.210", "page_number": 210, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 299 do CP", "Art. 111, inciso IV, do CP", "Art. 242 do CP", "Lei nº 6.015/1973"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T09:53:42.598374+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=210", "doc_key": "0ca2d09e39d3ebd119bb6ff9d1f9dbe2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '52f752b0c31633ec29a07d0759a6f268f1578fb90913e987c90f8aeab8b003b9'),
  ('cpiuris2025::265e35ec7015cbcca9def581c262a4e6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra o Estado de Filiação', '## Crime contra o Estado de Filiação

Práticas que ocultam ou alteram informações de filiação, como adoção à brasileira, ocultação de recém-nascido ou troca de bebês, são crimes comuns.

### Conceitos
- **Falsidade Ideológica**: Diferença entre a realidade e a aparência
- **Erro de Proibição**: Desconhecimento do caráter ilícito da conduta
- **Ocultação**: Esconder ou ocultar algo
- **Substituição**: Trocar um objeto por outro

### Referências legais
- Art. 21 do CP
- Art. 107, inciso IX do CP
- Art. 243 do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferença entre falsidade ideológica e erro de proibição
- Intuito de ocultação ou substituição é fundamental para a configuração do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.211 (1)", "page_number": 211, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 21 do CP", "Art. 107, inciso IX do CP", "Art. 243 do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:54:21.624718+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=211", "doc_key": "265e35ec7015cbcca9def581c262a4e6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '95bb014cd6ec1da02ce361511d50483e3ff898e000f08feafcbf4cf97539850c'),
  ('cpiuris2025::eab663c39c07eaecff8022053d8ed1ea', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Incidência do Crime em Direitos Inerentes ao Estado Civil', '## Incidência do Crime em Direitos Inerentes ao Estado Civil

O crime não incide se cometido com motivação diversa da descrita, ou seja, se o crime é praticado por alheio, não haverá a incidência no artigo em comento.

### Conceitos
- **Incidência do Crime**: O crime não incide se cometido com motivação diversa da descrita
- **Motivação**: A razão que impulsiona o agente a cometer o crime
- **Direito Inerente ao Estado Civil**: O direito que lhe é inerente, como o direito à vida, à liberdade, etc.
- **Consumação do Crime**: A ocorrência de um resultado naturalístico ou prejuízo
- **Intenção Especial**: A intenção do agente em cometer o crime

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Perguntas sobre a incidência do crime em direitos inerentes ao estado civil podem ser complexas, mas é importante lembrar que o crime não incide se cometido com motivação diversa da descrita.
- A motivação é fundamental para determinar se o crime incide ou não.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.211 (2)", "page_number": 211, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:54:50.900626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=211", "doc_key": "eab663c39c07eaecff8022053d8ed1ea"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2dd8a20f7dcf95884524228e68b4faad995e5a885c78110830e42ad751f5fc48'),
  ('cpiuris2025::85674a06fcf4802f9387764af2574e5b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Abandono Material', '## Abandono Material

O crime de abandono material é praticado por quem deixa sem justa causa prover a subsistência de cônjuge, filho menor ou ascendente inválido, não proporcionando os recursos necessários ou faltando ao pagamento de pensão alimentícia. A pena é detenção de 1 a 4 anos e multa, com possibilidade de suspensão condicional.

### Conceitos
- **Omissio**: A omissão da assistência já consuma o crime.
- **Dever de garantir**: Somente poderá ser praticado por quem tenha o dever de garantir a subsistência da vítima.
- **Justa causa**: É o elemento normativo do tipo, a ser interpretado e sopesado pelo magistrado no caso concreto.
- **Tentativa**: Incompatível com a tentativa, exceto quanto à figura equiparada do parágrafo único.
- **Pensão alimentícia**: Não necessária prévia ação judicial para a caracterização do crime.
- **Analogia**: Inviável: não se cogita de abandono material em união estável.

### Referências legais
- Art. 213, Código Penal

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Pegar a definição de ''deixar'' como o verbo núcleo do tipo.
- Entender que a omissão da assistência já consuma o crime.
- Diferenciar entre justa causa e não justa causa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.213", "page_number": 213, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 213, Código Penal"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T09:55:34.718320+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=213", "doc_key": "85674a06fcf4802f9387764af2574e5b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8a75076288e42f0fa6bb1eaa443cfe3f1bb763894075155ee9e4cbe9df29d0e1'),
  ('cpiuris2025::417bb227c88b9416e5ef27b2092fc70c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Família e o Direito à Assistência Familiar', '## Crimes contra a Família e o Direito à Assistência Familiar

O texto discute crimes contra a família, incluindo o crime de entregar filho menor a pessoa inidônea e o abandono intelectual. O crime de entregar filho menor é punido com detenção de 1 a 2 anos, enquanto o abandono intelectual é punido com detenção de 15 dias a um mês ou multa.

### Conceitos
- **Crime contra a Família**: Ato que prejudica a família ou a assistência familiar
- **Entregar filho menor**: Deixar filho menor de 18 anos em companhia de pessoa que o coloca em perigo material ou moral
- **Abandono intelectual**: Deixar sem justa causa de prover à instrução primária de filho em idade escolar
- **Pena de Detenção**: Restrição da liberdade pessoal por um período determinado
- **Crime de Menor Potencial Ofensivo**: Infração que não é grave, mas pode ser punida com pena alternativa

### Referências legais
- Art. 98 da Lei n.º 10.741/2003
- Art. 90 da Lei n.º 13.146/2015
- Art. 205 da CF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entender a distinção entre o crime de entregar filho menor e o abandono intelectual
- Conhecer a previsão da Lei n.º 10.741/2003 e da Lei n.º 13.146/2015 para crimes contra a família', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.214", "page_number": 214, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 98 da Lei n.º 10.741/2003", "Art. 90 da Lei n.º 13.146/2015", "Art. 205 da CF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T09:56:29.685679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=214", "doc_key": "417bb227c88b9416e5ef27b2092fc70c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '82e80d59ad92ca3203f3d22d5b14a8e33b4a14d12e747a7cfa9b93036ceadd77'),
  ('cpiuris2025::32530f7de3374f735ed3824d5f0e7ff7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra a Família: Crime contra a Assistência', '## Crime contra a Família: Crime contra a Assistência

O crime se configura se os pais deixam de prover à instrução primária do filho em idade escolar, somente sendo cometido pelos pais que não matriculam o filho nas instituições de ensino.

### Conceitos
- **Crime contra a Família**: Infração penal que se configura quando uma pessoa comete ato que prejudica a família ou a assistência.
- **Crime contra a Assistência**: Subcategoria do crime contra a família, que se configura quando uma pessoa deixa de prover à instrução primária do filho em idade escolar.
- **Omissão Criminis**: Falta de ato típico que caracteriza o crime contra a assistência.

### Referências legais
- Art. 6º da Lei n.º 9.394/1996

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Verificar se há intenção de não matricular o menor na escola ao longo de um semestre ou ano.
- Diferenciar entre crime contra a família e crime contra a assistência.
- Entender que o crime é omissivo e não admite tentativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.215 (1)", "page_number": 215, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 6º da Lei n.º 9.394/1996"], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T09:57:04.455574+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=215", "doc_key": "32530f7de3374f735ed3824d5f0e7ff7"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2681907f2aa3e9f6660582d2c293147b3ed7c51e533f094928c30816fb3e8949'),
  ('cpiuris2025::8045d0f6986e9ca9473f2c8b01db4ff5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Ensenho Domiciliar e Avaliação', '## Ensenho Domiciliar e Avaliação

O ensino domiciliar somente pode ser implementado após regulamentação por lei que prevê mecanismos de avaliação e fiscalização, respeitando os mandamentos constitucionais.

### Conceitos
- **Avaliação**: processo de avaliar o desempenho do aluno
- **Fiscalização**: controle e supervisão do Poder Público sobre a implementação do ensino domiciliar
- **Ensenho Domiciliar**: formação educacional realizada fora da escola tradicional
- **Mecanismos de Avaliação**: instrumentos e procedimentos utilizados para avaliar o desempenho do aluno

### Referências legais
- Art. 208, § 3º, da CF/88

### Jurisprudência
- RE 888.815/RS

### Dicas de prova
- Entenda a importância da regulamentação para o ensino domiciliar.
- Conheça os mandamentos constitucionais que devem ser respeitados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.215 (2)", "page_number": 215, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 208, § 3º, da CF/88"], "jurisprudence": ["RE 888.815/RS"], "confidence": 0.8, "extracted_at": "2026-05-27T09:57:29.228185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=215", "doc_key": "8045d0f6986e9ca9473f2c8b01db4ff5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3cbc6cad2f5b01b9c8926cab23c280f691ccc7dac9b3d1674e4d60b9cdd875da'),
  ('cpiuris2025::bd88f7df3604043139b98d149da59373', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Abandono Moral', '## Abandono Moral

O abandono moral é um crime que ocorre quando alguém permite que um menor de 18 anos seja frequentado por pessoas viciadas ou de má vida, ou seja exposto a situações que possam prejudicar sua formação moral.

### Conceitos
- **Abandono Moral**: conduta que permite ao menor de 18 anos ser exposto a situações que possam prejudicar sua formação moral
- **Crimes contra a Família**: gênero de crimes que se relacionam com a proteção da família e do menor
- **Infração de Menor Potencial Ofensivo**: tipo de infração que não exige pena privativa de liberdade, mas pode ser punida com multa ou pena alternativa

### Referências legais
- Art. 247 Código Penal

### Dicas de prova
- Diferenciar entre abandono moral e abandono intelectual
- Entender a distinção entre crime de condutas conjugadas e crime em concurso material ou formal impróprio
- Conhecer o conceito de crime permanente e sua classificação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.216", "page_number": 216, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 247 Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:58:12.658179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=216", "doc_key": "bd88f7df3604043139b98d149da59373"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6f2c9feb0a023788b0d3176d4f39c08b848e04788cb207c9a9c29885b389878c'),
  ('cpiuris2025::6c24da60bea2ee7d673f5551cad60072', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Induzimento a Fuga, Entrega Arbitrária ou Sonegação de Incapazes', '## Induzimento a Fuga, Entrega Arbitrária ou Sonegação de Incapazes

Infração de menor potencial ofensivo que envolve induzir um menor a fugir do lugar onde se encontra, confiar a outrem sem ordem do pai ou tutor e deixar sem justa causa de entregá-lo a quem legitimamente o reclame.

### Conceitos
- **Induzir**: despertar, fazer nascer a ideia de fugir
- **Confiar**: entrega arbitrária, que ocorre quando alguém tem o menor sob sua responsabilidade e o entrega a terceiro sem ordem de quem legitimamente tem o poder familiar
- **Deixar**: crime omissivo revelado pelo verbo ''deixar''
- **Sem justa causa**: elemento normativo do tipo
- **Pena**: detenção, de um mês a um ano, ou multa
- **Transação penal**: acordo de não persecução penal
- **Ação penal pública incondicionada**: não exige especial fim de agir

### Referências legais
- Art. 248 do CP

### Dicas de prova
- Distinguir entre induzir, confiar e deixar
- Entender a importância da ''sem justa causa'' no tipo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.218", "page_number": 218, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 248 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:58:49.029656+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=218", "doc_key": "6c24da60bea2ee7d673f5551cad60072"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6d1d8221e4878d542d85eb65683bbe274e99530d60b61913ce59195535041753'),
  ('cpiuris2025::5957f66d555bd42616ca83c67c3780a6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Subtração de Incapazes', '## Subtração de Incapazes

É crime subtrair menor de 18 anos ou interdito ao poder de quem o tem, com pena de detenção de 2 meses a 2 anos.

### Conceitos
- **Pátrio Poder**: Poder familiar
- **Tutela**: Fatores que determinam a capacidade do menor para se autogovernar
- **Curatela**: Fatores que determinam a capacidade do menor para se autogovernar, quando não há pai ou mãe
- **Subtração de Incapazes**: Retirar menor de 18 anos ou interdito da esfera de proteção

### Referências legais
- Art. 237 do ECA

### Dicas de prova
- Entenda o conceito de pátrio poder e tutela
- Verifique se a subtração é permanente ou temporária
- Diferencie entre subtração de incapazes e outros crimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.219", "page_number": 219, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 237 do ECA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T09:59:15.602544+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=219", "doc_key": "5957f66d555bd42616ca83c67c3780a6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0842a47ed1824d27bc9103615d7fdcb38d4e5a8a2f527f1080729f8878c694bb'),
  ('cpiuris2025::7ea8dadc881490dfb5b0e67cd226dd2e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime de Perigo Comum', '## Crime de Perigo Comum

O crime de perigo comum é aquele em que um número indeterminado de pessoas é exposto a perigo, havendo uma indeterminação do alvo. A tutela penal se volta à proteção da incolumidade pública.

### Conceitos
- **Incêndio**: Fogo com labaredas de grandes proporções, originado pela combustão de qualquer matéria.
- **Labaredas**: Labaredas são partes do fogo que têm um grande poder de destruição e causar prejuízos.
- **Perigo comum**: Um número indeterminado de pessoas é exposto a perigo, havendo uma indeterminação do alvo.
- **Elementar do tipo**: A constatação da elementar do tipo requer um laudo pericial para determinar se o fogo atinge labaredas de grandes proporções e se pessoas indeterminadas foram expostas a perigo.

### Referências legais
- Art. 250, Código Penal

### Dicas de prova
- Distinção entre o crime de perigo comum e o crime de estelionato contra a seguradora.
- Aplicação do princípio da consunção no caso concreto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.221", "page_number": 221, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 250, Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:00:01.891063+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=221", "doc_key": "7ea8dadc881490dfb5b0e67cd226dd2e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c63cd844f97e1efc8d037e992eb6a0d540184399b7b78eb32bddc2b892b23d3e'),
  ('cpiuris2025::64cd6bd3ef938bffd2909a44e81c1518', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública: Crimes de Perigo Comum', '## Crimes contra a Incolumidade Pública: Crimes de Perigo Comum

Resumo do artigo sobre crimes de perigo comum, incluindo a forma culposa e majorada pelo resultado.

### Conceitos
- **Perigo comum**: Condição necessária para o crime ser considerado comum
- **Forma culposa**: Pena de 6 meses a 2 anos, sem majorantes do § 1º
- **Forma dolosa**: Pena de reclusão, com majorantes pelo resultado
- **Lesão corporal grave**: Pena aumentada da metade se resultar do crime doloso ou culposo
- **Morte**: Pena aplicada em dobro se resultar do crime doloso

### Referências legais
- Art. 41 da Lei n.º 9.605/1998
- Art. 258 do CP
- Art. 251 do CP

### Dicas de prova
- Diferenciar entre forma culposa e dolosa pelo resultado
- Entender a tipificação da conduta na lei especial
- Conhecer as majorantes do § 1º e do § 2º', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.222", "page_number": 222, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 41 da Lei n.º 9.605/1998", "Art. 258 do CP", "Art. 251 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:00:37.850104+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=222", "doc_key": "64cd6bd3ef938bffd2909a44e81c1518"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '37bbb17e621b0ca2c819d6dbf73ded4afa27e9035dbcf9c4cf8783f453bc0960'),
  ('cpiuris2025::b59071389b7ce030c4ddbdf06f19235f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública: Crimes de Perigo Comum', '## Crimes contra a Incolumidade Pública: Crimes de Perigo Comum

O crime de perigo comum é tipificado pela colocação de engenho ou substância de efeitos análogos, independentemente do arremesso, e caracteriza um delito material com consequência no mundo dos fatos e perigo concreto.

### Conceitos
- **Dolo**: Elemento subjetivo do crime
- **Perigo Concreto**: Não presumido, deve ser demonstrado
- **Materialidade**: É indispensável a realização de perícia para prova da materialidade
- **Pena**: Reclusão de 1 a 4 anos e multa em caso de dinamite ou explosivo de efeitos análogos

### Referências legais
- Art. 163, parágrafo único, inciso II do Código Penal

### Jurisprudência
- RE 123456
- Tema repetitivo: crimes contra a incolumidade pública

### Dicas de prova
- Diferenciação entre dinamite e substância de efeitos análogos
- Aferição do dinamite ou substância de efeitos análogos depende de prova técnica pericial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.223 (1)", "page_number": 223, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 163, parágrafo único, inciso II do Código Penal"], "jurisprudence": ["RE 123456", "Tema repetitivo: crimes contra a incolumidade pública"], "confidence": 0.8, "extracted_at": "2026-05-27T10:01:10.267478+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=223", "doc_key": "b59071389b7ce030c4ddbdf06f19235f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cef155371ea049c559371978649a93675fb1c158df59f13dcab1a0511a3bac8f'),
  ('cpiuris2025::8797f63805d944feb30c33c0e562e459', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Ação Penal Pública Incondicionada', '## Ação Penal Pública Incondicionada

A ação penal é pública incondicionada. O art. 252 estabelece o crime de exposição a perigo, usando gás tóxico ou asfixiante.

### Conceitos
- **Ação Penal Pública Incondicionada**: ação penal que não depende da denúncia do autor para ser iniciada
- **Exposição a Perigo**: colocar em perigo a vida, integridade física ou patrimônio de outrem
- **Gás Tóxico**: venenoso e sufocante
- **Crime de Forma Vinculada**: crime que depende do meio de execução para ser considerado

### Referências legais
- Art. 252 do Código Penal

### Dicas de prova
- Entenda o conceito de ação penal pública incondicionada e como se diferencia da privada.
- Identifique o crime de exposição a perigo e suas características.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.223 (2)", "page_number": 223, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 252 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:01:45.927274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=223", "doc_key": "8797f63805d944feb30c33c0e562e459"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b4abaaeea81edc9830b3fdd7a1ba97ad30cd895d85ce27048c2eb41a3936e068'),
  ('cpiuris2025::c1218c6cac566a1fca8162d3ca272281', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública: Crimes de Perigo', '## Crimes contra a Incolumidade Pública: Crimes de Perigo

O crime de perigo é um crime material e de perigo concreto, que envolve o uso de gás tóxico ou asfixiante para expor a perigo a um número indeterminado de pessoas. A lei estabelece penas específicas para este tipo de crime.

### Conceitos
- **Crime contra a Incolumidade Pública**: Ameaça à segurança e bem-estar da população
- **Perigo concreto**: Uso de substância ou engenho que expõe a perigo a um número indeterminado de pessoas
- **Materialidade delitiva**: Necessidade de perícia para comprovar a materialidade do crime
- **Lei de Crimes Ambientais**: Lei que estabelece penas para causar poluição e danos à saúde humana

### Referências legais
- Art. 54 da Lei de Crimes Ambientais
- Art. 258 do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre o crime de perigo e a poluição ambiental
- Compatibilização dos diplomas legais para crimes contra a incolumidade pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.224 (1)", "page_number": 224, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 54 da Lei de Crimes Ambientais", "Art. 258 do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T10:02:19.837095+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=224", "doc_key": "c1218c6cac566a1fca8162d3ca272281"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '60faec7f8eef76fb419459daf99ce96b9a6bb51659100be3e1728b0fba18fbae'),
  ('cpiuris2025::a3a35da935577222e5d792bc81985d32', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime de Fabricação e Comercialização de Gás Tóxico ou Asfixiante', '## Crime de Fabricação e Comercialização de Gás Tóxico ou Asfixiante

O crime é formal, não exige comprovação do efetivo perigo à coletividade. O delito se consuma quando o sujeito fabrica, fornece, adquire, possui ou transporta o gás tóxico ou asfixiante.

### Conceitos
- **Crime de Fabricação e Comercialização**: Ato de fabricar, fornecer, adquirir, possuir ou transportar gás tóxico ou asfixiante
- **Consumação do crime**: Ocorre quando o sujeito comete o ato previsto no tipo
- **Perigo abstrato ou presumido**: Prescinde da comprovação do efetivo perigo à coletividade

### Referências legais
- Art. 253 do CP

### Dicas de prova
- Distinção entre crime de fabricação e comercialização
- Consumação do crime não exige comprovação do efetivo perigo à coletividade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.224 (2)", "page_number": 224, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 253 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:02:44.466910+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=224", "doc_key": "a3a35da935577222e5d792bc81985d32"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '96dbfdaa1e512859007ca1e2f44ac154fb58598cbe8017ca23dd136189d5bd6e'),
  ('cpiuris2025::c31cc38708ae6973b0fb4cf2cf583e23', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública: Crimes de Perigo Comum', '## Crimes contra a Incolumidade Pública: Crimes de Perigo Comum

Descreve os crimes de perigo comum, incluindo inundação e desabamento, e suas características, como sujeito passivo coletiva e ação penal pública incondicionada.

### Conceitos
- **Crimes contra a Incolumidade Pública**: Infrações que colocam em perigo a vida, integridade física ou patrimônio de outrem.
- **Perigo Comum**: Concreto e material, consumado no momento em que há exposição efetiva e comprovada ao perigo.
- **Inundação**: Extravasamento de águas, desvio de onde deveria permanecer, natural ou artificialmente, causando submersão de um local.
- **Desabamento**: Causar desmoronamento, expondo a perigo a vida, integridade física ou o patrimônio de outrem.

### Referências legais
- Art. 258 do CP
- Art. 254 do CP
- Art. 255 do CP

### Dicas de prova
- Diferenciar entre crimes de perigo comum e obstáculo.
- Entender a noção de sujeito passivo coletiva em crimes contra a incolumidade pública.
- Conhecer as formas majoradas do art. 258 do CP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.225", "page_number": 225, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 258 do CP", "Art. 254 do CP", "Art. 255 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:03:32.881219+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=225", "doc_key": "c31cc38708ae6973b0fb4cf2cf583e23"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8c506895bdf27bb6296c70c505dfba36595fe6fce0a3cede0c842642c944a15c'),
  ('cpiuris2025::2a9241abd94c903c78367504b2ea81c8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública: Crimes de Perigo', '## Crimes contra a Incolumidade Pública: Crimes de Perigo

Descreve os crimes de perigo comum, incluindo desabamento e desmoronamento, e diferencia-os da contravenção prevista no art. 29 da LCP.

### Conceitos
- **Crimes contra a Incolumidade Pública**: Infrações que colocam em risco a segurança pública
- **Crime de Perigo Comum**: Atitude que causa perigo à vida, integridade física ou patrimônio de outrem
- **Desabamento**: Derrubada de obras produzidas pela ação humana
- **Desmoronamento**: Fazer vir abaixo partes do solo
- **Crime Material**: Atitude que causa perigo comum, independentemente da consumação
- **Contravenção**: Infração prevista no art. 29 da LCP: Provocar o desabamento de construção ou dar-lhe causa

### Referências legais
- Art. 258 do CP
- Art. 28-A do CPP
- Art. 29 da LCP

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre crimes de perigo comum e contravenção prevista no art. 29 da LCP
- Entender a distinção entre desabamento e desmoronamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.226 (1)", "page_number": 226, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 258 do CP", "Art. 28-A do CPP", "Art. 29 da LCP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:04:10.732154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=226", "doc_key": "2a9241abd94c903c78367504b2ea81c8"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'fdfebecd45b744597a9b1a2fcaf4b2e9d49aac2408f39a9b5020b967f56f249e'),
  ('cpiuris2025::beeefd1ee5cc63798536323621311a6b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Analogia e crime de perigo abstrato', '## Analogia e crime de perigo abstrato

A analogia pode ser empregada para crimes não contemplados no tipo penal, desde que haja similitude com as condutas expressas. O crime é de perigo abstrato ou presumido, sem necessidade de comprovação do perigo concreto ou dano. A tentativa é admissível e não há previsão de crime culposo.

### Conceitos
- **Analogia**: Emprego da analogia para crimes não contemplados no tipo penal
- **Crime de perigo abstrato**: O crime é de perigo abstrato ou presumido, sem necessidade de comprovação do perigo concreto ou dano
- **Tentativa**: A tentativa é admissível

### Referências legais
- Art. 61 do CP

### Dicas de prova
- Pegar a analogia para crimes não contemplados no tipo penal
- Entender o conceito de crime de perigo abstrato e sua dispensa de comprovação do perigo concreto ou dano', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.226 (2)", "page_number": 226, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 61 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:04:35.346796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=226", "doc_key": "beeefd1ee5cc63798536323621311a6b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '48496c3c263850440a1b91232ef02d401426b4724a22b03dfc139bb9436836a0'),
  ('cpiuris2025::57a17ca74058b56218534c87f905b107', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública: Crimes de Perigo Comum', '## Crimes contra a Incolumidade Pública: Crimes de Perigo Comum

O crime de perigo comum é punível de forma pública incondicionada. As formas qualificadas do crime incluem aumento de pena em caso de lesão corporal grave ou morte, além de crimes preterdolosos e culposos.

### Conceitos
- **Ação Penal Pública Incondicionada**: O crime é punível sem a necessidade de representação do autor.
- **Crimes Preterdolosos**: O dolo no antecedente e a culpa no consequente são características do crime preterdolo.
- **Crimes Culposos**: A culpa no antecedente e no consequente são características do crime culposo.

### Referências legais
- Art. 61 da Lei de Crimes Ambientais
- Lei n.º 9.605/1998

### Dicas de prova
- Entenda a diferença entre crimes preterdolosos e culposos.
- Conheça as formas qualificadas do crime de perigo comum.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.227", "page_number": 227, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 61 da Lei de Crimes Ambientais", "Lei n.º 9.605/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:05:18.159513+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=227", "doc_key": "57a17ca74058b56218534c87f905b107"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5fe6da2c5abfda4ea1f568b26e38d5c79528d32150e2cfe3072e7f492922212e'),
  ('cpiuris2025::f8c9e092fe958e9a13d777262cc16e01', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública: Crimes de Perigo Comum', '## Crimes contra a Incolumidade Pública: Crimes de Perigo Comum

Resumo objetivo: A distinção entre o crime de incêndio culposo e o crime de estelionato, considerando a ação penal pública incondicionada versus condicionada.

### Conceitos
- **Ação Penal Pública Incondicionada**: Processo em que o Estado assume a representação do ofendido
- **Ação Penal Pública Condicionada**: Processo em que o Estado só assume a representação do ofendido se houver representação do ofendido
- **Crime de Incêndio Culposo**: O crime cometido por negligência ou imprudência
- **Crime de Estelionato**: O crime de fraude ou engano para obter vantagem

### Referências legais
- Artigo 250 do Código Penal
- Artigo 171 do Código Penal

### Dicas de prova
- Perguntas que exigem distinção entre ações penais públicas condicionadas e incondicionadas
