  ('cpiuris2025::9476b959c7e00397eaeeaeb4e390a4fb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra a Incolumidade Pública: Perigo de Desastre Ferroviário', '## Crime contra a Incolumidade Pública: Perigo de Desastre Ferroviário

O crime previsto no art. 260 é o de impedir ou perturbar serviço de estrada de ferro, com pena de reclusão de dois a cinco anos e multa.

### Conceitos
- **Taxatividade da lei penal**: A necessidade de que os tipos penais sejam claros e determinados
- **Crime vago**: O crime é comum, podendo ser praticado por qualquer pessoa, inclusive por funcionários da empresa ferroviária
- **Perigo concreto**: O perigo de desastre deve ser efetivamente comprovado
- **Delito preterdoloso**: Não admite tentativa
- **Infração de menor potencial ofensivo**: A pena é de detenção, de seis meses a dois anos

### Referências legais
- Art. 260 do Código Penal
- Súmula 342 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: crime contra a incolumidade pública

### Dicas de prova
- Pegar a fórmula genérica ''outro ato de que possa resultar desastre'' para aplicação da analogia intra legem
