Resumo objetivo: A conduta de surfista em trem não é típica, pois não há dolo de criar uma situação de perigo de desastre ferroviário. O crime de perigo de desastre ferroviário é apenado com reclusão e compete à Justiça Estadual.

### Conceitos
- **Dolo**: intenção de causar dano
- **Incolumidade Pública**: segurança e bem-estar da população
- **Competência**: Justiça Estadual tem competência para processar e julgar crimes contra a incolumidade pública

### Referências legais
- Art. 260, IV, § 2º, c/c art. 263 do CP

### Jurisprudência
- STJ. 6ª Turma. RHC 50.054-SP
- Súmula N da STF

### Dicas de prova
- Distinção entre dolo e intenção
