  ('cpiuris2025::50fc39fd21c0ae4789f0fcc817d87aff', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime de Perigo Concreto', '## Crime de Perigo Concreto

Descreve o crime de perigo concreto, considerado misto alternativo e de conteúdo múltiplo, com formas ''expor'', ''praticar'', ''impedir'' e ''dificultar''. Exige demonstração de perigo à incolumidade pública e não se preocupa com a finalidade da conduta.

### Conceitos
- **Crime de Perigo Concreto**: O crime que coloca a incolumidade pública em situação de risco
- **Misto Alternativo**: Tipo de crime que pode ser praticado de várias formas
- **Perigo Concreto**: Exigência do crime, que não se trata apenas de previsão de dano
- **Momento Consumativo Formal**: O crime é formal, independentemente do efetivo prejuízo à navegação

### Referências legais
- Art. 263
- Art. 258 do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre a forma de crime e suas consequências
- Distinção entre perigo concreto e previsão de dano
