  ('cpiuris2025::1169fd1787a4d0941e5a354ba80f4a42', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública', '## Crimes contra a Incolumidade Pública

Discute-se crimes contra a segurança dos meios de comunicação e transporte, bem como outros serviços públicos. São abordados os crimes de naufrágio, submersão, encalhe, atentado contra a segurança de outro meio de transporte e abuso na prática da aviação.

### Conceitos
- **Naufrágio**: Submersão ou encalhe de embarcação
- **Atentado contra a segurança de outro meio de transporte**: Expor perigo a outro meio de transporte público, impedir-lhe ou dificultar-lhe o funcionamento
- **Abuso na prática da aviação**: Entregar-se na prática da aviação, acrobacias ou voos baixos fora da zona permitida

### Referências legais
- Art. 35 do Decreto-lei n.º 3.688/1941
- Art. 261 e 262 do CP
- Art. 109, inciso IX, da CF
- Lei n.º 9.099/1995

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre crimes contra a segurança de meios de transporte público e particulares
