  ('cpiuris2025::b90b19641f7a7f007eae7f29cbf21181', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Variado', '## Variado

O crime variado é único se praticado com mais de um verbo em contexto fático. É formal e de perigo concreto, exigindo demonstração do perigo causado à incolumidade pública.

### Conceitos
- **Crime Variado**: É o crime que se pratica com mais de um verbo em contexto fático.
- **Formalidade**: O crime é formal, independentemente da ocorrência de desastre.
- **Perigo Concreto**: O crime exige a efetiva demonstração do perigo causado à incolumidade pública.
- **Desastre**: A ocorrência de desastre aumenta a pena, conforme o § 1º.
- **Pena de Reclusão**: É a pena aplicada em caso de desastre, de 2 a 5 anos.
- **Culpa**: Se ocorrer culpa, a pena será detenção, de 3 meses a 1 ano.
- **Infração Menor Potencial Ofensivo**: É a categoria de infrações que inclui crimes como o variado.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre crime formal e informal.
- Entender a importância do perigo concreto no crime variado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.232 (2)", "page_number": 232, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:09:06.921141+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=232", "doc_key": "b90b19641f7a7f007eae7f29cbf21181"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '775a6bad5ac57332051af100c83d481e093cf85792fe18d090079567843212ca'),
