Discute-se o crime de arremesso de projétil e suas características, incluindo forma majorada e conceito de projétil.

### Conceitos
- **Arremessar projétil**: conduta punida com detenção
- **Forma majorada**: aplicação do art. 258 em caso de desastre ou sinistro
- **Projétil**: objeto sólido utilizado no crime

### Referências legais
- Art. 263
- Art. 258
- Art. 260 a 262

### Dicas de prova
- Entenda o conceito de projétil e suas características
