  ('cpiuris2025::cfa2ae8c3dff6bd140b5c99958f83c6a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Projétil como munição de arma de fogo', '## Projétil como munição de arma de fogo

O crime será aquele previsto no art. 15 da Lei nº 10.826/03, sendo o crime subsidiário e residual. A intenção do agente não é necessária para a prática de um crime mais grave.

### Conceitos
- **Princípio da especialidade**: Rege a aplicação das penas específicas para crimes previstos em lei
- **Crime subsidiário**: É o que só se aplica quando não há outro crime mais grave comum
- **Delito comum**: Pode ser praticado por qualquer pessoa, sem necessidade de intenção específica
- **Consumação formal**: O crime é considerado consumado desde o momento em que a ação é realizada
- **Perigo abstrato**: Independente da efetiva produção de resultado naturalístico, o crime pode ser considerado

### Referências legais
- Art. 15 da Lei nº 10.826/03

### Dicas de prova
- Análise do princípio da especialidade
- Distinção entre crimes subsidiários e comuns
- Consumação formal como requisito para o crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.233 (2)", "page_number": 233, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 15 da Lei nº 10.826/03"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:10:09.930854+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=233", "doc_key": "cfa2ae8c3dff6bd140b5c99958f83c6a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'dce44198d87cfecfa4fcec2d1f94b6c3032bcbf9dd0264e7ea6b23c67d89b3e8'),
  ('cpiuris2025::64ea378775b4bc0b8d1ade9e968ebe08', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Atentado contra a segurança de serviço de utilidade pública', '## Atentado contra a segurança de serviço de utilidade pública

O crime de atentar contra a segurança ou o funcionamento de serviço de água, luz, força ou calor, ou qualquer outro de utilidade pública acarreta pena de reclusão, de um a cinco anos, e multa.

### Conceitos
- **Atentado**: Atrapalhar, ofender, importunar ou colocar em risco
- **Utilidade Pública**: Serviços essenciais à sociedade
- **Pena de Reclusão**: Detenção de mais de um ano até 3 anos
- **Multa**: Sancionamento pecuniário

### Referências legais
- Art. 265 do CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre atentar e impedir o funcionamento de um serviço
- Importância da interpretação analógica no crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.234 (1)", "page_number": 234, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 265 do CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:10:37.417826+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=234", "doc_key": "64ea378775b4bc0b8d1ade9e968ebe08"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9a28372afa8c69abed1e3ea34a083bce16a69512458aa3ae9737dee5174bacd0'),
