Descreve os crimes contra a segurança dos meios de comunicação e transporte, além de outros serviços públicos.

### Conceitos
- **Incolumidade Pública**: A segurança e integridade do patrimônio público
- **Crimes contra a Incolumidade Pública**: Títulos que regulamentam os crimes contra a segurança dos meios de comunicação, transporte e outros serviços públicos

### Referências legais
- Art. 334 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de Incolumidade Pública e como ela se relaciona com os crimes contra a segurança dos meios de comunicação e transporte.
- Identifique os tipos específicos de crimes que são considerados crimes contra a Incolumidade Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.236", "page_number": 236, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 334 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T10:11:51.311474+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=236", "doc_key": "ff1b1e9b2f32f1a52807e163ee17e7bc"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2ade3b355e58adb7cc9b58abad94c37b6f11afc52877e454274e19dbe9c52c86'),
  ('cpiuris2025::fb41ac637bf5d2743122f931ab105847', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública: Crimes contra a Saúde Pública', '## Crimes contra a Incolumidade Pública: Crimes contra a Saúde Pública

O art. 267 estabelece o crime de epidemia, punido com reclusão de 10 a 15 anos, que causa doença infectocontagiosa nociva à saúde pública.

### Conceitos
- **Epidemia**: surto de uma doença transitório, atacando simultaneamente um número indeterminado de indivíduos
- **Germe patogênico**: organismo capaz de produzir moléstia infectocontagiosa
- **Propagação de doença**: difusão da doença humana
- **Moléstia infectocontagiosa**: doença que pode ser transmitida por contato direto ou indireto
- **Saúde pública**: preservação de condições saudáveis de subsistência e desenvolvimento da coletividade
- **Causar epidemia**: produzir, dar origem, propagar os microrganismos
- **Tentativa**: hipótese em que apenas uma pessoa é contaminada

### Referências legais
- Art. 267 da Lei nº 9.394/1996

### Dicas de prova
- Diferenciar entre epidemia e pandemia
- Entender a propagação de doença humana como o núcleo do tipo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.237", "page_number": 237, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 267 da Lei nº 9.394/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:12:29.135347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=237", "doc_key": "fb41ac637bf5d2743122f931ab105847"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8a6febb96f706bbaf192dcae16203c508d9bd23c0c6ad0ffe6243b3dd6c78f3b'),
  ('cpiuris2025::e73669787da7140c5211ca9f0a1cb434', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública e Saúde Pública', '## Crimes contra a Incolumidade Pública e Saúde Pública

Descreve o crime de reutilização de agulhas hipodérmicas em hospital, que caracteriza o delito em comento, tutelando a saúde pública.

### Conceitos
- **Crime contra a Incolumidade Pública**: Tutela a saúde e segurança da população
- **Saúde Pública**: Responsabilidade do Estado em garantir a saúde e bem-estar da população
- **Dolo**: A intenção de cometer o crime, prescindindo de finalidade específica
- **Consumação do Crime**: O momento em que há violação à determinação do Poder Público
- **Tentativa**: A ação preparatória para cometer o crime, sem resultado naturalístico

### Referências legais
- Art. 285 Código Penal
- Art. 258 Código Penal

### Jurisprudência
- ARE 1418846/RS
- Informativo STF 1088

### Dicas de prova
- Diferenciar entre crime de perigo abstrato e crime de perigo concreto
