  ('cpiuris2025::688ea882f470467f9f609653c3ce8cb6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Omissão de notificação de doença', '## Omissão de notificação de doença

A omissão de notificar doenças compulsórias é crime, punido com detenção e multa, sendo crime próprio e omissivo.

### Conceitos
- **Crime Omissivo**: Figura penal que se caracteriza pela omissão de ato previsto em lei
- **Crime Público**: Ação penal que pode ser iniciada por qualquer pessoa, sem a necessidade de autorização prévia
- **Sujeito Passivo**: Coletividade que sofre o ato ilícito
- **Verbo Núcleo**: Parte do tipo penal que caracteriza a figura consumada

### Referências legais
- Art. 267 do Código de Processo Penal
- Art. 258 do Código de Processo Penal

### Dicas de prova
- Distinção entre crime omissivo e crime concreto
- Importância da notificação compulsória em saúde pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.238 (2)", "page_number": 238, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 267 do Código de Processo Penal", "Art. 258 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:13:36.479108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=238", "doc_key": "688ea882f470467f9f609653c3ce8cb6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'df1ded210a809f5cc1dafbfca030fe8271397a496e9ec9027cb4c0b49973d813'),
  ('cpiuris2025::cc4c2012767f6a34cecf78cd76210d64', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública e Saúde Pública', '## Crimes contra a Incolumidade Pública e Saúde Pública

Descreve o crime de envenenamento de água potável ou substância alimentícia/medicinal, caracterizado por perigo comum e potencialidade lesiva maior.

### Conceitos
- **Crime contra a Incolumidade Pública**: Ato que coloca em risco a segurança e o bem-estar da população.
- **Saúde Pública**: Estado de saúde coletiva, considerando a prevenção e proteção da população contra doenças.
- **Perigo Presumido ou Abstrato**: Hipótese em que o crime é caracterizado por perigo presumido ou abstrato, sem necessidade de provas concretas.
- **Potencialidade Lesiva**: Capacidade do crime de causar danos graves e irreversíveis à saúde e segurança da população.

### Referências legais
- Art. 285 do CP
- Art. 258 do CP
- Lei n.º 6.259/1975
- Portaria n.º 1.100/1996

### Dicas de prova
- Diferenciar entre crime de perigo comum e perigo presumido ou abstrato.
- Entender a noção de potencialidade lesiva e sua importância na classificação do crime.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.239 (1)", "page_number": 239, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 285 do CP", "Art. 258 do CP", "Lei n.º 6.259/1975", "Portaria n.º 1.100/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:14:12.467398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=239", "doc_key": "cc4c2012767f6a34cecf78cd76210d64"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '365878edb55a6cdf41af186c281ccae47e0bf6caf89f63395c4be45291cac2b7'),
  ('cpiuris2025::1c8e15428c20a59fd59d855409e1f5bb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime de Perigo Abstrato', '## Crime de Perigo Abstrato

O crime de perigo abstrato não exige a demonstração do efetivo perigo, sendo um tipo penal que se aplica a situações em que há risco de dano à pessoa, mesmo sem certeza do resultado. Exemplo: envenenamento de água potável.

### Conceitos
- **Crime de Perigo Abstrato**: Tipo penal que não exige demonstração do efetivo perigo
- **Risco de Dano**: Situação em que há ameaça à segurança da pessoa
- **Dano à Pessoa**: Lesão ou perigo à saúde, integridade física ou moral de uma pessoa

### Referências legais
- Art. 132 do CP

### Dicas de prova
- Distinção entre crime de perigo abstrato e crime de perigo concreto
- Exemplo de situação em que se aplica o crime de perigo abstrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.239 (2)", "page_number": 239, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 132 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:14:45.827613+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=239", "doc_key": "1c8e15428c20a59fd59d855409e1f5bb"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'fb58a2e577c5046a65da990f3ae6cff32ad2da7d0b1a6c234140d4d667762577'),
  ('cpiuris2025::e15d335f1b6c397998a9121f4e046124', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública e a Saúde Pública', '## Crimes contra a Incolumidade Pública e a Saúde Pública

Regra sobre o crime impossível de envenenamento de água ou substância alimentícia medicinal, considerando a impropriedade absoluta do objeto e a falta de provocação de dano.

### Conceitos
- **Crime Impossível**: O caso em que não é possível cometer o crime devido à natureza da substância ou água
- **Imprudência**: Negligência ou falta de cuidado que leva a um resultado prejudicial
- **Lei Especial**: Lei que abrange crimes específicos, como o crime ambiental
- **Causa de Aumento de Pena**: Fato que aumenta a pena prevista para um crime
- **Pena de Reclusão**: Pena privativa da liberdade

### Referências legais
- Art. 285
- Art. 258
- Lei nº 9.099/1995
- Lei nº 9.605/98

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre crime impossível e crime culposo
- Diferença entre envenenamento de água e poluição de água potável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.240 (1)", "page_number": 240, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 285", "Art. 258", "Lei nº 9.099/1995", "Lei nº 9.605/98"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T10:15:18.797543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=240", "doc_key": "e15d335f1b6c397998a9121f4e046124"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '66267eec77b33782b5da6fe56984b4cb638aa0539adf90e9bbc77ed0e77cc074'),
  ('cpiuris2025::764b90417d2554380c5a48024732cbce', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Poluição Ambiental', '## Poluição Ambiental

A Lei nº 9.605/98 estabelece que a água poluída ou corrompida, mesmo sem interrupção, pode ser considerada imprópria para consumo ou nociva à saúde, e incide na figura do art. 271 do CP.

### Conceitos
- **Poluição Ambiental**: Ação que prejudica o meio ambiente
- **Dano ao Meio Ambiente**: Prejuízo causado à natureza ou aos ecossistemas
- **Água Potável**: Água que é segura para consumo humano
- **Interrupção**: Falta de continuidade em uma ação ou processo
- **Inépcia da Denúncia**: Omissão ou falta de cumprimento de requisitos legais

### Referências legais
- Art. 271 do CP
- Lei nº 9.605/98

### Jurisprudência
- HC 178.423/GO
- Súmula do STJ

### Dicas de prova
- Entenda a noção de poluição ambiental e seus efeitos
- Conheça a Lei nº 9.605/98 e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.240 (2)", "page_number": 240, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 271 do CP", "Lei nº 9.605/98"], "jurisprudence": ["HC 178.423/GO", "Súmula do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T10:15:47.442457+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=240", "doc_key": "764b90417d2554380c5a48024732cbce"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '827ab7b33e0da5a4ff952abd8a588c084808fb4ec9742cfd8577d8ae86a7e91d'),
  ('cpiuris2025::d9c3c697d850ec0f38a986a3ebd04af7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Materialidade no Crime de Poluição Ambiental', '## Materialidade no Crime de Poluição Ambiental

O crime de poluição ambiental exige que a conduta torne a substância ou produto alimentício nocivo à saúde ou reduza o seu valor nutritivo, sendo imprescindível o exame pericial.

### Conceitos
- **Materialidade**: A prova da materialidade do crime, exigindo-se o exame pericial para demonstrar a perda dos nutrientes ou a nocividade à saúde.
- **Perigo Concreto**: O crime é de perigo concreto, sendo necessário demonstrar, por prova técnica, que houve a perda dos nutrientes ou a nocividade à saúde.

### Referências legais
- Art. 54 da Lei nº 9.605/98
- Art. 271 do Código Penal

### Jurisprudência
- HC 178.423/GO
- Súmula N STF

### Dicas de prova
- Pergunte sobre a materialidade e o perigo concreto no crime de poluição ambiental.
- Entenda que o exame pericial é imprescindível para demonstrar a perda dos nutrientes ou a nocividade à saúde.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.241 (1)", "page_number": 241, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 54 da Lei nº 9.605/98", "Art. 271 do Código Penal"], "jurisprudence": ["HC 178.423/GO", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T10:16:29.431788+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=241", "doc_key": "d9c3c697d850ec0f38a986a3ebd04af7"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'bec00ed0de4e360a12e53319c4f62a38953d4e61022a00d7b0d155bfe9b0ab60'),
  ('cpiuris2025::19018722a8fc551414490b3ac8d8ea15', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsificação de produtos alimentícios', '## Falsificação de produtos alimentícios

A doutrina aponta violação ao princípio da proporcionalidade, pois se punem condutas distintas com gravidades diversas. O crime é formal e admite tentativa.

### Conceitos
- **Princípio da Proporcionalidade**: Requer que a pena seja a mais adequada à gravidade do crime
- **Falsificação**: Modo de se tornar nocivo ou prejudicial, reduzindo o valor nutritivo
- **Crime Formal**: Prescinde de resultado naturalístico para a consumação
- **Tentativa**: É possível, desde que haja a intenção de cometer o crime

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferença entre condutas distintas e gravidades diversas
- Importância do princípio da proporcionalidade no direito penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.241 (2)", "page_number": 241, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:16:53.043509+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=241", "doc_key": "19018722a8fc551414490b3ac8d8ea15"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '254ca296dba22921bbafe8d6b6d7be1951d219f45c7ecb894200182d7119ff08'),
  ('cpiuris2025::5256df91fd9a174f78bb2c28f3574608', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsificação, Corrupção, Adulteração ou Alteração de Produto Destinado a Fins Terapêuticos ou Medicinais', '## Falsificação, Corrupção, Adulteração ou Alteração de Produto Destinado a Fins Terapêuticos ou Medicinais

O crime de falsificar, corromper, adulterar ou alterar produto destinado a fins terapêuticos ou medicinais é punido com reclusão de 10 a 15 anos e multa. É um crime hediondo, exceto na modalidade culposa, que também aplicam os rigores da Lei nº 8.072/1990.

### Conceitos
- **Falsificação**: Ação de tornar falso um documento ou produto
- **Corrupção**: Mudança ilegal de substância em um produto
- **Adulteração**: Mudança ilegal de substância em um produto sem alterar sua natureza
- **Alteração**: Mudança ilegal de características de um produto
- **Crime Hediondo**: Tipo de crime que tem como objetivo proteger a incolumidade da população
- **Lei nº 8.072/1990**: Lei brasileira que estabelece os rigores para crimes hediondos

### Referências legais
- Art. 273 do CP
- Art. 285 do CP

### Dicas de prova
- Entenda a distinção entre falsificação, corrupção, adulteração e alteração de produtos.
- Conheça as características do crime hediondo e como ele é aplicado na legislação brasileira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.242 (1)", "page_number": 242, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 273 do CP", "Art. 285 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:17:31.327329+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=242", "doc_key": "5256df91fd9a174f78bb2c28f3574608"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '01517d8a9e2c49c2e7c535f667b23b572cb87071343d49a8dad90770f0aa951f'),
  ('cpiuris2025::cf8286c512c060445365e48729444696', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Princípio da Proporcionalidade e Tipologia do Crime', '## Princípio da Proporcionalidade e Tipologia do Crime

O crime de falsificação de cosméticos e saneantes é caracterizado pelo princípio da proporcionalidade, com tipos mistos alternativos e verbos nucleares ''falsificar'', ''corromper'', ''adulterar'' ou ''alterar''. O crime é comum e vago, não exigindo características especiais do sujeito ativo.

### Conceitos
- **Princípio da Proporcionalidade**: Regra que exige que a gravidade do dano seja proporcional à gravidade da infração
- **Tipologia do Crime**: Classificação dos tipos penais em categorias ou núcleos
- **Verbos Nucleares**: Palavras-chave que definem a natureza da infração

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de princípio da proporcionalidade e como se aplica ao crime em questão
