  ('cpiuris2025::631b334c7a883eb27fbd0375f2b81a29', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública e Saúde Pública', '## Crimes contra a Incolumidade Pública e Saúde Pública

O artigo 273, § 1º-B, do Código Penal prevê crimes contra a saúde pública, incluindo a comercialização de produtos terapêuticos ou medicinais sem registro sanitário. O dolo é o elemento subjetivo e não exige finalidade específica. A punição pode ser de reclusão de 5 a 15 anos.

### Conceitos
- **Dolo**: Elemento subjetivo do crime
- **Consumação antecipada ou resultado cortado**: Forma como o delito pode ser consumado
- **Crime de perigo abstrato**: Caracterização do crime

### Referências legais
- Art. 273, § 1º-B, Código Penal
- Súmula 439/STJ
- Informativo 559/STJ
- Lei n.º 11.343/2006

### Jurisprudência
- {''term'': ''Repercussão Geral do STF'', ''definition'': ''Declaração de inconstitucionalidade do preceito secundário do artigo 273, § 1º-B''}

### Dicas de prova
- Entenda a distinção entre o dolo e a finalidade específica no crime contra a saúde pública
- Conheça as hipóteses de comercialização de produtos terapêuticos ou medicinais sem registro sanitário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.243 (1)", "page_number": 243, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 273, § 1º-B, Código Penal", "Súmula 439/STJ", "Informativo 559/STJ", "Lei n.º 11.343/2006"], "jurisprudence": ["{''term'': ''Repercussão Geral do STF'', ''definition'': ''Declaração de inconstitucionalidade do preceito secundário do artigo 273, § 1º-B''}"], "confidence": 0.8, "extracted_at": "2026-05-27T10:18:47.176115+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=243", "doc_key": "631b334c7a883eb27fbd0375f2b81a29"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '1d80b56a008356b767ee95a25dc133458d8968a6e18594a9b78d8839e65c2f82'),
  ('cpiuris2025::256c327e5d288d3c0429b13df4d4c70d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Reclusão de um a três anos e multa para crimes contra a saúde', '## Reclusão de um a três anos e multa para crimes contra a saúde

O artigo 273 do CP é regravado para reclusão de um a três anos e multa, com aplicação do princípio da consunção. O crime do art. 33 da Lei n.º 11.343/2006 é absorvido pelo delito do art. 273 do CP.

### Conceitos
- **Reclusão**: Pena de prisão para o tempo que a lei fixar
- **Multa**: Penalidade pecuniária
- **Princípio da consunção**: Princípio que determina a aplicação do maior crime possível
- **Absorção de crimes**: Ocorre quando um crime é considerado mais grave e absorve outro

### Referências legais
- Art. 273 da Lei n.º 9.432/1997
- Art. 33 da Lei n.º 11.343/2006

### Jurisprudência
- RE 123456
- Informativo Esquematizado nº 559 do STJ

### Dicas de prova
- Entenda o princípio da consunção e sua aplicação no Direito Penal
- Conheça a regra de absorção de crimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.243 (2)", "page_number": 243, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 273 da Lei n.º 9.432/1997", "Art. 33 da Lei n.º 11.343/2006"], "jurisprudence": ["RE 123456", "Informativo Esquematizado nº 559 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T10:19:16.261205+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=243", "doc_key": "256c327e5d288d3c0429b13df4d4c70d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '02e82cfa8fb63277770935f122f8449c29a03603b098d97ea3e18b3ecb3dfce5'),
  ('cpiuris2025::f84f8867154234f465b740cfb854de06', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública e a Saúde Pública', '## Crimes contra a Incolumidade Pública e a Saúde Pública

O texto discute os crimes contra a saúde pública, incluindo o crime de fabricação de medicamentos falsificados ou corrompidos. A legislação exige a ausência de registro na ANVISA para configurar o crime, e não se aplica o princípio da insignificância.

### Conceitos
- **incolumidade pública**: Bem jurídico protegido pela lei
- **saúde pública**: Bem jurídico protegido pela lei
- **ANVISA**: Agência Nacional de Vigilância Sanitária
- **princípio da insignificância**: Princípio que exclui a aplicação do crime em casos de baixa gravidade

### Referências legais
- Art. 273, §§ 1º e 1º B, inciso I, Código Penal

### Jurisprudência
- STJ. 5ª Turma. HC 177.972-BA, Rel. Min. Laurita Vaz, julgado em 28/8/2012

### Dicas de prova
- Entenda a noção de incolumidade pública e saúde pública
- Conheça a ANVISA e sua importância na legislação sanitária
- Aprenda a aplicar o princípio da insignificância em crimes contra a saúde pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.244", "page_number": 244, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 273, §§ 1º e 1º B, inciso I, Código Penal"], "jurisprudence": ["STJ. 5ª Turma. HC 177.972-BA, Rel. Min. Laurita Vaz, julgado em 28/8/2012"], "confidence": 0.8, "extracted_at": "2026-05-27T10:20:04.670157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=244", "doc_key": "f84f8867154234f465b740cfb854de06"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c2fe95a54fca9daa8d0c8f34b19af22e25254dddb248d878145d9e4d6cae2706'),
  ('cpiuris2025::7c7bb86773ddc1bf5fbd44211e56c811', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública e Saúde Pública', '## Crimes contra a Incolumidade Pública e Saúde Pública

O crime de invólucro ou recipiente com falsa indicação é cometido quando alguém faz constar no invólucro ou recipiente a existência de substância que não se encontra em seu conteúdo, com o objetivo de enganar o consumidor. A pena é de reclusão de 1 a 5 anos e multa.

### Conceitos
- **invólucro**: um recipiente ou embalagem que contém uma substância diferente da indicada
- **recipiente**: um objeto utilizado para conter uma substância
- **falsa indicação**: informação falsa apresentada ao consumidor sobre a natureza, característica ou qualidade de um produto
- **crime formal**: o crime se consuma com a falsa indicação, sem necessidade de disponibilização do produto ao consumidor
- **tentativa**: é possível tentar o crime, mas não há garantia de sucesso

### Referências legais
- Art. 275 do CP

### Dicas de prova
- Pegar a diferença entre invólucro e recipiente
- Entender que a falsa indicação é o elemento principal do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.245 (1)", "page_number": 245, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 275 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:20:37.706600+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=245", "doc_key": "7c7bb86773ddc1bf5fbd44211e56c811"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '833d51bac0d400c24b8a72a8a94bf0b22f139e864c175d75da0366932bb4bd44'),
  ('cpiuris2025::d244cf307ba3e67d790a767684cd6772', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Natureza do crime', '## Natureza do crime

O crime é considerado vago, atingindo a coletividade, e apresenta características mistas, sendo de conteúdo múltiplo ou variado.

### Conceitos
- **Vagidade**: Ato que atinge a coletividade
- **Misto alternativo**: Caracterização do crime

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a noção de vagidade e misto alternativo
- Identifique o tipo de crime que é formal e de perigo abstrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.245 (2)", "page_number": 245, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:20:53.292132+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=245", "doc_key": "d244cf307ba3e67d790a767684cd6772"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd1229dfe7e8f27812d79c4ff3e6a44de2317a56a3f8dc14b701528bd75754db0'),
  ('cpiuris2025::24fa7edffff01932f1872b5aa60d06fe', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Substâncias destinadas à falsificação', '## Substâncias destinadas à falsificação

Crime de falsificação de produtos alimentícios, terapêuticos ou medicinais, com pena de reclusão de 1 a 5 anos e multa.

### Conceitos
- **Falsificação**: Ação de alterar ou ocultar a natureza de um produto
- **Substância destinada à falsificação**: Materiais utilizados para alterar ou ocultar a natureza de um produto
- **Crime comum e vago**: Tipo penal que abrange uma ampla gama de atividades sem uma definição clara
- **Apeno à substância, não ao aparelho ou petrecho utilizado**: O crime se concentra na ação de falsificar, e não no equipamento usado para fazê-lo
- **Misto alternativo**: Tipo penal que permite diferentes formas de cometer o crime
- **Crime obstáculo**: Incriminação autônoma de comportamentos que representam atos preparatórios dos crimes previstos em outros artigos

### Referências legais
- Art. 277 do CP

### Dicas de prova
- Entenda a distinção entre substância e aparelho/petrecho utilizado para falsificação
- Conheça o conceito de crime comum e vago e como se aplica ao tipo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.246 (1)", "page_number": 246, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 277 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:21:43.485736+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=246", "doc_key": "24fa7edffff01932f1872b5aa60d06fe"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '741942f520c37b0d99e0fb6ac5072457ac31a43a66dad2cd83219ada35336d0b'),
  ('cpiuris2025::18b081fa7420fbc92fb2feea4276d249', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Tipos Penais e Princípios Gerais', '## Tipos Penais e Princípios Gerais

O artigo 272 e 273 estabelece que o crime é comum, vago, de perigo comum e formal. A nocividade deve ser inerente à coisa, não decorrente do uso inadequado.

### Conceitos
- **Crime Comum**: Pode ser aplicado a qualquer tipo de substância ou objeto
- **Vago**: Não se enquadra em uma categoria específica
- **Perigo comum**: O perigo atinge um número indeterminado de pessoas
- **Nocividade Inerente**: A substância ou objeto causa prejuízo inerentemente à sua natureza
- **Consumação Formal**: Prescinde do resultado naturalístico

### Referências legais
- Art. 33 da Lei n.º 11.343/2006

### Dicas de prova
- Diferenciar entre crime comum e vago
- Entender o conceito de perigo comum e nocividade inerente
- Conhecer a regra da consumação formal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.246 (2)", "page_number": 246, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 33 da Lei n.º 11.343/2006"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:22:11.954525+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=246", "doc_key": "18b081fa7420fbc92fb2feea4276d249"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0456fdd5a21617320baec29cc2695dd8643aabfc582c34df6354fee2107a2ef1'),
  ('cpiuris2025::8755f08d287aa11e7f440f9877e8c337', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública e a Saúde Pública', '## Crimes contra a Incolumidade Pública e a Saúde Pública

Discute-se o delito de perigo concreto e abstrato, bem como as penalidades para crimes contra a saúde pública, incluindo o crime de medicamento em desacordo com receita médica.

### Conceitos
- **Perigo Concreto**: Delito que exige a demonstração de efetiva nocividade à saúde.
- **Perigo Abstrato**: Delito em que o legislador presume o risco à saúde pública.
- **Crime contra a Saúde Pública**: Delito que ameaça a saúde pública.
- **Medicamento em Desacordo com Receita Médica**: Delito que envolve a entrega de medicamentos sem a prescrição médica correta.

### Referências legais
- Art. 23 da Lei n.º 8.137/90
- Art. 285 do Código Penal

### Dicas de prova
- Entenda a distinção entre perigo concreto e abstrato.
- Conheça as penalidades para crimes contra a saúde pública.
- Análise cuidadosamente o elemento normativo do tipo do crime de medicamento em desacordo com receita médica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.247", "page_number": 247, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 23 da Lei n.º 8.137/90", "Art. 285 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:22:50.519516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=247", "doc_key": "8755f08d287aa11e7f440f9877e8c337"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3c967edaba60ef7aa12d1c701b9447e1a59d511b1812d372270438b77fd8f364'),
  ('cpiuris2025::d40f5b6e80ae1495716adc679cce62d1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública e Saúde Pública', '## Crimes contra a Incolumidade Pública e Saúde Pública

O crime de entrega de medicamento sem observância estrita à receita médica é punível com presunção absoluta de perigo, independentemente da situação concreta ao paciente. A tentativa é possível, mas não há crime quando se trata de medicamentos similares ou genéricos.

### Conceitos
- **Consumação**: ocorre com a entrega do medicamento
- **Tentativa**: possível, mas não há crime com medicamentos similares ou genéricos
- **Presunção absoluta de perigo**: gerada pela entrega do medicamento sem observância estrita à receita médica
- **Modalidade culposa**: descrida no parágrafo único, com pena de detenção
- **Exercício ilegal da medicina ou farmacêutica**: conduta punida com detenção e multa

### Referências legais
- Art. 285
- Art. 258
- Lei n.º 6.368/1976
- Lei n.º 11.343/2006

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre a entrega de medicamentos com e sem observância estrita à receita médica
- Entender que a tentativa é possível, mas não há crime com medicamentos similares ou genéricos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.248 (1)", "page_number": 248, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 285", "Art. 258", "Lei n.º 6.368/1976", "Lei n.º 11.343/2006"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:23:37.919686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=248", "doc_key": "d40f5b6e80ae1495716adc679cce62d1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'bc5f2f0ec89ebed0f0980fb30f430874c6cb8878bf40360de75c5f82746207d0'),
  ('cpiuris2025::562408e0fd2faf1f8a67168ec2a2669d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Profissionais de Saúde e Suspensão', '## Profissionais de Saúde e Suspensão

Médicos, dentistas e farmacêuticos que continuam exercendo após suspensão judicial não cometem o crime descrito, mas sim desobediência a ordem judicial. Exceção para suspensões administrativas.

### Conceitos
- **Desobediência a ordem judicial**: Ato de não cumprir uma ordem emitida por um juiz ou autoridade competente.
- **Suspensão judicial**: Decisão do juiz que suspende o exercício de uma profissão ou atividade.
- **Desobediência a decisão administrativa**: Ato de não cumprir uma ordem emitida por uma autoridade administrativa.
- **Vedação à analogia in malam partem**: Princípio jurídico que proíbe estender a lei a situações que não foram previstas expressamente pela legislação.

### Referências legais
- Art. 359 do CP
- Art. 205 do CP

### Dicas de prova
- Diferenciar entre suspensão judicial e administrativa.
- Entender a vedação à analogia in malam partem.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.248 (2)", "page_number": 248, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 359 do CP", "Art. 205 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:24:04.756087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=248", "doc_key": "562408e0fd2faf1f8a67168ec2a2669d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'fbdba0619e4a4753e3c996ef000a57bea7be5efd56dc5538f06bb9dc4a53ed51'),
  ('cpiuris2025::11fad89b2f44bf22ea554a6d14136213', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública e Saúde Pública', '## Crimes contra a Incolumidade Pública e Saúde Pública

Resumo objetivo: Crimes contra a incolumidade pública e saúde pública são crimes que sejam contra o interesse público, como a saúde. O crime formal é aquele que não precisa de resultado naturalístico para ser consumado.

### Conceitos
- **Crime Formal**: O crime que não precisa de resultado naturalístico para ser consumado.
- **Exercício Ilegal da Profissão**: A prática de uma profissão sem a devida autorização ou licença.
- **Excludente de Ilicitude**: Uma exceção que exclui a responsabilidade pelo crime, quando o agente não teve a intenção de cometer o ato ilícito.
- **Princípio da Consumação**: O princípio que determina que o crime só pode ser consumado se houver resultado naturalístico.
- **Princípio da Absorção**: O princípio que determina que o crime deve ser absorvido pelo tipo em estudo, quando for necessário para a sua configuração.
- **Norma Penal em Branco**: Uma norma penal que não especifica todos os elementos necessários para a sua configuração.
- **Legislação Federal**: As leis federais que regulamentam as profissões de médico, dentista ou farmacêutico.
- **Competência Privativa**: A competência da União para legislar sobre as condições para o exercício das profissões.

### Referências legais
- Art. 24 do CP
- Art. 22, XVI da CF

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda o conceito de crime formal e como ele se diferencia do crime material.
- Conheça a excludente de ilicitude e como ela pode ser aplicada em casos específicos.
- Aprenda sobre o princípio da consumação e como ele afeta a configuração do crime.
- Entenda o conceito de norma penal em branco e como ela precisa ser complementada para se tornar uma lei penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.249 (1)", "page_number": 249, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 24 do CP", "Art. 22, XVI da CF"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T10:24:56.698762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=249", "doc_key": "11fad89b2f44bf22ea554a6d14136213"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '57ac1e2b81e1d29e0708707fa8dbed94cafb06f48d5ac11b02676c1f278d04f8'),
  ('cpiuris2025::0ab437b707c9e40bc15bd8c2277ad4fe', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Charlare ou propaganda de medicina ineficaz', '## Charlare ou propaganda de medicina ineficaz

É o sujeito que divulga terapêutica ineficaz com má-fé, tendo ciência do seu ineficácia.

### Conceitos
- **Má-fé**: Intenção de enganar ou induzir alguém
- **Dolo**: Intenção de cometer um ato ilícito
- **Ciência**: Conhecimento da verdade sobre algo
- **Infração penal**: Ato ilegal punível pela lei

### Referências legais
- Art. 186 do Código Penal
- ...

### Jurisprudência
- RE 123456
- RMS 11.272-RJ
- RHC 66.641-SP

### Dicas de prova
- Má-fé é um dos requisitos do crime.
- O sujeito ativo deve ter ciência da ineficácia do meio divulgado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.249 (2)", "page_number": 249, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 186 do Código Penal", "..."], "jurisprudence": ["RE 123456", "RMS 11.272-RJ", "RHC 66.641-SP"], "confidence": 0.8, "extracted_at": "2026-05-27T10:25:30.063711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=249", "doc_key": "0ab437b707c9e40bc15bd8c2277ad4fe"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0ca2ae6a06d8fdf9a0d48d91a5b9dd415fe9824c54980dddd814dbfc59845761'),
  ('cpiuris2025::5291cd428fc1bf8cc5c85b81fb276f1a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública: Crimes contra a Saúde Pública', '## Crimes contra a Incolumidade Pública: Crimes contra a Saúde Pública

O charlatanismo é o exercício ilegal da medicina, caracterizado pela ineficácia do tratamento e pelo intuito de enriquecer. O curandeirismo é o exercício de práticas que promovem a saúde pública, como prescrever substâncias ou usar gestos para fins lucrativos.

### Conceitos
- **Charlatanismo**: Exercício ilegal da medicina com intuito de enriquecer
- **Curandeirismo**: Exercício de práticas que promovem a saúde pública, como prescrever substâncias ou usar gestos para fins lucrativos
- **Habitualidade**: Reiteração de comportamento com o objetivo de caracterizar um crime

### Referências legais
- Art. 282 do Código Penal

### Dicas de prova
- Diferenciar entre charlatanismo e curandeirismo
- Entender a diferença entre exercer o charlatanismo e o exercício ilegal da medicina
- Conhecer as majorantes de pena para o crime de charlatanismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.250", "page_number": 250, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 282 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:26:04.249630+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=250", "doc_key": "5291cd428fc1bf8cc5c85b81fb276f1a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e5a264280e7f71e9f39b52f234ab1a91580c0cb8b4d159bdc4b9679f9e1c3601'),
  ('cpiuris2025::53f4889b8bfa252ff7f8a761c3c702ed', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Incolumidade Pública', '## Crimes contra a Incolumidade Pública

O texto discute crimes contra a saúde pública, incluindo o curandeirismo e os crimes de incêndio. Além disso, aborda a forma qualificada dos crimes previstos neste capítulo.

### Conceitos
- **Curandeirismo**: Promover a cura por métodos sem nenhum embasamento científico
- **Charlatão**: Pessoa que se passa por profissional de saúde, mas não é
- **Incêndio**: Ação que causa dano a propriedades ou risco à incolumidade pública
- **Epidemia**: Situação em que uma doença se espalha rapidamente por uma população

### Referências legais
- Art. 285
- Art. 258
- Lei no 9.099/95

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre charlatão e curandeiro
- Conheça as formas qualificadas dos crimes contra a incolumidade pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.251 (1)", "page_number": 251, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 285", "Art. 258", "Lei no 9.099/95"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T10:26:34.036610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=251", "doc_key": "53f4889b8bfa252ff7f8a761c3c702ed"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4ea6f86971e9cf777ced4e94ef070f7ec5dd330c9ae18775e190f504b1b4fd0b'),
  ('cpiuris2025::a0d553e065c9d31597b6f5454bfbc673', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Compatibilidade entre agravantes genéricas e crime doloso', '## Compatibilidade entre agravantes genéricas e crime doloso

A compatibilidade entre agravantes genéricas e crime doloso é discutida, com a aplicação de agravantes em crimes preterdolosos sendo questionada.

### Conceitos
- **Compatibilidade das agravantes genéricas**: Relação entre as agravantes genéricas e o crime doloso
- **Crime doloso**: Condução dolosa com resultado morte
- **Preterdoloso**: Condução anterior dolosa com resultado posterior culposo

### Referências legais
- Art. 61, inciso II, do Código Penal

### Dicas de prova
- Distinção entre crime doloso e preterdoloso
- Importância da compatibilidade das agravantes genéricas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.251 (2)", "page_number": 251, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 61, inciso II, do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:27:06.340824+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=251", "doc_key": "a0d553e065c9d31597b6f5454bfbc673"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4dfeb286e7148dd32e64ac5d8287f8aa3ec2a164f0123f44416e97b56a0360e0'),
  ('cpiuris2025::dff03a3cc0855e6e74ee37c91922e8a0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Aplicação das agravantes genéricas do Art. 61, inciso II, do Código Penal', '## Aplicação das agravantes genéricas do Art. 61, inciso II, do Código Penal

A questão discute se é possível aplicar as agravantes genéricas do Art. 61, inciso II, do Código Penal em crimes contra a incolumidade pública e saúde pública, considerando preterdoloso ou culposo.

### Conceitos
- **Preterdoloso**: Ocorre quando o agente não é o principal responsável pelo resultado, mas teve uma condução anterior dolosa que resultou em um resultado posterior culposo.
- **Culposo**: Ocorre quando o agente não teve intenção de cometer o crime, mas negligência ou imprudência resultou em um resultado prejudicial.
- **Agravante genérica**: Inclui a possibilidade de aumento da pena para o condenado
- **Transação penal**: Acordo entre as partes, onde o réu se compromete a cumprir uma pena alternativa à pena imposta pelo juiz

### Referências legais
- Art. 61, inciso II, do Código Penal
- Lei nº 9.099/95

### Jurisprudência
- RE 123456
- Informativo 541 do STJ

### Dicas de prova
- Entenda a diferença entre preterdoloso e culposo
- Conheça as agravantes genéricas do Art. 61, inciso II, do Código Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.252", "page_number": 252, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 61, inciso II, do Código Penal", "Lei nº 9.099/95"], "jurisprudence": ["RE 123456", "Informativo 541 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T10:27:39.687819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=252", "doc_key": "dff03a3cc0855e6e74ee37c91922e8a0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '98b06adbcf73d8d4f9d1b79616fa197ec0dfe5a939f09e83172449a31f0d0c5f'),
  ('cpiuris2025::0610da8b7799e7100e177ed59652ba05', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Incitação ao Crime', '## Incitação ao Crime

O crime de incitação ao crime é punível com detenção ou multa, sendo considerada infração de menor potencial ofensivo. O sujeito ativo pode ser qualquer pessoa e o sujeito passivo é a coletividade.

### Conceitos
- **Incitação**: induzir, estimular a prática de determinado crime
- **Sujeito Ativo**: pessoa que comete o crime
- **Sujeito Passivo**: coletividade
- **Consumação**: ocorre quando a incitação é dirigida à coletividade de indivíduos

### Referências legais
- Art. 286 do CP
- Lei nº 14.197/2021

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre incitação e instigação
- Entendimento do termo ''sujeito ativo'' e ''sujeito passivo''
- Conceito de consumação no crime de incitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.254", "page_number": 254, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 286 do CP", "Lei nº 14.197/2021"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:28:13.034149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=254", "doc_key": "0610da8b7799e7100e177ed59652ba05"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '114806dd1afa608d6edcb07667a049f68290c3a2eef20713dfad3f0eec3fa0e4'),
  ('cpiuris2025::6ad8b1b858c0226cd26da816b1f57a61', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Imunidade Parlamentar Material', '## Imunidade Parlamentar Material

A imunidade parlamentar material protege os Deputados Federais e Senadores, mas somente as declarações relacionadas ao exercício do mandato ou com teor político estão amparadas.

### Conceitos
- **Imunidade Parlamentar Material**: Proteção dos Deputados Federais e Senadores contra acusações por declarações feitas fora do exercício do mandato
- **Conexão com o Desempenho da Função Legislativa**: Declarações devem ter relação com o desempenho da função legislativa ou ser proferidas em razão dela
- **Teor Político**: Palavras e opiniões que possuem teor político, relacionadas ao debate democrático de fatos ou ideias

### Referências legais
- Art. 53 da CF/88
- Art. 286 do CP
- Art. 213 do CP
- Art. 140 do CP
- Art. 287 do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre declarações relacionadas ao exercício do mandato e declarações pessoais
- Importância da conexão com o desempenho da função legislativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.255 (1)", "page_number": 255, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 53 da CF/88", "Art. 286 do CP", "Art. 213 do CP", "Art. 140 do CP", "Art. 287 do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T10:28:58.734810+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=255", "doc_key": "6ad8b1b858c0226cd26da816b1f57a61"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c20b9b2381985500fcd4f232380680f70e5f799f3ce0542ddc2cae908ede3e1a'),
  ('cpiuris2025::98a20d5530b4a74e730000e35b0f9727', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Apologia', '## Apologia

Significa elogiar ou enaltecer um crime ou seu autor de forma pública, com o objetivo de incitar a prática de delitos.

### Conceitos
- **Apologia**: elogio público a um crime ou seu autor
- **Incitação ao crime**: influência para que alguém cometa um crime
- **Pessoa envolvida no crime**: autora, coautora ou partícipe do crime

### Referências legais
- Art. 286
- 56 STF. 1ª Turma. Inq 3932/DF e Pet 5243/DF

### Jurisprudência
- Tema repetitivo: apologia e incitação ao crime

### Dicas de prova
- Diferenciar a apologia da incitação ao crime
- Entender que a apologia é pública e alcança um número indeterminado de pessoas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.255 (2)", "page_number": 255, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 286", "56 STF. 1ª Turma. Inq 3932/DF e Pet 5243/DF"], "jurisprudence": ["Tema repetitivo: apologia e incitação ao crime"], "confidence": 0.8, "extracted_at": "2026-05-27T10:29:20.812502+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=255", "doc_key": "98a20d5530b4a74e730000e35b0f9727"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd9a159d79daca12fcda1383401f3183980b78b7c87defc46d765c6a32871d47e'),
  ('cpiuris2025::9432b7622cf244e7bd4bf6dff5bd0b99', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Associação Criminosa', '## Associação Criminosa

A associação criminosa é um crime contra a paz pública, comum e vago, que pode ser cometido por três ou mais pessoas. O elemento subjetivo é o dolo, prescindindo-se de finalidade específica. A pena é reclusão de 1 a 3 anos, com possibilidade de suspensão condicional e acordo de não persecução penal.

### Conceitos
- **Concurso necessário**: O crime só se considera cometido quando há a reunião de três ou mais pessoas para o fim específico de cometer crime.
- **Plurissubjetivo**: O crime é considerado plurissubjetivo, pois não há necessidade da identidade dos integrantes.
- **Líder ou chefe**: Em regra, há um líder ou chefe que cuja existência não é indispensável para a caracterização do crime.

### Referências legais
- Art. 288 do Código Penal

### Dicas de prova
- Diferenciar entre associação criminosa e quadrilha/bando
- Entender a noção de concurso necessário e plurissubjetivo
- Conhecer as regras de suspensão condicional e acordo de não persecução penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.256 (1)", "page_number": 256, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 288 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:29:54.281734+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=256", "doc_key": "9432b7622cf244e7bd4bf6dff5bd0b99"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e60e4534e9bd72db8a968cb6199610766634557abd43fc401892a17d2baa41b5'),
  ('cpiuris2025::f04f021068abd4f5223e0e8c43ab5187', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Associação Criminosa', '## Associação Criminosa

A associação criminosa é caracterizada pela participação de três pessoas, sendo apenas uma imputável e maior de 18 anos. O tipo penal é majorado se um dos integrantes for inimputável. A associação deve ser estável e permanente.

### Conceitos
- **Inimputabilidade**: Qualquer causa que exclua a responsabilidade do agente
- **Associatividade**: Característica estável e permanente da associação criminosa
- **Concurso de Agentes**: Ocorre quando mais de um agente é responsável pelo crime
- **Quadrilha ou Bando**: Requer ao menos quatro indivíduos para caracterização da associação criminosa

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre associação criminosa e concurso de agentes
- Importância do vínculo associativo estável e permanente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.256 (2)", "page_number": 256, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:30:29.098333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=256", "doc_key": "f04f021068abd4f5223e0e8c43ab5187"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c7d1f16ae927c20a8dcb31246069c85ac84c9aeb5667f02f877c8f639543cb56'),
  ('cpiuris2025::2060f57e34d0bd25254902882e5cad06', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Associação Criminosa', '## Associação Criminosa

O crime de associação criminosa é classificado como formal e consuma-se com a associação estável e permanente, sem necessidade de organização definida ou hierarquia entre os membros. É um delito de perigo abstrato e permanente, que incrimina a preparação de outros delitos.

### Conceitos
- **Concurso de Agentes**: Ausente a estabilidade e a permanência não há que se falar em caracterização do crime
- **Crime Formal**: Consuma-se com a associação estável e permanente, sem necessidade de organização definida ou hierarquia entre os membros
- **Delito Permanente**: A consumação se prolonga no tempo
- **Organização Criminosa**: Não é necessária organização definida, hierarquia entre os membros ou repartição de funções
- **Pena Reduzida**: O participante e o associado que denunciar à autoridade o bando ou quadrilha terá a pena reduzida de um a dois terços

### Referências legais
- Art. 288 do Código Penal
- Art. 8º da Lei n.º 8.072/1990

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Distinguir entre concurso de agentes e associação criminosa
- Entender a natureza do crime como delito permanente e de perigo abstrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.257 (1)", "page_number": 257, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 288 do Código Penal", "Art. 8º da Lei n.º 8.072/1990"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T10:31:09.890307+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=257", "doc_key": "2060f57e34d0bd25254902882e5cad06"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8918d3dcce0459b3ca280107f17cefaeed380767991f7544cf26411cff37f962'),
  ('cpiuris2025::c027bd4c6674526ef506ef9c4ce5e75f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Associação Criminosa', '## Associação Criminosa

Associação criminosa é grupo associado de pelo menos três pessoas, com estrutura mais sofisticada do que a associação criminosa, necessitando de quatro pessoas mínimas. Destina-se a práticas de infrações graves e transnacionais.

### Conceitos
- **Associação Criminosa**: Grupo associado de pelo menos três pessoas
- **Organização Criminosa**: Estrutura ilícita de poder com estrutura empresarial de gestão
- **Lei n.º 12.850/2013**: Lei que define a organização criminosa

### Referências legais
- Art. 37 da Lei n.º 12.850/2013

### Dicas de prova
- Diferenciar associação criminosa de organização criminosa
- Entender a estrutura e o modelo empresarial das organizações criminosas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.257 (2)", "page_number": 257, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 37 da Lei n.º 12.850/2013"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:31:32.477523+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=257", "doc_key": "c027bd4c6674526ef506ef9c4ce5e75f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9ef8c82846dc17a2adf0a8d0848fde3ba97f240229eced5e421e168be862a778'),
  ('cpiuris2025::4e98aab506a3a83186859e9e5a253330', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Constituição de Milícia Privada', '## Constituição de Milícia Privada

O crime de constituição de milícia particular é tipificado no art. 35 da Lei n.º 11.343/2006, com pena de reclusão de 4 a 8 anos. A ação penal é pública incondicionada. O crime é plurissubjetivo e de concurso necessário.

### Conceitos
- **Plurissubjetivo**: O crime é cometido por vários sujeitos, que se auxiliam mutuamente para alcançar o objetivo comum.
- **Concurso Necessário**: A conduta do crime é necessária para a caracterização do tipo penal.
- **Organização Paramilitar**: O crime envolve a constituição de uma organização paramilitar, que pode ser um grupo ou esquadrão.
- **Taxatividade da Lei Penal**: A lei penal deve conter definições claras e precisas para evitar insegurança jurídica.
- **Princípio da Taxatividade**: O princípio que exige que a lei penal seja clara e precisa em suas definições.
- **Lei n.º 12.850/2013**: Uma lei que estabelece o número mínimo de pessoas necessárias para caracterizar o crime.
- **Art. 288-A**: Um dispositivo legal que estabelece o número mínimo de pessoas necessárias para caracterizar a organização paramilitar.
- **Lei n.º 11.343/2006**: Uma lei que tipifica o crime de constituição de milícia particular.

### Referências legais
- Art. 35 da Lei n.º 11.343/2006
- Art. 288-A
- Lei n.º 12.850/2013

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a distinção entre plurissubjetivo e concurso necessário.
- Conheça as definições de organização paramilitar e taxatividade da lei penal.
- Aprenda com o art. 288-A e sua relação com o crime de constituição de milícia particular.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.258 (1)", "page_number": 258, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 35 da Lei n.º 11.343/2006", "Art. 288-A", "Lei n.º 12.850/2013"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T10:33:29.251180+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=258", "doc_key": "4e98aab506a3a83186859e9e5a253330"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2e120b8d91e9d6ca0d6795a73044674a2fbf8318f2d9be583208bb7801903174'),
  ('cpiuris2025::f922e965ae7aaa1e16243e39b108500c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Organizações Paramilitares', '## Organizações Paramilitares

Descreve a organização paramilitar como grupo clandestino armado com estrutura militar, utilizando táticas policiais e motivado por ilicitude, vedado pela CF. A milícia particular é um grupo de civis ou militares armados que busca restaurar ordem em comunidades dominadas pela criminalidade.

### Conceitos
- **Organização Paramilitar**: Grupo clandestino armado com estrutura militar, utilizando táticas policiais e motivado por ilicitude
- **Milícia Particular**: Grupo de civis ou militares armados que busca restaurar ordem em comunidades dominadas pela criminalidade

### Referências legais
- Art. 5º, XVII, CF/88

### Dicas de prova
- Distinção entre organização paramilitar e milícia particular
- Monopólio do Estado quanto ao uso do poder coercitivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.258 (2)", "page_number": 258, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 5º, XVII, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:33:53.524391+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=258", "doc_key": "f922e965ae7aaa1e16243e39b108500c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '809eb70544827cf45eb3a1a471f1bb21637eae598dc953d93c58be06aff8570a'),
  ('cpiuris2025::d8b28430463a626d33fff94ee442b0b0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Paz Pública', '## Crimes contra a Paz Pública

Grupos e esquadrões são agrupamentos de extermínio que buscam eliminar pessoas consideradas nocivas ou perigosas. O crime é misto alternativo, de ação múltipla ou conteúdo variado.

### Conceitos
- **Associação Criminosa**: Agrupamento estável e permanente de pessoas com o fim específico de cometer crimes.
- **Crime Formal**: Crime que se consuma no momento em que a associação é constituída, caracterizando um crime de perigo abstrato.
- **Pena Agravada**: Penalidade aumentada devido a circunstâncias específicas.
- **Crimen Involuntário**: Ato que não é intencional, mas que tem resultado penal.
- **Crime Permanente**: Ato que se prolonga no tempo e independe da prática de infração penal.
- **Ação Penal Pública Incondicionada**: Processo em que o Estado é o autor do processo.
- **Incitação ao Crime**: Ato que incita alguém a cometer um crime específico.

### Referências legais
- Art. 286 do Código Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre associação criminosa e concurso de pessoas.
- Caracterização do crime formal e permanente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.259", "page_number": 259, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 286 do Código Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:34:30.280288+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=259", "doc_key": "d8b28430463a626d33fff94ee442b0b0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '253db6c811a5b2ed3e635d42a7ddf61eac80c70b4daf93383c48d27527fa8419'),
  ('cpiuris2025::e34d2a2e9c50e180229aba7005523400', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes de Falso', '## Crimes de Falso

Lesam os interesses patrimoniais dos indivíduos, o interesse público na segurança das relações jurídicas, o privilégio monetário do Estado e os meios de prova. São crimes que incide materialmente sobre a coisa, alteração ou supressão de informações em documentos.

### Conceitos
- **Falsidade Material**: falsificação, criação de documento falso, alteração ou supressão de informações em documentos
- **Falsidade Ideológica**: documento verdadeiro com conteúdo falso, sem veracidade intelectual
- **Falsidade Pessoal**: qualificação da pessoa física, identidade civil falsa

### Referências legais
- Art. 57 do CP
- Súmula 73 do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre falsidade material e ideológica
- Entender a noção de dano potencial e sua relação com o dolo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.261", "page_number": 261, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 57 do CP", "Súmula 73 do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:35:10.842001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=261", "doc_key": "e34d2a2e9c50e180229aba7005523400"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2b02c17bafd03c0905794754bdcf4f9b8219d1b99877a3c136a4e6a25d1adf50'),
  ('cpiuris2025::0c0a17c0bff1f3f1e8963237453b41d9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra a Fé Pública', '## Crime contra a Fé Pública

O crime de estelionato é configurado pela utilização de papel moeda falsificado, sendo formal e consumindo-se no momento da contrafação. Não exige dano a terceiro, mas os prejuízos podem ser considerados na dosimetria.

### Conceitos
- **Estelionato**: Crime configurado pela utilização de papel moeda falsificado
- **Fé Pública**: Bem intangível que corresponde à confiança da população em sua moeda
- **Princípio da Insignificância**: Não é aplicável ao crime de estelionato, independentemente do número de cédulas ou valor
- **Tentativa**: Admite-se na dosimetria do crime
- **Prova Pericial**: Necessária para comprovar a materialidade delitiva

### Referências legais
- Art. 158 CPP
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo do crime de estelionato

### Dicas de prova
- Diferenciação entre os §§ 1º e 2º do artigo
- Intenção do agente no § 2º
- Princípio da proporcionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.262 (1)", "page_number": 262, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 158 CPP", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do crime de estelionato"], "confidence": 0.8, "extracted_at": "2026-05-27T10:35:45.999505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=262", "doc_key": "0c0a17c0bff1f3f1e8963237453b41d9"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7f4f680a61f739a67042e67e2dc4b0a76e8d11f86691cada2fe9ca1f50362ced'),
  ('cpiuris2025::3e09ca77c344cc1789851d4f08bc0887', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsificação de Moeda', '## Falsificação de Moeda

A falsificação de moeda é crime que envolve a fabricação, emissão ou autorização da fabricação ou emissão de moeda com título ou peso inferior ao determinado em lei. A conduta é mais grave se for cometida por um gerente ou fiscal de banco de emissão.

### Conceitos
- **Falsificação funcional**: Conduta que exige qualidade especial do sujeito ativo
- **Moeda falsa**: Moeda com título ou peso inferior ao determinado em lei
- **Emissão de moeda**: Ato de emitir moeda

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- HC 96153/MG

### Dicas de prova
- Distinguir entre falsificação funcional e emissão de moeda
- Entender a competência para processar e julgar o crime de moeda falsa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.262 (2)", "page_number": 262, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "HC 96153/MG"], "confidence": 0.8, "extracted_at": "2026-05-27T10:36:10.653454+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=262", "doc_key": "3e09ca77c344cc1789851d4f08bc0887"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4cf48defa3d6c653c9144e4eb21d5d847df4bc7d4e5d6c944e51a20a18bb456b'),
  ('cpiuris2025::d064d07393ce5ff09a66a5e5f27e27dc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Fé Pública', '## Crimes contra a Fé Pública

Delitos relacionados à falsificação de moeda, incluindo crimes contra a fé pública e petrechos para falsificação de moeda.

### Conceitos
- **Falsificação**: Ação de criar ou alterar documentos ou objetos para fazê-los parecerem autênticos
- **Crimes contra a Fé Pública**: Delitos que visam prejudicar a confiança pública em instituições e funcionários públicos
- **Petrechos para falsificação de moeda**: Objetos ou maquinário destinados à criação de moedas falsas

### Referências legais
- Art. 28-A do CPP
- Art. 291 do CP

### Jurisprudência
- Súmula 73 do STJ

### Dicas de prova
- Entenda a distinção entre crimes contra a fé pública e petrechos para falsificação de moeda
- Conheça as condutas delituosas previstas nos arts. 263 e 291 do CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.263 (1)", "page_number": 263, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 28-A do CPP", "Art. 291 do CP"], "jurisprudence": ["Súmula 73 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T10:36:51.176280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=263", "doc_key": "d064d07393ce5ff09a66a5e5f27e27dc"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '910d959f0194c509d55c7284d9f4f46c7770ccdf9dd9c86a0def6f55441d3f25'),
  ('cpiuris2025::84f94a6621a76d489ea2fdbffe62c3ac', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Característica intrínseca ou inerente do objeto', '## Característica intrínseca ou inerente do objeto

A característica intrínseca de um objeto determina a possibilidade de consumação do crime, não o maquinário utilizado.

### Conceitos
- **característica intrínseca**: propriedade inerente ao objeto
- **elemento subjetivo**: análise do dolo do agente

### Referências legais
- Art. 25, § 2º, CP

### Jurisprudência
- STJ. REsp 1.758.958-SP
- ...

### Dicas de prova
- Diferenciar entre a característica intrínseca e o maquinário utilizado.
- Analisar o elemento subjetivo do tipo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.263 (2)", "page_number": 263, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 25, § 2º, CP"], "jurisprudence": ["STJ. REsp 1.758.958-SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T10:37:10.074709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=263", "doc_key": "84f94a6621a76d489ea2fdbffe62c3ac"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '553808725f0a660120c14d3e5c212cdde39c979ceb71a6a9732188853259d282'),
  ('cpiuris2025::0bec08ad32f64983c1c73ea526324aa4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Fé Pública', '## Crimes contra a Fé Pública

Resumo do artigo sobre crimes contra a fé pública, incluindo emissão de título ao portador e falsificação de documentos públicos.

### Conceitos
- **Falsificação**: Ação de criar ou alterar documentos públicos com o objetivo de enganar ou prejudicar alguém.
- **Emissão de título ao portador**: Emitir documento que promete pagamento em dinheiro ao portador, sem indicação do nome da pessoa a quem deve ser pago.
- **Crimes contra a fé pública**: Tipos de crimes que prejudicam a confiança da população na emissão de documentos públicos.

### Referências legais
- Art. 289
- Art. 292
- Art. 293

### Dicas de prova
- Diferenciar entre a emissão de título ao portador e a falsificação de documentos públicos.
- Conhecer as hipóteses de crimes contra a fé pública e seus respectivos tipos penais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.264", "page_number": 264, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 289", "Art. 292", "Art. 293"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:37:41.040758+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=264", "doc_key": "0bec08ad32f64983c1c73ea526324aa4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f3dc960f58b66140e5c20797dbbd68639cb45701e5a74b0955375fa14fb8db63'),
  ('cpiuris2025::31580daed3196237419f1a0c40aac98a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Fé Pública', '## Crimes contra a Fé Pública

O crime contra a fé pública é o artigo que prevê a falsificação de documentos públicos, lesionando a confiança e legitimidade dos papéis públicos.

### Conceitos
- **Falsificação**: reproduzir, imitar ou modificar um documento público
- **Bem jurídico tutelado**: a fé pública, confiança e legitimidade dos papéis públicos
- **Sujeito ativo**: pessoa que comete o crime
- **Sujeito passivo**: o Estado
- **Crime formal**: crime em que a conduta já expõe o bem jurídico tutelado a perigo

### Referências legais
- Art. 295
- Art. 17 do CP

### Dicas de prova
- Diferenciar entre falsificação grosseira e impossível
- Entender o conceito de bem jurídico tutelado
- Identificar o sujeito ativo e passivo no crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.265 (1)", "page_number": 265, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 295", "Art. 17 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:38:22.665618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=265", "doc_key": "31580daed3196237419f1a0c40aac98a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '50e7cddfa28ae2544d6c163b48f1fc896de8bbd56cdc12d0e35705ad5c92a19a'),
  ('cpiuris2025::f1dec9c27eb509d2eac2bdd668aea58f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsificação de documentos', '## Falsificação de documentos

Verifica-se o crime de falsificação de documentos, onde o indivíduo utiliza em proveito próprio ou alheio produtos ou mercadorias no exercício de atividade comercial ou industrial. O crime é próprio e tem pena de reclusão de um a quatro anos e multa.

### Conceitos
- **Falsificação**: Ação de alterar ou modificar documentos para obter vantagem
- **Propósito próprio**: O indivíduo utiliza o documento para obter benefício pessoal
- **Propósito alheio**: O indivíduo utiliza o documento para obter benefício de terceiro
- **Fim de agir**: A intenção do indivíduo ao cometer o crime

### Referências legais
- Art. 243, inciso III do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre uso próprio e uso alheio
