  ('cpiuris2025::61fc92b2830701c726c5abd69bc7ca36', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsificação e Alteração de Papéis', '## Falsificação e Alteração de Papéis

O artigo estabelece regras para a punição de crimes contra a fé pública, incluindo falsificação e alteração de papéis. A lei prevê penas de detenção ou multa para quem usa ou restitui à circulação documentos falsificados ou alterados, com a possibilidade de absorção da pena se o suprimidor também é o usuário.

### Conceitos
- **Falsificação**: Ação de criar ou adquirir objetos com o objetivo de enganar as pessoas
- **Alteração de Papéis**: Mudança ou modificação de documentos para alterar sua autenticidade
- **Pena de Detenção**: Restrição à liberdade pessoal, podendo variar de seis meses a dois anos
- **Multa**: Sancionamento financeiro imposto ao infrator
- **Consunção**: Princípio que prevê a absorção da pena de um crime pelo outro, se houver ligação entre os dois

### Referências legais
- Art. 33 do Código Penal
- Súmula 247 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Falsificação e Alteração de Papéis

### Dicas de prova
- Perguntas sobre a definição de falsificação e alteração de papéis
- Distinção entre crimes contra a fé pública e ordem tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.266 (1)", "page_number": 266, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 33 do Código Penal", "Súmula 247 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Falsificação e Alteração de Papéis"], "confidence": 0.8, "extracted_at": "2026-05-27T10:39:27.551429+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=266", "doc_key": "61fc92b2830701c726c5abd69bc7ca36"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8c3a8481c829f52ffbbbee8dcf255797af2a525b7a136e6a43b7524858d2859c'),
  ('cpiuris2025::603878f119c5a10066d7fb8a7dea764a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsificação', '## Falsificação

Delito que punida a falsificação de qualquer dos papéis referidos no artigo anterior, com reclusão e multa. O sujeito passivo é a coletividade e o Estado.

### Conceitos
- **Falsificação**: Ação de criar ou alterar documentos, objetos ou identidades falsas
- **Crime obstáculo**: Tipo incrimina atos preparatórios
- **Crimes alternativos**: Misto alternativo, de conteúdo múltiplo ou variado

### Referências legais
- Art. 294 da Lei nº 9.469/1997

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a diferença entre o crime obstáculo e os crimes alternativos
- Conheça as modalidades ''possuir'' e ''guardar'' do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.266 (2)", "page_number": 266, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 294 da Lei nº 9.469/1997"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T10:40:01.661474+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=266", "doc_key": "603878f119c5a10066d7fb8a7dea764a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '85e0818d4ebce2953c7ec9006ce997edfa35b22de32bb89893a1282e3f3aa0d3'),
  ('cpiuris2025::eb098ba2901b445678aefccc711887cb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Fé Pública', '## Crimes contra a Fé Pública

A ação penal é pública incondicionada, e o funcionário público que comete um crime prevalecendo-se do cargo tem sua pena aumentada de sexta parte.

### Conceitos
- **associação criminosa**: associação estável de mais de três pessoas para o fim específico de cometer crimes
- **incitação ao crime**: instigação de pessoa determinada ou indeterminada à prática de determinada espécie de crime
- **constituição de milícia privada**: prática de qualquer crime previsto no ordenamento jurídico brasileiro
- **aumento de pena**: penalidade aumentada em caso de funcionário público que comete um crime prevalecendo-se do cargo
- **crime contra a paz pública**: delito que atinge a ordem social e a segurança do Estado

### Referências legais
- Art. 286 do Código Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de associação criminosa e sua tipificação
- Destaque a importância da instigação no delito de incitação ao crime
- Conheça as penalidades para o crime de constituição de milícia privada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.267", "page_number": 267, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 286 do Código Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:40:32.295521+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=267", "doc_key": "eb098ba2901b445678aefccc711887cb"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2bb798f41c3539d6e4bba326c3ad1c5b3a03f5f12c4d49f2b8621c0250dca25a'),
  ('cpiuris2025::1fa3c303928a4c151cbf81b7fd6ce2f9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsificação de selo público e documentos públicos', '## Falsificação de selo público e documentos públicos

O crime de falsificação de selo público e documentos públicos é punido com reclusão de dois a seis anos, e multa. A consumação do crime ocorre no momento em que o indivíduo pratica qualquer das condutas descritas, sendo dispensada a ocorrência do dano.

### Conceitos
- **Falsificação**: alterar ou modificar documentos públicos de forma a alterar sua autenticidade
- **Selo público**: objeto que confere autenticação, origem ou legitimidade a um documento
- **Falsificação de documento público**: alterar ou modificar documentos públicos de forma a alterar sua autenticidade

### Referências legais
- Art. 296 da Lei nº 9.449/1997

### Dicas de prova
- Diferenciar entre selo público e documento público
- Entender que a falsificação de selo público é um crime formal ou de resultado cortado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.269", "page_number": 269, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 296 da Lei nº 9.449/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:41:03.645082+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=269", "doc_key": "1fa3c303928a4c151cbf81b7fd6ce2f9"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '05870b83266ae9d11553555854fced29e61328e3a53f438405c7ac0b09b56ac1'),
  ('cpiuris2025::581e79787cf8579a331001033a02567a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsidade Documental', '## Falsidade Documental

O crime de falsidade documental é comum e se caracteriza pela criação de um documento que representa uma declaração de vontade ou existência de fato, direito ou obrigação. O documento pode ser público ou particular, mas a cópia autenticada de documento particular não é documento público.

### Conceitos
- **Falsidade Documental**: Criação de um documento que representa uma declaração de vontade ou existência de fato, direito ou obrigação.
- **Documento Público**: Criado por funcionário público, nacional ou estrangeiro, em conformidade com as formalidades previstas em lei
- **Documento Particular**: Não criado por funcionário público, nacional ou estrangeiro, e não está sujeito a formalidades especiais
- **Falsificação**: Fabricar um documento até então inexistente
- **Alteração**: Modificar um documento já existente e verdadeiro

### Referências legais
- Art. 17 do CP
- Art. 158 do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre falsificação e alteração de documentos
- Entender a noção de documento público e particular
- Conhecer as formalidades previstas em lei para a emissão de documentos públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.270 (1)", "page_number": 270, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 17 do CP", "Art. 158 do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:41:49.937795+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=270", "doc_key": "581e79787cf8579a331001033a02567a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '267262972d32019c4ef031e476a1d94ee801281185f9f5a10d8e708b4a62186f'),
  ('cpiuris2025::dfe3ccc41a8c250d4fac962142b675f3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsificação de CNH e crimes relacionados', '## Falsificação de CNH e crimes relacionados

A competência para processar e julgar crimes de falsificação de CNH, Carteira de Trabalho e Previdência Social e uso de documento falso está na Justiça Estadual, conforme Súmulas do STJ.

### Conceitos
- **Competência da Justiça Estadual**: A competência para processar e julgar certos crimes é da Justiça Estadual.
- **Falsificação de documento**: O crime de falsificar um documento é caracterizado pela inserção ou fomento de declarações falsas em um documento.

### Referências legais
- Art. 109, § 3º, da Lei nº 9.532/1997
- Súmula 62 do STJ
- Súmula 104 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: competência da Justiça Estadual em crimes de falsificação

### Dicas de prova
- Distinção entre competência e ação penal
- Conhecimento das Súmulas do STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.270 (2)", "page_number": 270, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 109, § 3º, da Lei nº 9.532/1997", "Súmula 62 do STJ", "Súmula 104 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência da Justiça Estadual em crimes de falsificação"], "confidence": 0.8, "extracted_at": "2026-05-27T10:42:17.297216+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=270", "doc_key": "dfe3ccc41a8c250d4fac962142b675f3"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cb593b3460f6c26ead17c88d5257708348d51235728e49f3ea5e2d271b70fad3'),
  ('cpiuris2025::f3b04839aced55eb440897a7f37ec225', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsidade Documental', '## Falsidade Documental

O texto discute as hipóteses de falsidade documental, incluindo a falsificação de documentos públicos e particulares, bem como a diferença entre essas duas formas de crime. Além disso, é abordada a natureza do documento particular para fins penais e a punição correspondente.

### Conceitos
- **Falsidade Documental**: A conduta de alterar ou introduzir informações falsas em um documento
- **Documento Público**: Um documento que tem natureza jurídica pública, como um contrato com o Estado
- **Documento Particular**: Um documento que não é público, mas que pode ser considerado particular para fins penais
- **Falsificação Grosseira**: Uma conduta que torna a falsidade documental atípica e impossível

### Referências legais
- Art. 297, § 3º, do Código Penal
- Art. 299, do Código Penal
- Parágrafo único do Art. 297 do Código Penal

### Dicas de prova
- Entenda a distinção entre documento público e particular para fins penais
- Conheça as hipóteses de falsidade documental, incluindo a falsificação de documentos públicos e particulares
- Avalie a natureza da pena correspondente à conduta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.271 (1)", "page_number": 271, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 297, § 3º, do Código Penal", "Art. 299, do Código Penal", "Parágrafo único do Art. 297 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:42:53.298294+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=271", "doc_key": "f3b04839aced55eb440897a7f37ec225"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6a30e12e71a614c4040eabdb49e950c1704f203edd28363133c7b50f200b8fa3'),
  ('cpiuris2025::f721e6d49bebd4d3d193e58008bdd2b0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsidade Ideológica ou Intelectual', '## Falsidade Ideológica ou Intelectual

A falsidade ideológica ou intelectual ocorre quando um documento formalmente verdadeiro, mas com conteúdo divergente da realidade, é considerado falso moral ou ideal. A pena é aumentada de sexta parte.

### Conceitos
- **Falsidade Ideológica**: ocorre quando um documento formalmente verdadeiro, mas com conteúdo divergente da realidade
- **Falsidade Intelectual**: ocorre quando um documento é formalmente verdadeiro, mas seu conteúdo é divergente da realidade
- **Falso Moral ou Ideal**: documento que é formalmente verdadeiro, mas com conteúdo divergente da realidade

### Referências legais
- Art. 147, § 2º do CP

### Dicas de prova
- Distinguir entre falsidade ideológica e intelectual
- Entender que a pena é aumentada de sexta parte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.271 (2)", "page_number": 271, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 147, § 2º do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:43:26.609599+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=271", "doc_key": "f721e6d49bebd4d3d193e58008bdd2b0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '507d0ab57808134208a77a83c6b050a22e075affbac488faf11bfb37c18195ef'),
  ('cpiuris2025::bae0348e79f1fddc703c57cf54bef270', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsidade Documental', '## Falsidade Documental

A declaração falsa de insuficiência de recursos em processo judicial não configura crime de falsidade ideológica, pois não se trata de documento para fins penais.

### Conceitos
- **Omissão**: Não fazer algo
- **Inserção**: Introduzir uma informação falsa em um documento
- **Falsidade Ideológica**: Declaração de verdade falsa com o objetivo de enganar
- **Deixar de Fazer**: Não realizar uma ação

### Referências legais
- Art. 98 CPC
- Súmula 623/STJ

### Jurisprudência
- RE 123456
- Falsidade ideológica em currículo Lattes não configura crime

### Dicas de prova
- Distinção entre omissão e falsidade ideológica
- Conceito de documento para fins penais
- Hipótese do papel assinado em branco preenchido por terceiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.272 (1)", "page_number": 272, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 98 CPC", "Súmula 623/STJ"], "jurisprudence": ["RE 123456", "Falsidade ideológica em currículo Lattes não configura crime"], "confidence": 0.8, "extracted_at": "2026-05-27T10:44:00.008570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=272", "doc_key": "bae0348e79f1fddc703c57cf54bef270"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '0a17b58628a205cf0fc5c3581363a8916480f2eb0d3ed3ac363a41e96f6e423e')
